  '材料-22',
  '材料-22',
  '企业公布的财务信息反映了企业的经营和运营状况。毛利润、运营利润和净利润是通常使用到 的指标。毛利润通常是企业营业收入除去营业成本（如原材料、设备等生产成本和营业税等）后 的收入，运营利润是毛利润减去运营成本费用（如员工工资、管理费用、研发费用、销售费用、 财务费用）后的收入，净利润是企业运营利润加其他收入之后减去所得税额之后的收入。运营利 润，在其他收入(营业外收入)之前，反映了企业基本经营活动获得利润的能力。下表是A公司去 年和今年的运营信息，请根据相关信息回答问题。按照营业收入来计算，A公司今年的人均差 值与去年相比：',
