  '材料-180',
  '在互联网的普及下，人们的生活方式发生了变化，对于农产品、食品、医药等消费品的选购方 式也变的越来越便利。对于网购、生鲜电商、蔬果宅配等来说，运输环节十分重要。受益于这 类消费的增长，国内冷链物流市场也快速发展。数据显示：2019年，我国冷链物流行业的市场规 模约3391亿元，据中商产业研究院预测，到2020年，我国冷链物流行业市场规模将突破4000亿 元。根据材料和图表回答下列问题。假如2016年我国冷链物流行业市场规模同比增长了4%， 那么2015年我国冷链物流行业市场规模约占2019年我国冷链物流行业市场规模的（）。',
