(
  '文字-1',
  '文字-1',
  '文件内容较多,搜索之前先打开缓存一会 ,等待加载完毕。 1 高新科技成果转化为生产力,有一个客观的转化过程。从基础理论到技术研究,进而设计、开发、研制出样品、样机,从试验或小批生产到建立经济规模的生产及相应的经营管理和销售服务,高科技成果转化成为具有使用价值和经济效益的社会生产力,要经过许多环节,要做大量具体的转化工作。其中,应特别注意的是必须切实解决经济规模生产的工艺问题。 对这段话最准确的复述是:',
  null,
  '{"A":"高新科技成果转化为生产力要经许多环节和做大量具体的转化工作","B":"解决经济规模生产的工艺问题是高新科技成果转化为生产力的首要任务","C":"解决经济规模生产的工艺问题与设计、开发等问题同等重要","D":"高新科技成果转化为生产力要做许多具体工作,主要包括解决经济规模生产的工艺问题"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '第一步,分析文段。首先提出"高新科技成果转化为生产力"有一个转化过程,接着详细介绍了转化过程各个环节的转化工作。最后通过"其中""特别注意""必须"指出除了以上的转化工作,要特别注意"经济规模生产的工艺问题"。第二步,对比选项。D项是对文段主旨的同义替换。因此,选择D选项。要点:A项:没有强调高新科技成果转化为生产力需要解决经济规模生产的工艺问题,偏离重点。B项:"首要任务"无中生有。C项:没有提及"高科技成果转化为生产力",偏离重点。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
