  '文字推理',
  '中心理解题',
  '["做题辅助-对策词"]'::jsonb,
  '北森言语理解',
  null,
  1,
  '{"kind":"verbal","analysisSource":"原题解析","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-2',
  '文字-2',
  '虽然春节、清明、端午和中秋都被称为中国四大传统节日,不过与其他三个相比,中秋要年轻许多,直到宋代才以"节日"的姿态示人。在中国的四大传统节日中,春节是资格最老的。虽然将正月初一定为春节是民国成立以后的事了,但是这个节日本身历史久远保守估计也已经在中国走过了三千年的历程。四大传统节日中排行第二的是端午节。 端午节起源于先秦,而最终形成独立节日则是在汉魏时期。相比较之下,清明节比中秋节略年长些虽然有关清明从节气演变到节日的起源,一般会提到春秋时晋文公重耳和其忠臣介子推的传说但传说终归是传说清明节的最终生成则是在中国历史上最为辉煌的大唐。 下面对文本内容理解正确的一项是',
  null,
  '{"A":"中秋节在宋代以前就已经中国的节日了。","B":"口端午节在先秦时期已形成独立节日。","C":"清明节与春秋时晋文公重耳和其忠臣介子推的传说未必有关。","D":"中秋节的最终是在中国历史上最为辉煌的大唐形成独立节日的。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '由题意可知:中秋要年轻许多,直到宋代才以"节日"的姿态示人。所以A错误。端午节起源于先秦,而最终形成独立节日则是在汉魏时期。所以B错误。一般会提到春秋时晋文公重耳和其忠臣介子推的传说但传说终归是传说清明节的最终生成则是在中国历史上最为辉煌的大唐。所以C对,B错。所以答案选C。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
