(
  '文字-3',
  '文字-3',
  '每个人在学习新事物时都会有恐惧、畏难的心态,但如果因此而( ) ,那我们就永远也学习不到新知识。 填入括号内最恰当的词语是:',
  null,
  '{"A":"因噎废食","B":"瞻前顾后","C":"首鼠两端","D":"视为畏途"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '题中意思是每个人对学习新事物都会害怕,但如果就此害怕学习,就永远也学不到新知识。因噎废食:因为吃饭噎住了,索性连饭也不吃了。瞻前顾后:形容顾虑过多,犹豫不决。形容迟疑不决或动摇不定。视为畏途:比喻把事情看得艰难可怕,而不敢去做。所以答案选D。',
  '先判断上下文逻辑关系，再比较词义、感情色彩、程度和固定搭配。 本题重点：题干逻辑-对应关系。',
