),
(
  '文字-4',
  '文字-4',
  '生长在水中或水边的动植物的遗体是最易被保存下来的,因为保存动植物遗体的必要条件是快速掩埋,而在淤泥不断淤积的海洋、河流乃至湖泊中,动植物的遗体以及其他东西能够被快速掩埋。 这段话主要支持了这样一种观点,即:',
  null,
  '{"A":"动植物遗体很容易在淤泥不断淤积的海洋、河流乃至湖泊中保存下来","B":"只有生长在水中或水边的动植物的遗体才能被保存下来","C":"淤泥不断淤积的海洋、河流乃至湖泊是保存动植物遗体的最佳环境","D":"只要被快速掩埋,动植物遇体就能被保存"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '本题考查的是考生对关键词语的把握能力。文章是解释为什么“生长在水中或水边的动植物的遗体是最易被保存下来”,所以答案为A。开头一句话的“最”字,是需要考生把握的,由此选择A,A说“很容易”,与原文程度相符。B“只有”犯了绝对化的错误,“最容易”不代表“只有”。其他地方仍然可能保存动植物的遗体。C项中的“最佳”错误。D选项和题干矛盾.题干说的是“快速掩埋”是“保存动植物遗体”的必要条件。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-主题词。',
  '入门',
