),
(
  '文字-5',
  '文字-5',
  '教育上"谁受益、谁出钱"这一提法如果是正确的话,只能理解为国家是教育的最大受益者。这是因为一方面,教育的经济效益,虽然不能直接、立即体现在市场经济交换过程中,却存在于社会之中:另一方面,教育不仅有经济效益,而且是国家综合国力的重要组成部分。因此: ( )',
  null,
  '{"A":"教育经费主要由国家承担是合理的","B":"教育经费应由个人,社会与国家共同承担","C":"个人是教育的次要受益者,所以应该承担相当大部分的教育经费","D":"应该实行由幼儿园到大学的免费教育"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '由题意可知:国家是教育的最大受益者。教育上"谁受益、谁出钱"这一提法如果是正确。教育经费主要由国家承担是合理的。所以答案选A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
