  5,
  '{"kind":"verbal","analysisSource":"原题解析","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-6',
  '文字-6',
  '父亲忽然看见两位先生在请两位打扮得漂亮的太太吃牡蛎。一个衣服褴楼的年老水手拿小刀一下撬开牡蛎,递给两位先生,再由他们递给两位太太。她们的吃法很文雅,用一方小巧的手帕托着牡蛎,头稍向前伸,免得弄脏长袍;然后嘴很快地微微一动,就把汁水吸进去,蛎壳扔到海里。毫无疑义,父亲是被这种高贵的吃法打动了,走到我母亲和两个姐姐身边问:"你们要不要我请你们吃牡蛎? "母亲有点迟疑不决,她怕花钱;但是两个姐姐赞成。母亲于是很不痛快地说:"我怕伤胃,你只给孩子们买几个好了,可别太多,吃多了要生病的。"然后转过身对着我,又说: "至于 若瑟夫,他用不着吃这种东西,别把男孩子惯坏了。" 父亲请家人吃牡蛎的动机是:',
  null,
  '{"A":"想请家人品尝牡蛎的鲜味道","B":"借机摆出高雅的绅士风度","C":"羡慕别人吃牡蛎的动作","D":"想力法为家人的旅游助兴添乐"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '逐项对照原文，B项“借机摆出高雅的绅士风度”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择B。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
  '提高',
  '文字推理',
  '细节判断题',
  '["信息核对-定位原文"]'::jsonb,
  '北森言语理解',
  null,
  6,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-7',
  '文字-7',
  '经济学应具有伦理的方法,伦理学也可引进经济学的方法。伦理学与经济学之所以有相通之处,可以相互联系、相互引进,是由人们的经济行为和道德行为本身相互关联决定的。例如在工业生产中,人们的创造能力不仅取决于知识和技术水平,也取决于是否肯于奉献的道德水平。 这段文字旨在告诉我们:',
  null,
  '{"A":"经济学为何与伦理学有相通之处","B":"经济学与伦理学是相互联系,相互引进的","C":"经济学与伦理学的关系","D":"经济学与伦理学的方法是相通的"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '首句为中心句,第二句为解释说明原因,第三句为例子解释。即文段中心:经济学与伦理学之间有联系,能互相引进。选B。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-因果关系。',
