  '中心理解题',
  '["关联词语-因果关系"]'::jsonb,
  '北森言语理解',
  null,
  7,
  '{"kind":"verbal","analysisSource":"原题解析","duplicateOccurrences":[531]}'::jsonb
),
(
  '文字-8',
  '文字-8',
  '人们通常把个人成长看作是容易识别和衡量的外在行为表现,例如青年不痴迷于游戏,学生掌握了一门新语言等。 这些都是付出努力之后取得成绩的行为表现。相比之下,从过程的角度,测量成长就较为困难了。它像是一次旅行,不是路上的里程碑,是当人遇到新体验或困难时所持的态度和情感。从这个意义上来说,成长的过程没有真正的尽头,因为新挑战和新体验随时都会发生。 由材料推论,一个人如果被大家认为取得了成长,通常是因为:',
  null,
  '{"A":"在工作中很努力","B":"克服掉了抽烟的习惯","C":"渴望学习新的事物","D":"不断接受挑战"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '文中“人们通常把个人成长看作是容易识别和衡量的外在行为表现,例如青年不痴迷于游戏,学生掌握了一门新语言等”。 问题是“一个人如果被大家认为取得了成长”,被大家认为,那么也就是行为表现,B项符合',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
  '入门',
  '文字推理',
  '细节判断题',
  '["信息核对-定位原文"]'::jsonb,
  '北森言语理解',
  null,
  8,
  '{"kind":"verbal","analysisSource":"原题解析","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-9',
  '文字-9',
  '陌生人社交平台引发了荷尔蒙经济的热潮,之所以如此是因为由荷尔蒙引起的欲望本就存在于人性中, 经验告诉我们,所有基于人性的生意都是刚需,并且长久不衰。尤其是在中国市场,人们既被传统思想束缚,表面上必须遵守许多规矩,尤其是伦理与道德的标准,但也许正是因为这样,被压抑的荷尔蒙才更容易刺激人们做一些不那么遵守规则的事情。所以,陌生人社交提供给荷尔蒙经济一个极好的发展平台,在这个平台中,荷尔蒙可以被无限次消费,而且收益惊人。以陌陌为例,去年第四季度,陌陌的付费用户达到390万人,季度净增人数30万.在第四季度增值业务的营收中,陌陌的收入为4.99亿元,余下的则是探探创造的2.23亿元。 下面最适合本文的标题是:',
  null,
  '{"A":"荷尔蒙经济热潮","B":"陌生人社交平台收益惊人","C":"荷尔蒙经济的推手——陌生人社交平台","D":"消费荷尔蒙的时代"}'::jsonb,
  '{}'::jsonb,
