(
  '文字-10',
  '文字-10',
  '在美国,目前官方认为肥胖是一种疾病。这可将人们从超重带来的精神负罪感中解脱出来。但也可能让有些人会放弃减肥。 节食本身并不一定有效。有很多饮食的倡导者们会声称某种饮食方式明显减轻了体重。节食效果可能是真实的,但是几乎没什么意义,除非知道节食的人中体重减轻的的占百分之几,以及保持了多久。 最成功的治疗需要改变生活方式。研究发现,每天至少饮用一杯软饮料的人比其他人更易超重。原因之一是几乎所有软饮料都用果糖添加甜味,而果糖不能像其他糖那样多地增加胰岛素或瘦素,使人获得卡路里却没有饱足感。 另一个选择是减肥药。虽然大多减肥药能降低进食量,阻止肠道吸收脂肪,但也存在副作用。 最后,还有一种选择是进行胃分流术。通过手术减少胃的容积,使少量进食即可产生饱足感,但会使人遭受感染、肠梗阻等。手术只是在重度肥胖的情况下值得考虑。 根据本文观点,下列观点正确的是:',
  null,
  '{"A":"面对超重时,我们可以选择食用安全无副作用的减肥药来减轻体重。","B":"进行胃分流术虽然可以减少进食,控制食物的进入,但是产生的消极影响太多,因此不能用于控制体重。","C":"节食可能的确有利于减轻体重, 但是我们要根据自身的实际情况来进行判断。","D":"如果我们饮用不添加果糖的饮料,体重就能够得到控制。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '由题意可知:另一个选择是减肥药。虽然大多减肥药能降低进食量,阻止肠道吸收脂肪,但也存在副作用。题中并未提到由安全无副作用的减肥药,所以A错。还有一种选择是进行胃分流术。通过手术减少胃的容积,使少量进食即可产生饱足感,但会使人遭受感染、肠梗阻等。胃分流手术可能会控制体重,但可能会产生消极影响。所以B错。每天至少饮用一杯软饮料的人比其他人更易超重。原因之一是几乎所有软饮料都用果糖添加甜味,而果糖不能像其他糖那样多地增加胰岛素或瘦素,使人获得卡路里却没有饱足感。文中写的是原因之一是,可能软饮料中还有其他原因。所以答案选C。',
