(
  '文字-11',
  '文字-11',
  '怀旧一词来自希腊词"回家"和"疼痛"的结合,意为"思念家而带来的疼痛"。它被用来描述在奔波于异乡的商人身 上的思乡综合症:心率不齐、啜啼、疲倦而且毫无食欲。怀旧被认为是一种多愁善感、难以消除的消极情绪。但怀旧也具有积极的心理功能,怀旧感被激发的人比普通人更愿意为慈善基金服务,并捐赠更多金钱。在这个过程中,怀旧启动了同情心,让人们对他人的处境感同身受,从而增加了人们的捐赠行为好在下面哪种广告语中,人们更愿意为地震地区的儿童捐款:',
