  '文字-13',
  '从哲学的角度看,不可否认原始儒家思想中存在很多人性的光辉,而从历史的角度看,儒家思想世俗化之后建构的传统文化,最明显的缺陷就在于没有提供一种包含起码的人道主义精神的底线伦理。当我们在批判传统文化和创造新文化的时候,应该在人道主义的框架内建立一种起码的道德底线。 这段文字的主旨是:',
