(
  '文字-14',
  '文字-14',
  '我们的一些科普文章常常激不起公众的兴趣,原因之一便是枯燥。 要把科普文章写得"郁郁乎文哉",就需要作家的笔。科学的飞速发展,为文学写作提供了一座富矿。相信有眼光的文学家一旦领略科学题材的广 阔富饶,便会陶醉在它的无限风光中乐而忘返。 这段文字谈论的是:',
  null,
  '{"A":"科普文章对作家的依赖","B":"科学和文学的互相激励作用","C":"科学和文学互相依赖","D":"科学发展为文学提供了丰富的素材"}'::jsonb,
  '{}'::jsonb,
