(
  '文字-15',
  '文字-15',
  '群众的眼睛是雪亮的,但如果缺乏足够的引导和约束,这种"雪亮"有可能变成一种偏执,一种没有方向的自负。而建立在"多数人"压过"少数人"基础上的制度安排,很可能走进片面和褊狭的陷阱中。"上级"评议,官员面对的是"一个人","公众"评议,官员面对的是"一群人",只有在"顶天"的压力和"立地"的责任互相补充下才能真正起到足够的监督作用。自上而下与自下而上的监督力量有机地结合,才可能在博弈中避免"一个人"的片面和"一群人"的片面。 这段文字的主旨是:',
  null,
  '{"A":"质疑群众评议的合理性","B":"群众的意志要得到合理的引导和约束","C":"如何对官员进行有效的监督","D":"怎样在群众和上级间达到平衡"}'::jsonb,
  '{}'::jsonb,
