  '文字-16',
  '文字-16',
  '人们为保护海龟采取了一系列措施, 例如使用全球定位系统追踪他们的行踪、志愿者主动把孵化的幼龟送到海边、政府出面保护海龟的产卵场等。研究人员使用卫星设施跟踪海龟的迁移情况,试图弄清这些海龟常常穿越广阔海域洄游数干公里的原因,以让保护海龟措施的制定更加科学。这类定位跟踪研究能更清晰地认识海龟的活动规律,例如海龟在产卵期要产五六窝卵,每产窝卵需要回到海中休息半个月,一旦知道海龟在产卵间隙回到海洋休息的活动范围,就可以确切地知道保护区范围应该有多大才合适;又如海龟产完卵后会去哪里?会走一条什么样路线?这些研究成果会让我们更明确应在哪些区域保护海龟。但是自然对人类公平的理念却漠不关心。实际上,如果没有额外的保护,海龟很有可能会永远消失。 由材料可以推论出:',
  null,
  '{"A":"人类的活动改变了海龟的存活方式","B":"人为地干预生态系统导致了海龟的灭绝","C":"人们已经做出了防止海龟灭绝的努力"}'::jsonb,
