(
  '文字-17',
  '文字-17',
  '对于身边大多数物品,比如一把椅子, 无论如何放置,人类都可以轻易识别。然而脸却不同,当照片中出现两张正置的面孔,即使非常相似,我们也可以轻而易举地指出两张脸的差异。但如果面孔是倒置的,找出不同就有些困难,这种现象称为面孔识别效应。这是因为大脑有一个特定识别面孔的区域, 当面部上下颠倒时,大脑会通过识别物体的通路来识别图像,而不再使用面孔识别通路。人们一直认为"面孔倒置效应"是哺乳类动物独有的,仅在灵长类生物与绵羊中被观测到。但最近一项发现表明日本田鱼似乎也有这种效应。日本田鱼,又称青鲋鱼,生性喜欢社交,因此正确识别其他个体对它们来说非常重要。为了探究青鏘鱼对颠倒的面孔的辨识能力,研究人员们使用棱镜对鱼的面孔进行垂直或水平翻转,测试雌鱼对各种翻转面孔的识别能力。令人惊讶的是,青终鱼也表现出"面孔倒置效应",这项发现表明鱼与人类类似,可能有特定的加工面孔的脑机制。 以下哪项内容在材料中没有提及到?',
  null,
  '{"A":"人们通常认为面孔识别效应是哺乳类动物独有的。","B":"倒置的面孔会通过识别物体的通路来被认知。","C":"当面孔方向与预期不一致时,社会信息就减弱。","D":"面孔识别效应有特定的脑机制。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '由题意可知:人们一直认为"面孔倒置效应"是哺乳类动物独有的,仅在灵长类生物与绵羊中被观测到。所以选项A对。当面部上下颠倒时,大脑会通过识别物体的通路来识别图像,而不再使用面孔识别通路。所以选项B对。这是因为大脑有一个特定识别面孔的区域。所以选项D对。C选项的内容题中并未提到。所以答案选C。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-无中生有。',
