(
  '文字-19',
  '文字-19',
  '公众宣传是一种为吸引公众的注意而在各类传播媒体上发布有关个人、团体或产品的信息的宣传方式。公众宣传有较大优势,如它的信息传播没有空间成本,可信度高等。新闻报道就是公众宣传的一种形式,读者乐于将报道的独立性与客观性相联系,认为新闻报道更有可信度。但不可否认选择公众宣传本身也有局限性,如公司对产品的信息、播报时间等几乎没有控制权,如果公司在一个特定时期需要宣传,则媒体很有可能因未能及时报道而影响宣传效果。所以媒体宣传固然有优势,但也有其局限,它的发展只能说是差强人意。 为什么人们更愿意相信新闻报道而不是广告?',
  null,
  '{"A":"新闻报道更加客观","B":"新闻报道数量多,报道鲜明","C":"新闻报道是独立的","D":"新闻报道的观众群比广告的观众群大"}'::jsonb,
  '{}'::jsonb,
  4,
