(
  '文字-21',
  '文字-21',
  '现在的社会中有许多有很大的发展潜力但生活困难的人,他们无法靠自己的力量来改变目前的处境,但若有人进行扶持,则会前途无限。一些人认为社会的资源以及职位要通过市场来进行配置,政府无法包办。现在的情况是市场不可能自动实现与协调社会中各阶层人民收入的平衡,也不可能估计到整个社会的贫弱阶层,这样一来贫高差距过大,必然会影响社会的和谐发展。 上面一段话重点阐述的观点是:',
