(
  '文字-25',
  '文字-25',
  '虽然电子烟会在产品性能和配料上突出科技含量高、新潮时尚,但其配料无非是尼古丁、水、丙二醇等,原理就是电子蒸发。真正吸用电子烟上瘾的人都是年轻人,他们多数没有吸过传统香烟,只是为了追赶时尚。在正常使用条件下,电子烟气溶胶中的铅、铭和镍及甲醛的浓度等于或高于传统卷烟中的浓度。此外,电子烟还会产生一些传统卷烟烟气中没有的有毒物质,如乙二醛,该物质有毒,蒸气或雾对眼睛、黏膜和上呼吸道有刺激作用。随着消费者的理智回归和社会评价的不断客观化,电子烟遭受质疑是必然。 下面对本文内容理解正确的是:',
  null,
  '{"A":"吸电子烟的人大多没有吸过传统香烟。","B":"电子烟带来的巨大危害最终会引导消费者选择传统香烟。","C":"铅、铬和镍及甲醛是电子烟与传统香烟都有的成分。","D":"乙二醛带来的危害是电子烟遭受质疑的主要原因。"}'::jsonb,
