(
  '文字-26',
  '文字-26',
  '金融经济学家早前做的有关股票期权回溯调查,着重研究的是公司股权价格在授权后的不规则增长的程度范围。我与我的同事则着重研究股权授权日当天的股票价格在当月内股票价格分布图里所处的位置。研究者们对全球19000上市公司的首席执行官在10年内(1996-2005) 所获得的平价期权许可及其它计划之外的津贴进行了调查研究之后发现,选择授权日进行股票期权分配与其公司当日股票价格在当月股价排列分布图中的位置有很大的关联性:这就是说,如果股票价格在当月位于最低水平,那么这一天就极有 可能被选为股票期权授日,那么倒数第二低位置的价格就第二有可能被选中成为股票期权授权日,诸如此类推算。 根据作者的研究结果,我们可以推断出:',
  null,
  '{"A":"股票期权授权日与股票的价格低有关","B":"股票期权授权日与股票价格关系不大","C":"股票期权授权日的决定由每年度股票价格决定","D":"股票期权授权日是不会发生变化的"}'::jsonb,
  '{}'::jsonb,
