(
  '文字-28',
  '文字-28',
  '李渔是我国杰出的戏曲理论家。他的戏曲理论远比他的剧作更受人们重视。在吸取前人戏曲理论成果的同时,李渔根据自己丰富的戏曲创作经验和导演经验,对我国的戏曲、特别是昆曲艺术的经验和规律,作了相当全面的总结,建立了一套比较完整的理论体系。他在我国戏曲理论史上做出了重大贡献。他的戏曲理论主要见于《闲情偶寄》的《词曲部》、《演习部》和《声谷部》的一部分。在其他诗文中,也有一些对戏曲的可贵见解。李渔对我国戏曲艺术的特征和特殊规律最有认识,而且十分注重戏曲的舞台性、通俗性和趣味性。他明确说:"填词之设, 专为登场。"由此可见,李渔的戏曲创作有着鲜明的方向性,即戏曲创作是要为了舞台演出。基于材料,我们可以推测出:',
  null,
  '{"A":"李渔反对不考虑演出而只考虑案头略剧作","B":"李渔反对戏曲的娱乐性,主张戏剧表现要深刻","C":"李渔对戏曲语言的要求比对戏曲立意的要求更严苛","D":"李渔在戏曲方面同时注重编剧和导演的精细"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
