  '文字-29',
  '文字-29',
  '有一种看法,认为结构游戏只不过是幼儿拼拼凑凑、搬搬运运而已,无须教师过多的参与。其实,结构游戏如能进行得好,它不但能培养幼儿的搭配能力、空间想象能力、思维能力,而且能促进幼儿手、脑、眼协调一致的能力和培养幼儿对造型艺术的审美能力。但要使结构游戏发挥出如此的作用,教师不仅要参与,更要不失时机地示范、指导、点拨,否则,便不可能有这样的效果。 这段文字的主旨是:',
