),
(
  '文字-30',
  '文字-30',
  '湖州羽毛扇与苏州的团扇、杭州的折纸扇并誉为中国三大名扇。唐代颜真卿《石柱记》记吴兴旧事,有"姚苌雉尾扇"的记载,距今有1300多年历史。湖州羽毛扇向以选料严格、毛片平薄、制工精细、造型美观而闻名。花色品种繁多,有诸葛扇、桃形扇、圆形扇、半月扇、绒折扇等100余种,质软风柔,堪为消暑纳凉之上品,人们常说此种扇子扇出来的风是"和风",特别适宜于老、弱、病人及孕妇使用,不会扇出病来,因而被人们誉为"纳凉妙品",俗称"清凉悠悠鸟毛扇"。湖州民间习俗。男女婚后头年端午回赠长辈礼品必用羽毛扇,名为"端扇子",相沿至今。2007年, 湖州羽习毛扇制作技艺被公布为浙江省非物质文化遗产。 与本文符合的选项是:',
  null,
  '{"A":"\"姚苌雉尾扇\"选自明朝文震享《长物志》。","B":"2007年之前,湖州扇并非获得重视。","C":"湖州扇最有名的扇形是半月扇。","D":"湖州扇的\"和风\"适宜一些体质较差 需要被照顾的人群。"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '由题意可知:唐代颜真卿《石柱记》记吴兴旧事,有"姚苌雉尾扇"的记载,距今有1300多年历史。所以A错。2007年, 湖州羽习毛扇制作技艺被公布为浙江省非物质文化遗产。所以B错。选项C中内容文中并未提到,所以C错。人们常说此种扇子扇出来的风是"和风",特别适宜于老、弱、病人及孕妇使用。所以D正确。所以答案选D。',
