  '人浮于食:原指人的才能超过所得的俸禄。后比喻人员太多超过了工作的需要。牛鼎烹鸡:比喻大材小用。明珠弹雀:比喻做事轻重颠倒,得不偿失。投闲置散:指不被重视或不被任用。选择C。',
