  '文字-33',
  '文字-33',
  '当男性遭遇"性别气质威胁"(如你不够man)时,会刻意和"女孩子气"的物品保持距离。此外,为了保持自身与代表"男人"的准则相符,他们会在自己的男性气质遭到威胁时,想方设法在其他方面做出补偿。比如,那些男性气质受到威胁的男生,平均夸大了身高2厘米,而对照组只多报了0.4厘米。这类男生自称有过的恋爱关系次数也要显著更多,并指自己更有攻击性和运动能力。气质受到威胁的男性会更多地对女性进行性骚扰和怪罪强暴中的受害者。但由于睾酮的影响,女性相对并不容易受性别气质威胁影响。 下面最适合本文的标题是:',
  null,
  '{"A":"性别气质决定了男性的行为","B":"当男人不\"男人\",他们会怎么办","C":"夸大自己一维护性别气质","D":"像个男人,远离女性化"}'::jsonb,
