(
  '文字-37',
  '文字-37',
  '通过参与国际分工,参与资本与技术的引进和输出,摆脱封闭的自我调整,在国际产业结构的转换中实现产业结构的调整。这与世界经济一体化的发 展趋势是密不可分的,通过商品和劳务的交流,通过利用外资和引进技术,可以对我国产业结构起补调作用,实现对原有企业的技术改造,提高劳动生产率。同时填补国内的一些空白产业,促进产业结构的调整和升级。在这里,关键是如何瞄准国际产业结构的动向,盯住国际产业结构变动的重心,顺利实现产业结构的调整。 这段话:主要支持了这样一种论点,即:',
  null,
  '{"A":"积极发展对外经济关系是实现我国产业结构调整的一条有效途径","B":"通过参与国际分工,在国际产业结构的转换中实现我国产业结构的调整","C":"通过商品和劳务的交流,促进产业结构的调整和升级","D":"瞄准国际产业结构的动向,盯住国际产业结构变动的重心,顺利实现产业结构的调整"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '原文第一句话主要讲通过参与国际分工、参与资本与技术的引进和输出调整我国产业结构,第二、三两句主要讲通过商品和劳务的交流,通过利用外资和引进技术调整我国的产业结构,第四句是对前三句的补充。所以原文的主要内容是积极发展对外经济关系,实现我国产业结构调整。故正确答案为A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-并列关系。',
