(
  '文字-38',
  '文字-38',
  '周人取代商人而统治中原时,仍然使用贝币。在西周的社会经济中,货物交换发展,贝币的流通量日趋庞大。如殷代甲骨文中不过是"二朋""十朋"的数量,而周代的金文中,"百朋"甚至"万朋"等数字就很常见了。个人的交往动辄即有百朋之数,社会上的交易之大自然可想而知,由于天然贝的来源有限,于是出现了各种仿制贝,即以贝为模本,用其他材料仿制而成。现已出现的有蚌贝、骨贝、石砚、陶贝、铜贝、金贝等等,其中,最有重大意义的是贝与铜的结合而产生的铜贝。因为它是同后代的金属铸币连在一起的。 周代的铜贝可以说是世界上最早的铜造货币。而春秋战国时代的楚国把铜贝发展为一种椭圆形的小铜币,中国的钱币学家称为"鬼脸钱"和"蚊鼻钱"。这是中国古代铜钱的滥觞。 下列说法中与原文不相符的一项是',
  null,
  '{"A":"周代的人们普遍采用贝壳作为流通手段","B":"从周到商可能经历了一定程度的通货膨胀","C":"贝币经历了由真实贝类到贝形态钱币的发展过程","D":"春秋战国时,楚国最早发明了铜贝"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '由题意可知:周人取代商人而统治中原时,仍然使用贝币。所以A对。如殷代甲骨文中不过是"二朋""十朋"的数量,而周代的金文中,"百朋"甚至"万朋"等数字就很常见了。所以B对。由于天然贝的来源有限,于是出现了各种仿制贝,即以贝为模本,用其他材料仿制而成。所以C对。周代的铜贝可以说是世界上最早的铜造货币。周代最早发明了铜贝。所以选项D错误。与原文内容不相符,所以答案选D。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-排除错误项。',
