(
  '文字-39',
  '文字-39',
  '通过追踪人们在音频片段中使用的词语,研究者发现人们的语言模式比他们自己对压力等级的评价更准确地预测了焦虑、抑郁等与压力相关的生理疾病。在人们的语言中,比起意义词(名词或动词),功能词(代词和形容词)虽然没有任何意义,但它们明确了正在发生的事情,因此人们会更加自然地使用。正处于压力中的人会更少说话,但会使用更多的副词,如真的、难以置信,这些词是一种"情绪增强剂", 意味着更高的觉醒状态。他们也不太可能使用第三人称复数代词,如他们。因为当人们受到威胁时,他们可能会更少地关注他人和外部世界。 下面最适合本文标题的是:',
  null,
