(
  '文字-41',
  '文字-41',
  '研究发现野果对大脑的益处远远超过海产品,排在第一位,蔬菜是第二位。红莓苔子因其中含有大量能与自由氧离子发生相互作用的抗氧化剂,能破坏对血管和心脏有极大破坏性的胆醇激素。黑莓果有对视力和听力非常有益的成分。大叶子的圆白菜含有能把发展成帕金森氏综合症的酶破坏掉的物质。但是鱼只有金枪鱼、沙丁鱼含有能分解有害酶的脂肪酸和大脑大量需要的酶。如果认为只要吃了上述食品就变得聪明,就错了。食品应该多种多样。还有观点认为巧克力可以提高智力。每天吃50克巧克力可以延缓机体的衰老但指的是黑色的苦巧克力。过多食用非常甜的、含有奶制品的巧克力会产生糖尿病,肥胖症等。含有维生素B的食品,可促进大脑思维的过程,消除疲劳。但要开发智力,最好的方法是不断学习,读好书,与有文化有知识的人交流。 以下哪项在文中没有提及到? ( )',
  null,
  '{"A":"虽然金枪鱼、沙丁鱼等能够分解有害酶,但它们对大脑的营养比不上蔬菜。","B":"红莓苔子中有益于大脑,同时益于视力和听力的成分。","C":"食品可以促进大脑思维的过程,但是本身并不能提高智力。","D":"每天吃50克苦巧克力可以延缓机体的衰老。"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '又题意可知:研究发现野果对大脑的益处远远超过海产品,排在第一位,蔬菜是第二位。所以A对。红莓苔子因其中含有大量能与自由氧离子发生相互作用的抗氧化剂,能破坏对血管和心脏有极大破坏性的胆醇激素。黑莓果有对视力和听力非常有益的成分。是黑莓果有对视力和听力非常有益的成分。文中并未提到红莓苔子也有有对视力和听力非常有益的成分,所以B错。如果认为只要吃了上述食品就变得聪明,就错了。所以C错。每天吃50克巧克力可以延缓机体的衰老但指的是黑色的苦巧克力。所以D对。所以答案选B。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
