(
  '文字-43',
  '文字-43',
  '现代科学的思维方式在现代科学发展过程中经历了巨大的变化,形成了与近代科学差异很大的新角度、新方位,从机械观思维向以系统观为主导的思维转变,强调认识系统的整体性、动态性、复杂性和或然决定性。 这段话主要支持了这样一种论点, 即:',
