(
  '文字-44',
  '文字-44',
  '帕累托最优(Pareto Optimality),也称为帕累托效率(Pareto efficiency),是指资源分配的一种理想状态,假定固有的一群人和可分配的资源,从一种分配状态到另一种状态的变化中,在没有使任何一人境况变坏的前提下,使得至少一个人变得更好。帕累托最优状态就是不可能再有更多的帕累托改进的余地;换句话说,帕累托改进是达到帕累托最优的路径和方法。帕累托最优是公平与效率的"理想王国"。 对怕累托最优理解正确的是:',
  null,
  '{"A":"有人受损失的情况下有人获益。","B":"在不使其他人受损失的情况下有人获益。","C":"不使其他人受损失就不能使另一个人获益。","D":"使其他人受损失同时没人获益。"}'::jsonb,
