  '文字-45',
  '科学家发现,地球磁场除了有规则的昼夜变化外,还有约十年左右的周期性磁暴发生;又发现,磁暴的周期性经常与太阳黑子的活动周期相吻合;同时,随着太阳上的黑子数目的增加,磁暴的强度也增大,太阳黑子数目减少时,磁暴的强度也随之减小。 因此可认为:',
