(
  '文字-46',
  '文字-46',
  '人的血型通常是由红细胞表面某些可遗传的糖蛋白及糖链构成的抗原决定的。截至目前,像这样的血型系统已被发现超过30种,而Rh血型系统是其中最复杂的一类。在Rh系统中,如果红细胞表面含有D抗原,被称为RhD阳性,反之则称为阴性。研究发现,RhD阴性则非常少见,被称为熊猫血。有科研团队尝试用"易容术"解决"熊猫血"患者输血难题,即将RhD阳性红细胞"改造"成RhD阴性红细胞。目前已在小鼠体内实现了安全的单次及多次输血,展示了良好的临床转化前景。 根据本文内容,下面推断正确的是:',
  null,
  '{"A":"易容术改造的熊猫血(RhD阴性)同样也能在人类身上实现安全的单次及多次输血。","B":"易容术改造的熊猫血(RhD阴性)同样也将在人类身上实现安全的单次及多次输血。","C":"熊猫血(RhD阴性) 非常少见,一方面是因为Rh血型系统的复杂性导致的。","D":"熊猫血(RhD阴性) 罕见主要因为Rh血型系统是目前最复杂的血型系统。"}'::jsonb,
  '{}'::jsonb,
