  '文字-47',
  '文字-47',
  '不管在学习还是工作中,缺乏自信都会影响个人的发展。但是在工作能力和男性相当的前提下,自信的女性却不能为自己带来和男性相当的收益。有研究表明,男性工程师越自信,他们的影响力更大;而女性若要提升自己的影响力,除了自信,还需要具备亲社会倾向。也就是说女性要与其他人分享她的工作收益。因为人们对女性的刻板印象是不好胜。野心小,过于自信的女性不符合这样的人设,因而会遭受社会性的,经济性的报复,产生"反冲效应"。女性很少自我推销,因为她们担心他人对此的看法和反应。研究人员让一组女大学生写重名的奖学金申请书,另一组写量现名字的申请书,结果发现在重名的申请书中,女生都会报告更多的成就:而那些名字会显示的女生则更低调。 下面最适合本文的标题是:',
  null,
  '{"A":"职场中的女性刻板印象","B":"为什么女性表现得不如男性自信?","C":"刻板印象如何摧毁女性的自信","D":"他人看法如何影响女性表现"}'::jsonb,
