(
  '文字-49',
  '文字-49',
  '璋是中华礼器中较为正宗的祭祀用品,它的起源很早,而且在中华传统文化中有深刻的印迹。目前国内已发现的璋大约有 140 件,主要分布在山西、湖北、河南、河北、山东、福建、广东、四川等地,但他们大多数属于传世品或者采集品,通过正式考古发掘的出土品却极为罕见。而这些出土品主要出现在三星堆的两个祭祀坑中。虽然中原的早期文献中常常提到璋,好像中原人所遵从的祭礼从来就有一套完整的规章制度,既繁复又高明,璋一类的礼器本该多如牛毛,但事实上,真正能够传诸后世的物证,还是出现在成都平原这一被中原视为"夷"的地方。 根据上述材料我们能够推断出:',
  null,
