  '文字-51',
  '文字-51',
  '人类的正常活动是白天工作晚上休息,然而工业自动化却要求机器 24 小时不间断工作。一个人大约需要 6 天才能适应黑夜和白天颠倒,但在工业生产中几乎每星期都要倒班,倒班制度使工人的所有生活都变得混乱。解决这个问题似乎只有把夜班固定给一批人干,但同时也要挑选一些能快速适应倒班的人来环节轮班干活的紧张。根据提问挑选人员不失为一种好方法,因为人们工作效率高时体温也较高,只是这种方法至今并未得到实际的应用。根据材料内容,轮班工作的主要问题是:',
  null,
  '{"A":"寻找一批固定座夜班工作的人很难","B":"轮班工人的生活周期被打乱","C":"上夜班的人生活质量降低","D":"工人适应不了夜班生活"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '“解决这个问题”之前应该就是轮班工作的问题,即工人生活变得混乱,选B。',
