(
  '文字-53',
  '文字-53',
  '互联网解决的主要是信息的问题,以前是信息不对称,做生意时一方知道的另一方不知道,这样的不公平交易就可能会造成信息弱势的那一方吃亏。而网购的发展也是有代价的,北京的商场人最多的是第五层和地下一层,都是吃饭的楼层,中间的几层往往顾客没有营业员多,这些行业受到了很大的冲击, 这段话支持的观点是:',
