  '文字-57',
  '文字-57',
  '与外貌毫无吸引力的人相比,美貌的人拥有更多的社会理想属性。研究者发现当外貌信息是人们已知的唯一信息时, 它会在很大程度上影响他人对这个人的判断。实验中,被试被告知一位女性犯了入室盗窃罪或诈骗罪,他们需要为罪犯量刑。结果显示,在入室盗窃案中,被试给外貌吸引人的罪犯的平均量刑低于外貌不吸引人的罪犯;在诈骗案中,情况则截然相反---被试对外貌吸引人的罪犯的平均量刑高于外貌不吸引人的罪犯。当犯罪行为本身与罪犯的外貌无关时,人们会对貌美的罪犯从宽处理;当犯罪行为本身与罪犯的外貌有关时,人们会对貌美的罪犯更严厉。 根据本文内容,下面推断正确的是:',
  null,
  '{"A":"当人们充分了解一个人的所有信息之后,即使这个人非常美貌,也不会影响人们的判断。","B":"如果适当运用自己的美貌,人们就可以为自己谋取更大的利益。","C":"人们对诈骗罪的量刑高于入室盗窃罪,是因为人们认为诈骗案比入室盗窃案更加严重。","D":"如果一个人的外貌完全没有吸引力,那么人们对他的评价也会更加中立。"}'::jsonb,
