  '文字-58',
  '文字-58',
  '潜在疗法具有优势和劣势两重性。癌症通常无法治愈,是因为恶性肿瘤会附着在血管壁上,吸收附近所有的营养,从而使恶性细胞不断长大直至扩散到全身。癌症不治的主要原因是无法阻止癌细胞的蔓延。医学家已经发现了潜在疗法,它通过单个的生物化学转换刺激血管生长,但因为血管生长的生物途径非常复杂,多数实验仍需进一步探索。潜在疗法与传统疗法不同,它不会损坏正常的组织,蛋白质干扰只在创造新血管时发挥重要作用。事实证明,虽然潜在疗法目前仍不太稳定,但一方面使用传统疗法,一方面除去肿瘤的供血来源的组合方法,应该是今后抗癌的一种有效治疗方案。根据材料推断,潜在疗法主要是针对:',
