  '辽代的乐舞形象造型很特殊。体志上大都呈现出面部六围,体形敦厚的特点。服饰上兼容汉族服饰与契丹服装,如有的戴汉人的头巾,有的戴契丹毡帽。这些特征在多个乐舞壁面上都有体现。内蒙古库伦旗辽基壁画的乐舞形象(残缺) ,其服饰动作和乐器等有看明显的中原特色。河北宣化辽墓壁画中的乐舞人皆戴头巾,乐工手执鼓板。笛、笙、排箫等汉传乐器。河北蓟县独乐寺辽塔砖雕乐舞人。其造型服饰与动作方面有着少数民族的特点,比如着毡帽,靴子及脸型扁因,两腮胡须等。根据上述材料,我们能够推测出:',
  null,
  '{"A":"根据辽墓壁画的考据,辽代歌舞融合了汉代和辽代的特色","B":"辽代乐舞形象是以壁画的方式保存下来的","C":"辽代的乐部形象往往是根据本民族的人物形象塑造的","D":"辽代的乐舞受到了中原的影响"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '根据原文辽基壁画的乐舞形象 (残缺),其服饰动作和乐器等有看明显的中原特色,所以选择D。',
