  '文字-62',
  '文字-62',
  '神经性厌食症患者不愿意摄入与其所需等量的食物。他们变得极度消瘦,有时甚至死亡。罹患神经性厌食症的患者通常在青少年时期发病,在较严重的病例中,女性的比例较高。问题并不在于缺乏食欲。厌食症患者享受食物的味道和气味,而且,很多患者还喜欢烹调食物。他们的问题在于对变胖或丧失自我控制的恐惧。与濒于饿死的人不同,大多数厌食症患者是勤奋工作的完美主义者,而且惊人的活跃。神经性厌食的病因现在还知之甚少。患这种疾病的人血液和脑内存在多种生物化学反应的异常,但这些异常也可能是体重降低的结果。一个有趣的推测将厌食症与麋鹿及其他大型哺乳动物为寻找一个更好的觅食地而进行的长距离迁徙时的行为进行比较。迁徙过程中,它们高度活跃,甚至在找到一小片草地的时候它们仍然拒绝所有食物。可以想象,当运动与节食的结合引发人类大脑中相似的机制时,厌食症就发生了。下面哪项内容在文中提到过? ( )',
  null,
  '{"A":"神经性厌食症患者容易在青少年时期发病,而且通常以男性居多。","B":"有推测认为,厌食症的病因可能和运动与节食的结合所引发的大脑生化反应有关。","C":"神经性厌食症患者缺乏食欲,不愿意摄入食物,因此十分消度。","D":"神经性厌食症患者不缺乏食欲,但是往往不愿意摄入食物,因此十分消瘦。"}'::jsonb,
  '{}'::jsonb,
