(
  '文字-69',
  '文字-69',
  '各种媒体暴力节目与个体暴力性行为之间是否存在直接的因果?怀疑论者认为多数研究夸大了媒体暴力对观众的影响。危言耸听者则认为暴力媒体直接造成了侵略性行为,他们认为暴力节目会使越来越多的人把观看暴力视频当成有趣的娱乐活动,从而进一步巩固社会暴力倾向。而现实是, 一种社会行为背后也许不只有一种原因 ,在反驳危言耸听者时,首先要弄清何为暴力,在为两者关系下定义前,要重新考虑前提条件。材料的主要内容是:',
