  'C',
  '患失语症的人可在2到3岁开始,至青春期到来之前结束,在此期间进行完全的语言恢复训练,有可能恢复。因为青春期大约在18岁左右结束。因此,本题选C,18岁之前。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
