(
  '文字-72',
  '文字-72',
  '对灵长类动物而言,能否融入团体对身心的健康发展至关重要,倭黑猩狸就经常通过互相梳理毛发来维持友谊。但理毛需要一对一服务,这样既费神又费时。因此对人类来说,音乐是将彼此连结在一起更好的方法。 研究者让不同的合唱小团队分别进行独立合唱和集体合唱,在唱歌前后对他们的情绪、人际关系及对疼痛的耐受性进行测量。结果发现,合唱能显著增强成员的积极情绪、社会亲密感和接纳感,同时对疼痛的忍受性有了显著提升。此外这些感受在集体合唱中的程度要高于独立合唱,说明合唱可以拉近成员彼此的心,同时合唱在大社群中发挥的作用大于在小社群中的作用。下面不属于合唱的好处的是:',
  null,
  '{"A":"让自己更能够忍受疼痛","B":"让自己更加开心","C":"让自己与成员关系更亲密","D":"让自己更受人喜欢"}'::jsonb,
