(
  '文字-74',
  '文字-74',
  '抽卡是指在游戏中通过免费赠送或花钱购买的道具,随机抽得稀有材料的游戏方式。除了抽卡,消耗自己积攒的材料以一定的概率合成罕见的游戏角色,也采用了相似的游戏机制。抽卡游戏实际上是一个概率问题。不确定性的奖励是吸引人们抽卡的主要原因。有研究让小鼠按下控制杆,到达一定次数可以获得食物。但组是随机得到的,另一组是有规律地得到的。结果发现,在奖励消除后,随机得到食物奖励的小鼠会更持久地按控制杆,这种现象被称为"间歌强化"。此外,当我们成功的时候,大脑会释放多巴胺以让人感觉愉悦。但与成功失之交臂时,多巴胺同样会分论。这种机制会鼓励人们继续努力直到成功。 下面哪个词能够代替"失之交臂", 而使原文意义不变? ( )',
