(
  '文字-76',
  '文字-76',
  '用含0.25mg/m的藻蓝蛋白(藻青素)处理培养的小鼠骨髓瘤细胞,再经514nm激光辐照300J/平方厘米,发现癌细胞存活率仅15% ;而单纯采用激光辐照或藻蓝蛋白处理,细胞存活率69%和71%。人大肠癌细胞株HR8348培养后分别用100μg, 50μg , 25μg的钝顶螺旋藻的藻蓝蛋白处理,经光波为630nm的铜激光辐照12J/cm,用MTT法检测培养癌细胞存活率分别为22.2% ,6%和89.7%,显示良好的剂量效应。对肉瘤S180小鼠,分别给予藻蓝蛋白注射2mg或口服20mg后,经铜激光福照瘤体15天后,有效率分别为50%和53%,与对照组相比,具显著差异。体内外试验证实藻蓝蛋白确有光教作用,且无毒副反应,是一种理想的光敏剂。对这段话的理解正确的一项是:',
