(
  '文字-79',
  '文字-79',
  '哈佛大学的研究人员通过机器学习的方法建立了一个可以利用Instagram上发布的照片来检测一个人是否患有抑郁症的模型,准确率高达70%。研究者认为,Instagram.上的图片含有大量的可以用于心理洞察的特征,照片可以被编码为定量特性进行评估,包括像素、颜色和亮度值。图片收到评论和点赞的数量、用户使用和上传图片的频率等,也可以作为评估用户心理状态的线索。研究结果发现,情绪的确和视觉偏好相关。患抑郁症的用户更喜欢蓝色、灰色或者一些深色的色调,不用滤镜或只使用黑白滤镜。相比之下,心理健康的用户,往往更喜欢明亮的色调,也更喜欢使用明亮的滤镜,同时,患有抑郁症的用户很少获得赞,更喜欢上传包含自己面孔的图片,但平均每张图片中出现其他人面孔较少,这也符合抑郁症患者通常都在较小的社会环境中互动的情况。 根据上述材料我们不能推测出:',
  null,
  '{"A":"心理健康的用户比抑郁症只户更喜欢使用明亮的滤镜。","B":"是否使用滤镜反映了一种视觉偏好。","C":"心理健康的用户较有可能获得点赞。","D":"心理健康的用户通常不喜欢上传自己的照片。"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '题干中,最后一句话只是说明了“患抑郁症的用户,更喜欢上传包含自己面孔的图片”,并没有说心理健康的用户通常不喜欢上传自己的照片。因此,本题选D。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-并列关系。',
