(
  '文字-80',
  '文字-80',
  '额叶负责逻辑、语言、决策等高级认知行为,顶叶主要处理感官,颞叶主要处理听觉和记忆,枕叶负责视觉。左脑和右脑虽然没有明确的分工,但是随着不同人的使用偏好也会有不同的倾向一对大多数右撇子们来说, 左脑擅长逻辑分析和语言,右脑则是直觉和空间感知。大脑之下还有小脑,它让我们的动作更协调精确,帮助运动,保持平衡和方向感。人脑不同功能区之间的神经连接就好像它们间的"导线",让一只只神经元能够相互联络,彼此"合作",构建起整个"电路"根据本文内容,下面推断正确的是:',
  null,
  '{"A":"除了左脑和右脑,人脑其他部分都有明确的分工。","B":"对左撇子而言,左脑擅长直觉和空间感知,右脑擅长逻辑分析和语言。","C":"每个人不同的使用偏好会影响人脑各个区域的发达程度。","D":"人脑的构造和电路的构造相同,其中神经连接起到了核心作用。"}'::jsonb,
