(
  '文字-81',
  '文字-81',
  '逆差与顺差,应当辩证地看,贸易平衡永远是相对的、动态的。中美经贸关系是双赢而非零和,经济互补性注定了美对华逆差将是一个长期问题。今后,中美两国参与全球化和产品内分工的程度会继续加深,只要不改变现行统计方法,美对华逆差仍将持续,而中美经贸规模也仍将不断扩大。这段话表达的核心观点是:',
