  '文字-82',
  '我国的专利申请平均每年以48%的速度增长。我国的专利实施只占专利总量的20%~30%,与国外高达80%的实施率相比差距很大。在我国专利申报总量只有15%来自于企业,而发达国家的专利申请80%来自于企业。 据此,以下观点正确的是:',
