  '夏天,少数人为贪图凉爽,早餐以冷饮代替豆浆和牛奶,这种做法在短时间内不会对身体产生影响,但长期如此会伤害"胃气"。在早晨,身体各系统器官还未走出睡眠状态,过多食用冰冷的食物,会使体内各个系统出现孪缩及血流不顺的现象。所以早饭时应首先食用热稀饭、热豆浆等热食,然后再吃蔬菜、面包、水果和点心等。这段文字主要谈的是:',
