(
  '文字-88',
  '文字-88',
  '细菌无处不在,即使是我们认为洗得很"干净"的手上也充满了细菌。虽然多数细菌是无害的,也改变不了有害细菌让我们寝食难安的事实。河豚中毒或对各种食物过敏,大多都是细菌惹的祸。到目前为止,高温加热仍然是杀死细菌的最有效手段。通常的食品加工,只是把细菌的量减少到一定浓度,不会对人体产生危害即可.如果是超高温灭菌,把牛奶加热到135度以上,1秒钟就可以几乎杀死全部的细菌,这样处理过的牛奶即使是放在常温下,也能保证几个月不出问题。当然,这仅限于密封保存的情况。对个人而言,注意食品安全、建立良好的卫生习惯也是预防细菌危害的手段。厨房、冰箱经常清洁并保持厨房通风干燥,有助于减少细菌。家里的食物,尽量减少存货。下面能代替文中的"寝食难安"且保持意义不变的是:',
