(
  '文字-91',
  '文字-91',
  '文化消费是消费者对有形和无形的文化产品的消耗,消费过程实质上是对文化的消化、继承积蓄、再造和创新过程。对消费者而言,文化消费的效用就是获得精神享受。这种消费分为两类:一类是消费者自主支付的文化消费,必须支付货币,这是主流的文化消费;另一类是由政府提供的公益性的文化消费。消费者的文化消费不仅仅与他们的经济实力相关,更与他们的文化资本息息相关。消费者的文化资本,即解释、理解和欣赏文化产品的能力,既影响文化消费的深度,也影响文化消费品位,而这一资本又在一次次在文化消费中发生着变化。以下对"文化消费"理解正确的是:',
  null,
  '{"A":"文化消费的实质是对无形文化的消化、继承积蓄和创新过程。","B":"文化消费包括必须支付货币的消费和公益性 文化消费两种。","C":"一切与人类有关的文化活动都是由于文化消费产生的。","D":"文化消费不仅会产生政治、经济、社会福利,还会带来精神享受。"}'::jsonb,
  '{}'::jsonb,
