  '文字-92',
  '文字-92',
  '与审美感知和审美注意相比,审美情感是艺术欣赏中最具活力的心理因素。艺术形象是情感化的审美物,观众通过情感活动与作品进行交流,最终目的是为了获得情感愉悦。即使是理性意识的获得,其最有效的途径也往往是"动之以情"。情感活动是以认知为基础的,它往往能引起快感,但审美快感不是生理冲动的满足,而是精神上的赏心悦目。因此,审美的情感愉悦并不是一种感官刺激,而是意识领域中的一种审美感受。 材料中心思想是:',
  null,
  '{"A":"艺术欣赏的方式","B":"审美情感与审美感知的区别","C":"审美情感的实质","D":"审美情感在艺术欣赏中的重要性"}'::jsonb,
