  '文字-93',
  '以制度安排和政策导向方式表现出来的集体行为。不过是诸多个人意愿与个人选择的综合表现。除非我们每一个人都关心环境,并采取具体的行动,否则,任何政府都不会有动力(或压力)推行环保政策。即使政府制定了完善的环保法规,但如果每个公民都不主动遵守,那么,再好的环保法规也达不到应有的效果。 这段文字主要支持的一个观点是:',
