  '文字-94',
  '文字-94',
  '无症状感染者是虽然感染了病毒,但自己却不会发病,这是怎么回事呢?如果感染了病毒,神经系统会调节人体体温,让人体温度上升几度,因为温度高可以抑制病毒自我复制的能力,免疫系统会派出具有杀伤力的细胞剿灭病毒,此时人体就会感到发烧、无力,这个阶段就是人体与病毒硬杠的时期。而无症状感染者就厉害了,同样是病毒,在别人体内可能会引起发烧、咳嗽、流鼻涕,但他们的身体素质比较强,免疫系统也比平常人要强,所以它们的免疫系统可以杀死一部分病毒,让病毒无法感染更多的细胞,此时就不会引起人体生病,或者是人体症状比较轻。这就是无症状感染者。值得注意的是,无症状感染者并不代表着不会生病,如果当体内的病毒占据上风时,该患者依然会患病,只是相对于普通人而言,需要更久的时间才会发病。 下列对本文内容理解不正确的是',
