  '文字-96',
  '文字-96',
  '有研究发现当我们在乎的人处于困境,我们也会投入到他的情绪中,并感到不适。这时如果给对方提供食物,不仅可以表达支持,也会使提供者与接受者都获得情绪上的正向影响,并使双方感到更加亲近。食物能够有效调节内在情绪的原因在于其兼具生理与心理的特性:食物不仅可以让我们饱腹,也可以用来表达庆祝、告别、安慰。提供食物是无论关系深浅都适宜的表达方式,且行为背后具有建立关系、传递关心、表达支持等更深层的内涵。下面对本文内容理解正确的是:',
