  '文字-97',
  '文字-97',
  '碘是人体必需的微量元素之一,是合成甲状腺激素必不可少的重要原料,在维持机体健康的过程中发挥着促进生长发育、参与脑发育、调节新陈代谢和对其他器官系统功能产生影响的重要作用,孕妇缺碘不但会对自身造成危害,还会影响宝宝的生长发育,由于怀孕的生理变化,孕妇对确的需求量高于正常成人。这主要是因为妊娠反应会使碘损入减少。而孕吐会使确流失增加。另外,在怀孕前半期,支持胎儿脑神经发育的甲状腺激素主要来自母亲,母体也需要将一部分碘要通过胎盘转运给宫内的宝宝。再者,孕晚期母体血容量增加,稀释碘浓度,同时肾血流量增加,肾小管滤过率和肾脏碘清除率均有所提高,导致确随尿液排出增多。 下面对本文内容理解正确的是:',
