(
  '文字-99',
  '文字-99',
  '自我意识指的是个体对自己的心理、思维及行为活动的内容、过程及结果的自我体验。自我认识。自我调节。自我意识一般包括两个方面: 一个是主体的我,即对自己身心活动的觉察,比如性格、能力和行为等;另一个是客体的我,即被觉察到的我,是个体在生活中作为客体被自我和他人所认识。自我意识的结构是从自我意识的知、情、意三方面分析的,包括自我认识,自我体验和自我调节。自我认识是自我意识的认知成分,它是自我意识的首要成分,主要包括自我感觉、自我观察、自我分析和自我评价。自我体验是自我意识在情感方面的表现,自尊心、自信心都是自我体验的具体内容。自我调节是自我意识的意志成分,包括自我检查、自我监督、自我控制等。 根据材料,自我意识是指。',
  null,
  '{"A":"人对主体 我和客体我认识的统一体。","B":"人对外部世界及对他人和自己的认识。","C":"人对思维活动结果的自我体验、 自我认识和自我调节。","D":"人生而具有的一种区别于动物的意识存在形式。"}'::jsonb,
  '{}'::jsonb,
