  '梳理文段的中心句与行文重点后，A项“人对主体 我和客体我认识的统一体。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-并列关系。',
