),
(
  '文字-100',
  '文字-100',
  '很多人小时候都不喜欢苦涩的蔬菜或汤药。但长大之后,越吃越觉得这些东西也没那么难吃。原因是我们的唾液美化了味觉, 让苦涩的食物更容易接受。唾液作为唾液腺分泌的一种多功能体液,其中99%以上的成分是水,此外还有电解质、抗菌物质、帮助消化的酶等等。人们每天分泌的唾液可以冲刷口腔、维持黏膜湿润、预先分解食物中的营养物质。同时,唾液中的某些蛋白质会影响食物中的风味物质与味觉受体细胞的结合,从而改变我们尝到的口味。因此,连续吃苦涩食物可能影响唾液里特定蛋白质的表达,从而减少人对苦味和涩味的感知。 下面对本文内容理解正确的是:',
  null,
  '{"A":"小时候不喜欢吃的蔬菜或汤药,长大之后都会觉得好吃。","B":"唾液是一种主要由水组成,可以冲刷口腔、帮助消化的营养物质。","C":"食物中的风味物质与味觉受体细胞的改变会影响人们对味道的感知。","D":"唾液中的蛋白质会在重复多次的咀嚼中改变食物的苦涩味道。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '由题意可知:很多人小时候都不喜欢苦涩的蔬菜或汤药。但长大之后,越吃越觉得这些东西也没那么难吃。所以A错。唾液作为唾液腺分泌的一种多功能体液。所以B错误。食物中的风味物质与味觉受体细胞的结合,从而改变我们尝到的口味。所以C对。题中并未提到唾液中的蛋白质会在重复多次的咀嚼中改变食物的苦涩味道。所以D错。所以答案选C。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
