(
  '文字-103',
  '文字-103',
  '限于各物流公司及网购商家对成本的控制,塑料袋、胶带等大多为难以降解的塑料制品被广泛使用。同时,快递包装填充物等垃圾随处可见,大量快递包装材料难以回收利用和循环使用,也使得快递包装业急需向绿色包装方向转型。快递包装"绿色化"的发展,对电商商家、物流企业运营成本增加影响大,消费者包装回收分类也意识薄弱。鉴于此,要以政府政策为推动,以电商、快递企业为主体,全产业链共同努力,推动快递包装物可降解材料的利用和快递包装多次回收再利用模式的发展。这其中,下游厂商谁能推出具有一定成本优势的绿色环保产品,谁就能抢占市场先机。 下面对本文内容理解正确的是:',
  null,
  '{"A":"首先研发推出绿色环保产品的厂商,能够先人一步占领市场。","B":"因为快递包装材料都是不可回收的, 所以要推动快递包装\"绿色化\"。","C":"当电商商家和物流企业的运营成本变大,快递包装就能\"绿色化\"发展。","D":"每一家网购商家都在使用塑料袋和胶卷。"}'::jsonb,
