(
  '文字-104',
  '文字-104',
  '中国者百姓无论怎样穷,怎样苦,也要从牙缝里挤出钱来,供孩子上学念书。他们很清楚,只有这样,才可能从根本上改变命运,才可能拥有未来。运用到国家政策层面,毫天疑问。教育只应该是公益事业,是烧钱的事业。 这句话中"烧钱的事业"可以理解为:',
  null,
  '{"A":"教育事业是一项非常费钱的事业","B":"对教育应该投资而不应该从中谋利","C":"对教育的投资可能无法收回成本","D":"国家应该增加教育投资力度"}'::jsonb,
  '{}'::jsonb,
