(
  '文字-106',
  '文字-106',
  '"不公平"存在两种形式,一种是"我比你少",另一种是"我比你多"。对"我比你少"的厌恶是大自然的规律,所有的灵长类生物都存在这种厌恶。但对"我比你多"的厌恶却是人类的"专长"。只有人类才会主动放弃既得的好处以维护一个公平的结果。 这一方面是因为人类的共情心已相当成熟,另一方面是因为人类还具有内疚等高级情绪, 因此会怜悯弱者。但人们会不会为了公平而放弃战得利益,要看他们在资源分面对程中的角色。如果人们是分面中的主导者,即由他们决定如何分配,他们就有可能会遵守公平原则;如果他们只是分配中的接受者,他们反而会接受有利于自己的不公平结果。 下面对本文内容推斯正确的是:',
  null,
  '{"A":"动物在面对 \"我比你多\"的情况时,不会放弃自己己有的好处。","B":"在面对不公平情境时,人们之所以愿意放弃既得的好处。是为了帮助弱者。","C":"动物不会认为\"我比你多\"的情况是不公平的,因此动物不会产生厌恶感。","D":"人们在资源分配中所处的位置决定了他们对\"我此你多\"现象的感知。"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '梳理文段的中心句与行文重点后，B项“在面对不公平情境时,人们之所以愿意放弃既得的好处。是为了帮助弱者。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择B。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
