(
  '文字-107',
  '文字-107',
  '有研究发现,浪漫的爱情与腹侧被盖区和尾状核这两个区域的活跃有关。这些区域在我们的奖励通路中发挥了必不可少的作用,而且调控了让我们"感觉很好"的神经递质多巴胺。也就是说,在恋爱的早期阶段你渴望那个人是因为对方让你感觉非常好。一旦坠入爱河,仅仅想到对方就能够感到愉快,同时也能缓冲疼痛、压力和其他负面情绪。而长期的恋情会让大脑更多区域产生变化,长期恋人的大脑中,与依恋有关的大脑区域得到了更大程度的激活,同时调节焦虑与疼痛的阿片类和5---羟色胺富集的区域更加活跃。 下面最适合本文的标题是:',
  null,
  '{"A":"爱情如何改变我们的大脑","B":"恋爱让我们感觉更愉快","C":"奖励通路因恋爱而改变","D":"大脑变化告诉你,恋爱很幸福"}'::jsonb,
