(
  '文字-109',
  '文字-109',
  '归因理论的研究者发现,我们解释他人的行为时,会低估环境的影响,而高估个人的特质和态度的影响;而对于自己的行为,则更多归因于情景的影响。这种倾向被称为基本归因错误。我们为什么会犯归因错误呢?有学者指出,当我们作为行动者时,环境会支配我们的注意;而当我们观察别人的行为时。作为行为载体的人则会成为我们注意的中心,而环境变得相对模糊。同样,文化也会影响归因错误。一个持有西方式世界观的人,更可能认为是人本身导致了事件的发生。在这种文化下,用内部原因解释人的行为更受社会赞许。但是东亚文化下的人通常对环境的作用格外敏感。当意识到社会环境的影响作用时,他们很少设想他人的行为与其内在特质有关。 对于产生基本归因错误的原因,下面理解错误的是:',
  null,
  '{"A":"当我们所处的立场不同,行为者和观察者的视角也就不同,对行为的解释也就各不相同。","B":"如果我生气了,那是因为我本身脾气就不好。如果别人生气了,那是因为当时的情境让他生气。","C":"西方文化下的个体更加容易将行为解释为个体本身的原因,而东方文化则更看重情境的影响。","D":"对于迟到这一现象,中国人常解释到\"闹钟使我起晚了\""}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '我们解释他人的行为时,会低估环境的影响,而高估个人的特质和态度的影响;而对于自己的行为,则更多归因于情景的影响” 所以B应该为“如果别人生气了,那是因为他本身脾气就不好。如果我生气了,那是因为当时的情境让我生气',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
