  111,
  '{"kind":"verbal","analysisSource":"原题解析","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-110',
  '文字-110',
  '植物和动物一样,也会受伤。由于一些食草动物以植物为食,所以植物经常受伤。同样,植物也和动物一样,会为自己迅速疗伤,以防伤口感染或者重要物质流失。但是最近科学家们发现了一种不自我封闭伤口的植物。这种叫做小癫茄的茄属植物会让伤口渗出物质,在伤口处故意分泌一种花蜜,可以吸引昆虫,进而可以保护植物不受食草动物的伤害---如蚂蚁在收到花蜜这样的雇佣费之后,就会对抗甲虫幼虫。甲虫幼虫不得不爬上茎,因为它们要在植物幼嫩的茎上开采物质。幼嫩的茎离主干约半米到一米的距离。幼虫在前往茎的路上,就会受到蚂蚁的攻击。因为蚂蚁就在植物处巡逻。与没有受到蚂蚁群保护的植物相比,受到保护的植物其生长速度要快约10%-13%。 下列哪项不是小癫茄分泌物质的收益:',
  null,
  '{"A":"抵御侵略者不再攻击其伤口","B":"比其他植物更快地生长","C":"使侵略者无法攻击其嫩茎","D":"花粉得以广泛地传播"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '由题可知:这种叫做小癫茄的茄属植物会让伤口渗出物质,在伤口处故意分泌一种花蜜,可以吸引昆虫,进而可以保护植物不受食草动物的伤害。所以A对。与没有受到蚂蚁群保护的植物相比,受到保护的植物其生长速度要快约10%---13%。所以B对。甲虫幼虫不得不爬上茎,因为它们要在植物幼嫩的茎上开采物质。幼嫩的茎离主干约半米到一米的距离。幼虫在前往茎的路上,就会受到蚂蚁的攻击。所以C对。选项D的内容文中并没有提到。所以答案选D。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
