  '北森言语理解',
  null,
  112,
  '{"kind":"verbal","analysisSource":"原题解析","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-111',
  '文字-111',
  '达尔文进化论的核心是自然选择。"物竞天择,适者生存"是前提和基础。逐渐积累的有利变异结果就形成了新的物种。因此达尔文一再宣称"自然界没有飞跃"。美国古生物学家古尔德和埃尔德雷奇提出了"间断平衡论"。该理论指出生物的进化是渐变与跃进交替的进化模式。达尔文之后的古生物发现和研究证据都明确地表明,自然界不单存在着达尔文所主张的渐灭,还存在着达尔文坚决否认的突然绝灭。同时,20世纪60年代以来的科学研究表明,在自然界中,每个生态系统内的生物个体、物种、群落之间,以及它们与环境之间,不但存在竞争,更有协同发展。人们熟悉的一个例子是,昆虫在采集花粉的同时,也为植物完成了授粉的任务,动物与植物彼此受益。 根据本文,下面理解不正确的是:',
  null,
  '{"A":"20世纪60年代以来的研究表明,不同物种之间的相互依赖是推动生物进化的重要原因之一","B":"昆虫采集花粉的事例证明了\"间断平衡论\"的正确。","C":"\"间断平衡论\"解释了达尔文进化论无法回答的问题。","D":"达尔文认为自然界中从来没有出现过生物突然灭绝的现象。"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '逐项定位原文，B项“昆虫采集花粉的事例证明了"间断平衡论"的正确。”与原文信息不符、表述过度或未被提及，符合题干要求，因此选择B。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-排除错误项。',
