  '文字-112',
  '文字-112',
  '人们都希望能拥有更好的记忆力。但研究者认为,记忆的缺陷才是其最重要的特性。人类的记忆只会记录事件的大概内容,且往往经过了自我美化,还充斥着大量错误的修正。在一项研究中,研究者让大学生回忆他们在高中时期的成绩,结果显示:回忆起的成绩有五分之一都和实际不符,分数越高越不容易记错。这说明错误的记忆可以让我们自我感觉良好从而增进健康。另一项研究中,研究者要求受试者阅读一个赢得几百万乐透大奖的幸运儿罗格的故事。其中一部分受试者读到的是,罗格是一个工作努力,与人为善的好人;另部分受试者读到的却是:罗格总是好吃懒做、怨天尤人、对人冷漠,他根本不配有这样的好运。其后,当研究者让受试者回忆罗格赢得奖金的具体数额时,那些认为他不配得到这笔奖金的人比另一组受试者给出的答案平均低了280000美元。这说明错误的记忆还可以保护我们对公平正义的信念。 根据上述材料我们能推论出:',
  null,
  '{"A":"罗格的故事说明记忆会倾向于美化人。","B":"罗格获得的奖金数额是受试者分配的。","C":"两组受试者阅读的故事中,罗格获得的奖金数额是相同的。","D":"实验说明受试者对不配拥有奖金的罗格有偏见。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '逐项对照原文，C项“两组受试者阅读的故事中,罗格获得的奖金数额是相同的。”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择C。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
