  'C',
  '有原文可知,光合作用是地球上最为普遍、规模最大的反应过程,在有机物合成、蓄积太阳能量和净化空气、保持大气中氧气含量和碳循环的稳定等方面起很大作用。C正确。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
