(
  '文字-114',
  '文字-114',
  '在痛苦的时候,人们回忆起曾经痛苦的记忆,就会更加消极地看待些问题。这时候,人们很容易对负性事件进行深度思考。人们沉浸于对这种抽家的、无法解释清楚的问题的思考中,结果唤起更多的有关自我和外界的负面规法,变得更加痛苦,这就是反刍。反急思维不仅无法解决问题,还会在不断的思考中更加消极地评价事件,并在想起这些事情时感到更悲伤、更痛苦, 唤起更多负面情绪,形成个无休止的恶性循环。 下面符合反刍思维的过程的是:',
  null,
  '{"A":"负性情绪——回想起负性事件——变得消极——思考为什么会变成这样——唤起负面自我","B":"回想起负性事件——负性情绪——思考为什么会变成这样——变得消极一一唤起负面自我","C":"负性情绪——回想起负性事件——思考为什么会变成这样——唤起负面自我一一变得消极","D":"负性情绪——变得消极——回想起负性事件——思考为什么会变成这样——唤起负面自我"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '由题意可知:在痛苦的时候, 人们回忆起曾经痛苦的记忆,就会更加消极地看待些问题。这时候,人们很容易对负性事件进行深度思考。人们沉浸于对这种抽家的、无法解释清楚的问题的思考中,结果唤起更多的有关自我和外界的负面规法,变得更加痛苦,这就是反刍。反刍思维的过程应该是:负性情绪——回想起负性事件——变得消极——思考为什么会变成这样——唤起负面自我。所以答案选A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-递进关系。',
