  null,
  116,
  '{"kind":"verbal","analysisSource":"原题解析","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-115',
  '文字-115',
  '在社会交往中,个体产生的第一印象往往会影响到对他人的知觉。但随着对他人认识的深入,逐渐形成了对他人的整体印象。20世纪60年代开始,有心理学家陆续提出了几个信息加工处理的模型用于解释印象形成。一是平均模型。 该模型认为我们将正性印象记作正数,将负性印象记作负数,以简单平均的方式处理所获得有关他人的信息,二是累加模型。该模型指人们对他人片断信息的整合方式与平均模式相似,也是将对他人的印象综合起来,但是最后进行的是累加而非平均。而支持累加模型的研究不多。三是加权平均模型。按照这一模型,人们形成整体印象的方式是将所有特质加以平均,但对较重要的特质给予较大的权重。相对而言,加权平均模型能够解释的范围更广。 根据本文观点,下列观点正确的是:',
  null,
  '{"A":"我们向他人塑造的第一印象对他人形成关于我们自身的整体印象起着重要作用。","B":"由于支持累加模型的证据不多,因此可以推断人们对他人的整体印象主要是通过平均模型形成的。","C":"根据加权平均模型,我们看重的特质在形成他人整体印象的过程中影响更大。","D":"在当前解释印象形成的所有模型中,加权平均模型的解释性是最好的。"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '逐项对照原文，D项“在当前解释印象形成的所有模型中,加权平均模型的解释性是最好的。”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择D。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
