(
  '文字-116',
  '文字-116',
  '盆景艺术大多为文人喜好,究其因,其创作过程实际上是创作者美学思想的折射。这和文人作品中追求的"境由心生""道法自然"之观不谋而合。在狭小的盆盎之间,植物、山石、水、土等因素都被赋予无限的精神内涵。南北朝时,画家宗炳就运用画理缩景于盆,寄情山水,高枕卧游,在有限的空间内表现无限的诗意情怀。清初崇古之风大盛,文人将盆景艺术与书画美学、禅意思想、诗文古意等融合且发挥极致。盆景中的花草树石、山水林泉在文人指端呈现千姿百态,其中的一草木寄寓着作者深厚的情感,或超然世外,或自持傲骨,暗含了无限的意境。 下列符合原文的一项是',
  null,
  '{"A":"盆景艺术的创作过程体现了古代文人的美学思想","B":"石、士这类因素可以不细细品味","C":"盆景艺术的视觉体验比情感体验更重要","D":"盆景中的景观皆是创作者的情感外现"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '逐项对照原文，A项“盆景艺术的创作过程体现了古代文人的美学思想”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择A。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
