(
  '文字-117',
  '文字-117',
  '中国原始彩陶大批的出现,是从约六千年前的仰韶文化到约三千年前的大汶口文化。从已发现的材料看,黄河流城、长江流域新石器时期的彩陶,大体上可以按照区域归为中原地区彩陶、西北地区彩陶和东南沿海地区彩陶三类。这三个区域的彩陶,在器型、纹饰方面都有它的基本相异之处,从器型来看,中原地区多盆形、钵形;西北地区多罐形、壶形;长江中下游及沿海地区多鼎形、豆形和深腹罐。从纹饰来看,三者虽然都以动物、植物和编织为主,但是在图案取材、变化以及组织等方面,各具独特风格,其相异程度是一望而知的。 根据上述材料我们能够推测出:',
  null,
  '{"A":"东南沿海地区的纹饰多用菱形等几何体构建","B":"西北地区的纹饰采取动植物和波浪纹等","C":"深腹罐彩陶多在长江中下游地区发现","D":"花草虫鱼的图案都能够在东南沿海彩陶中发现"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '梳理文段的中心句与行文重点后，C项“深腹罐彩陶多在长江中下游地区发现”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择C。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
