(
  '文字-118',
  '文字-118',
  '如果你想要达到最佳状态、表现出色,时刻担心别人的看法只会让你停滞不前。因为对别人怎么评价自己的担心让我们不具理性、效率任下,它的消极影响比实际看起来的还要大。你越来越不关注自身独特的地方,而是屈从于别人对你的看法,那么你就会影响自己潜力的发挥。慢慢地,因为害怕招致批评,你只顾着求稳,不再寻求突破。如果你想要超越自己,不再惧怕他人的看法,你就需要培养更多的自我意识,需要对自己是谁形成一个更强烈、更深刻的认识。践行自己的人生信条,就像吹一个已经充过气的气球一样,需要更多的努力和力量。但这能让你真实、开放地表达自我,激励你带着更多目标和意义去工作和生活。要记得当你到达能力极限时,才有机会获得成长和学习。 这段文字意在说明:',
  null,
  '{"A":"过于在意他人看法的人需要做出改变。","B":"面对他人的评价,我们应该如何反应。","C":"他人的评价只会给我们带来消极影响。","D":"强烈的自我意识是实现自我成长的前提。"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '梳理文段的中心句与行文重点后，A项“过于在意他人看法的人需要做出改变。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
