(
  '文字-119',
  '文字-119',
  '太阳系最开始还有一颗行星,但该行星与地球发生了碰撞,产生的巨大撞击力导致该星球解体,一部分星球碎片留在了地球上,另一部分飘向了宇宙中,由于地球引力的存在,这些碎片并没有飞出去太远。后来,这些碎片比较密集的地方逐渐吸引周围的物体凝聚在一起,最终形成了月球。1946年,科学家戴利认为,月球和地球曾经短暂地在一起过,后来才形成的月球。上个世纪时美国曾带回过月球上的土壤,通过对比发现,这两者的比例是完全一致的。而且,月球上的岩石和地球上的岩石年龄非常接近,这意味地球和月球曾经是一个整体。 由于月球的质量比较小,再加上离地球比较近,所以月球受地球引力的影响较大,才围绕着地球转动,成为地球的卫星。月球受到地球的潮汐力较大,自转速度逐渐被拖慢,最终被锁定,只有一面对着地球转动。 下面最适合本文的标题是',
  null,
  '{"A":"月球是环绕地球的卫星","B":"月球和地球曾经短暂的在一起过","C":"地球和月球本来是一个星球","D":"月球是怎样变成地球卫星的"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
