  '文字-121',
  '文字-121',
  '巴纳姆效应是指人们愿意接受那些过度概括和普遍性的描述。巴纳姆式陈述是对一个特定群体的人格描述 ,这种描述对所有人都适用。也就是说,它是一个对所有人来说都"有些意义"的普遍性陈述。它们遍布大众媒体,以自助读本,星象预报、灵媒热线及数理占卜读物、解梦、手相等形式存在。例如我们可能会很自信地称"移民都有自尊问题", 或者"少数民族对批评都很敏感"或者"性少数群体不欢被拒绝".这一类问题的变种也是无限的,它可以扩大为"印度教徒追求生命的意义"、"法国人喜欢美食"。它们也许在总体上是有效的,但这些描述往往十分模糊及普遍,以致能够放诸四海皆准,而不能体现任何个体或社会文化群体间的差异。减少巴纳姆效应可以通过限定人格描述和解释用词来实现。如将"印第安人欣赏原始农业社会"改成"相较于现代工业化社会,印第安人更为欣赏原始农业社会",这称之为 "去巴纳姆化"。 根据本文内容,下列哪项不属于巴纳姆效应?',
  null,
  '{"A":"\"你强烈地需要别人喜欢并羡慕你,你有时是外向的、友善的,有时又是内向的、谨慎的。\"","B":"\"本周射手座对工作、生活依旧抱有顺其自然的心态,不过你仍然具有较强的积极性,不管是大事还是小事都能认真地做好。\"","C":"\"共和党人关注家庭价值\"","D":"\"比起李丽,张强的性格更加急躁。\""}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '梳理文段的中心句与行文重点后，D项“"比起李丽,张强的性格更加急躁。"”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择D。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-递进关系。',
