(
  '文字-122',
  '文字-122',
  '没有愿景就不存在创造性张力。创造性张力不能由现状单独产生。世界上所有的分析从来都不会产生愿景。那些由于这样做而导致失败的人,就是因为他们试图用分析来取代愿景。他们认为,只要人们了解了现实,就一定会有动力去改变, 然而,他们却失望地发现,人们"抵抗"为了改变现实而必须做出的个人和组织的变革。他们从来没有理解的是:改变现实的自然力来自拥有一个可能成为什么的愿景,而这对人们来说,比事物本身更加重要。 根据上面一段文字,下面说法错误的是:',
  null,
  '{"A":"对于现实的分析不能用来代替愿景。","B":"人们不愿意为了改变现实而进行个人和组织的变革。","C":"创造性张力决定于我们想要成为什么以及我们的现状。","D":"愿景比现实更加重要。"}'::jsonb,
