  '文字-123',
  '文字-123',
  '亚当▪斯密是最先看到劳动分工重要性并解释了其优点的人。以英国大头针的生产过程为例,他将制作大头针的工作分为十八道工序,每道工序由不同的工人分开完成。亚当▪斯密说,用这样的方法每名工人一天大约生产四千个大头针,但如果是全部的工人单独工作的话,一天之中,没有人可以制作二十个大头针。由此可见,劳动分工是一种组织工作的有效方式。亚当▪斯密到了这点,但他"天真地"认为劳动分工是经济增长和发展的根本原因,但劳动分工并未增添新的东西,它只是让人们能够生产出更多已有的产品。 按照材料的理解,亚当▪斯密是第一个',
