  '文字-124',
  '文字-124',
  '胚胎组织的免疫系统发育尚不充分,对外界刺激反应较慢,如果将胚胎组织注射到受外伤的成年人体内,可有效防止伤口疤痕的形成。成年人血小板中的一种生长因子可加快伤口愈合,研制具有抑制这种生长因子作用的药物,在伤口出现12小时内,将该药物敷于伤口部位,伤口愈合后亦无疤痕。 关于上述两种医疗措施的表述,最准确的是:',
