(
  '文字-125',
  '文字-125',
  '古人十分讲究步行美,以此体现人的性格、情趣和风度教养。先秦君子步行鸣佩玉,既喻示着君子言行举止要符合德行的要求,而佩玉之声伴随着步行的节奏,又显示出一种庄重和谐的美。对待步行,儒道两家态度素不相同。儒家容美于善,道家容美于真。汉末至魏晋时代,随着儒学的日益衰落和人们思想的逐渐解放,人们对美的崇尚与追求更为显著,因此节度迟缓不迫、举止舒泰优雅的步行,作为衡量一个人的修养、气质和风度的重要标准,常为品评者称誉。乐府民歌《陌上桑》载秦罗敷在拒绝使君求婚时,就夸说自己的丈夫:"盈盈公府步 ,冉冉府中趋。"古人还把与步行有关的词语用来表情达意。如常见的徘徊、彷惶、踌躇、容与等,就被演化为举步不定、犹豫不决的意思。"徒跣"一词,原义是脱掉鞋子赤脚走路,后演化为表示发怒、着急、匆忙和痛苦的情感。刘邦赦免了萧何,萧何"徒跣入谢", 即是表示急速前往致谢的意思。 下列说法中,与原文不符的一项是',
  null,
  '{"A":"先秦君子佩玉是对现实与抽象之美的双重追求","B":"儒家和道家对步行之美的追求有所差异","C":"儒学的发展促进了人们对美的崇尚与追求","D":"缓慢优雅的步行是魏晋时期的美学追求"}'::jsonb,
