(
  '文字-127',
  '文字-127',
  '成功学大师宣扬的"我最棒"真的可以让人发家致富吗?有研究表明,积极的自我陈述并非在所有情况下都有效,鸡血是否有效取决于个人是否发自内心地相信那些鸡血。那些本来就觉得自己很棒、很有价值的高自尊个体就很容易被"我一定行"的口号燃起斗志,但对那些低自尊的人来说,绝对正面的自我陈述不符合他们内心对自己的评价,百分百积极的口号只会引起他们条件反射式的自我否定。对他们来说,辩证型或成长型的自我陈述可能更加管用。 对低自尊的人来说,最有用的鸡血是:',
  null,
  '{"A":"虽然在这个领域我失败了,但我相信我在擅长的领域能做到很好。","B":"这次不仅我失败了,大部分人也都没有完成,所以我不是最糟糕的。","C":"这次任务有很多次机会可以尝试,所以我不介意失败一次","D":"这次失败是由于我状态没有调整到最好,和我的实力无关。"}'::jsonb,
