(
  '文字-128',
  '文字-128',
  '我们怎样才能增加他人的顺从呢?研究者提出了以下几种技巧。"脚在门槛内技巧" ,也叫登门技巧,第一步先向他人提出一个小的要求,等他人满足该要求之后,再向其提出一个较大的要求。"门前技巧",是先向他人提出一个很大的要求,在对方拒绝之后,紧跟着提出一个小的要求。但是必须满足三个前提:首先,最初的要求必须很大;其次,两个要求之间的时间间隔不能过;第三,较小的请求必须由同样的人提出。此外还有"折扣技巧":第一步是先提出一个很大的要求,在对方回应之前赶紧打些折扣或给对方其他的好处。"滚雪球技巧"指在最初的要求被他人接受之后,又告诉他人由于自己的要求被低估,又提出了新的较高的要求或价码。 下列关于"顺从"的描述,正确的是:',
  null,
  '{"A":"顺从是让别人听从于我们的命令","B":"顺从是让别人答应我们的要求","C":"顺从是让别人答应购买我们介绍的东西","D":"顺从是让别人及时响应我们的需求"}'::jsonb,
