(
  '文字-130',
  '文字-130',
  '云南各民族的生活是丰富多彩的,舞蹈是各民族生活中的重要组成部分。云南各民族舞蹈的自娱性大于表演性,这种寄托了个人情感、为自我娱乐而创造出的自娱性舞蹈,往往能够表现云南的风土人情、历史渊源和生活习俗,能够将舞者的情感贯穿到舞蹈中去,传达给观众,显示出各民族之间伯歌季舞的气氛来。从这些自娱性舞蹈中,我们也能够最大程度地看到舞者对个人生存经验的传达和本民族风土人情的展示。打歌可以说是云南流传最为广泛的舞蹈了,它的特点是载歌载舞,随时随地都可以跳,在各种集会中,它是必不可少的项目,而彝族的打歌又是最有名气的。 下列哪个词语能够代替原文中的"伯歌季舞",且保持原文意思不变?',
  null,
  '{"A":"轻歌曼舞","B":"百兽率舞","C":"伯仲之间","D":"亲密无间"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '伯歌季舞:意思是哥哥唱歌,弟弟跳舞。比喻兄弟之间亲密无间。百兽率舞:意思是各种野兽一起起舞,形容天下太平。伯仲之间:比喻两者不相上下,难分高下。亲密无间:形容十分亲密,没有任何隔阂。选择D',
