values
(
  '文字-131',
  '文字-131',
  '人在受到意外刺激时,第一反应是减少身体动作,保持瞬间静止,以便看清突发状况并判断对策。从这种身体突然僵住或减弱活动的反应中,可以判断出对方感到吃惊,随后可能产生恐惧、愤怒或者喜悦的心理感受。当一个人完整的动作或表情被压缩到极致的时候,表现出来的就不是一个夸张的表情或动作,而是一个极小的反应,极易被人们忽略,这种反应,就是一个微弱的反应,又叫微反应。 根据以上文字,下列说法错误的是:',
  null,
  '{"A":"瞬间的静止是人受到意外刺激的第一反应。","B":"这种瞬间的静止就是一个微弱的反应。","C":"我们可以从瞬间静止的反应中判断出一个人的心理感受。","D":"夸张的表情和动作可以使人们更加清楚地辨别出一个人的感受。"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '由上文可知,人在受到意外刺激时,第一反应是减少身体动作,保持瞬间静止。选项A正确;一个人完整的动作或表情被压缩到极致的时候,表现出来的就不是一个夸张的表情或动作,而是一个极小的反应,极易被人们忽略,这种反应,就是一个微弱的反应,又叫微反应。选项B正确;从这种身体突然僵住或减弱活动的反应中,可以判断出对方感到吃惊,随后可能产生恐惧、愤怒或者喜悦的心理感受。选项C正确;选项D与原文意思不符,所以选择D。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-排除错误项。',
