(
  '文字-132',
  '文字-132',
  '在很多人看来,压力大是因为总觉得时间不够。为了解决这一问题,很多人尝试时间管理, 希望通过"更高效"的方式将一小时会议压缩成半小时,或者在日程表里的空档安排一些小任务,尽量减少无效时间。然而矛盾的是,时间管理往往会增压而非减压。效率提升时,人们会为更多任务腾出空间,感到压力更大。如果感觉不知所措,最好从根本上解决问题。生产力很重要,但在工作倦怠不断蔓延的世界里,人们也需要采取一些策略减少工作,而不是简单地适应。面对各种情况,解决方案并不是提升效率以完成更多任务,做出更多决定,结果不断分心。当务之急非常明确,就是简化,减少承担的任务数量,用原则代替决定,并建立适当的结构消除干扰。 下面对本文内容理解正确的是:',
  null,
  '{"A":"有足够时间的人往往很难感觉到压力的存在。","B":"无效的时间越多,人们感觉到的压力也越大。","C":"只要时间管理得当就能腾出更多的时间轻松完成更多事项。","D":"简化工作比适应工作更有利于减轻人们的压力。"}'::jsonb,
