(
  '文字-133',
  '文字-133',
  '虽然世界因发明而辉煌,但发明家仍常常寂寞地在逆境中奋斗。市场只认同有直接消费价值的产品,很少有人会为发明家的理想"埋单"。世界上有职业的教师和科学家,因为人们认识到教育和科学对人类的重要性,教师和科学家可以衣食无忧地培育学生,探究宇宙:然而,世界上没有"发明家"这种职业,也没有人付给发明家薪水。 这段文字主要想表达的是:',
  null,
  '{"A":"世界的发展进步离不开发明","B":"发明家比科学家等的处境更加艰难","C":"发明通常不具有直接消费价值","D":"社会应对发明家提供更多保障"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '意图判断类题目。材料主要谈了发明家的现实处境,即“市场只认同其有直接消费价值的产品,很少有人会为发明家的理想‘埋单’......也没有人付给发明家薪水。”可知既然“世界因发明而辉煌”,但是发明家处境不是很好,所以当今社会应为发明家提供更多保障。选择D。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
