(
  '文字-134',
  '文字-134',
  '地球上分布着一百多个互不相连且面积不大的火山活动区,地质学家称为"热点区"。和大多数火山不同的是,它们不位于巨大漂移板块的连接点,反而藏于板块的深处。大部分热点区移动极为缓慢,有时,板块滑过这些热点区,便留下死火山的痕迹,热点区及其火山痕迹就是板块移动的象微。如今,板块漂移学说已然毋庸置疑。以非洲和南美洲为例,由于新物质嵌入洋底,两个大陆越来越远,纵然远隔大洋,其相互吻合的海岸线和相似的地理特征会让人想到这两个大陆曾经相连。两个大陆漂移板块做相对运动已得到了详细的说明,但人们还不能确定两个大陆是否在朝相反的方向运动,也不能确定是否一个大陆原地不动,另个大陆正在离它而去。而位于地壳深处的热点区提供了解决这一问题的测量仪。从热点区的人口情况分析来看,似乎非洲板块是固定的,三千万年过去了也没有移动。 作者可能认为哪一项是正确的?',
  null,
  '{"A":"板块的运动与地球内部运动相似","B":"板块漂移学说是科学的","C":"热点区的移动证明大陆逐渐分离","D":"热点与板块向相反的方向缓慢移动"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '热点的重要性不仅限于它们作为参照体系的作用。现在看来,它们还对推动板块在地球表面漂移这一地球物理过程有重要影响。当大陆板块漂移到热点上方,来自地球深层的物质便形成了巨大的圆顶状隆起物。随着这个圆顶的增长,板块出现深深的裂缝。至少有几次,大陆可能会沿着其中的一些裂缝完全裂开了,因此这个热点就引发了一个新的海洋的形成。这样,正像早期的理论解释了大陆的移动性一样,热点理论或许能解释大陆板块的不稳定性。据此分析,作者可能认为大陆应逐级分离是正确的。故选:C',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
