(
  '文字-135',
  '文字-135',
  '认知启发是指由于人们的加工信息能力有限,在认识事物时并不会对所有的信息进行加工, 而是顿向于"抄近路",去加工最明显、最典型的信息。在面对不确定事件时,认知启发法促使人们根据与以往典型事件的相似程度,对当前信息或事件做出判断。这种策略认为:个体越是与某一群体的一般成员相似,就越可能成为该群体中的一员。因为每个群体都有独特的行为风格,其成员总有共同特征,因此通过这种形式进行判断往往是准确的。但是,认知启发往往会产生"基率谬误",即个体因忽视事件发生概率而做出错误判断,因为两个独立事件同时发生的概率不可能高于单个事件发生的概率。人们在运用这一启发法时,习惯于把事物的类型做典型化的划分,进而过分强调某种决策选项的典型性而忽视其发生的概率,这实际上是种认知偏差。 根据材料,人们判断不确定事件的依据是:',
  null,
  '{"A":"事件的发生概率","B":"事件容易被联想的程度","C":"事件的典型性程度","D":"事件与自我的相关程度"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '梳理文段的中心句与行文重点后，C项“事件的典型性程度”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择C。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
