(
  '文字-136',
  '文字-136',
  '最新研究发现,消费者网购时使用的设备会影响他们]对商品的选择。如果用触屏设备(如智能手机、平板电脑等)逛网店,消费者更乐于购买享乐型商品,如按摩设备等。如果用电脑网购,消费者则会更加"实际", 在购物中偏好实用型商品,如洗衣液、手抽纸等。导致这种差异的是人们的思考风格。行为决策中存在经验和理性两种不同的思考风格,前者是一种从日常经验出发,富于情感的思考模式;后者则是从逻辑出发,理性且非冲动的思考模式。使用触屏设备可以将消费者切换至经验思考风格中。消费者用手在触屏设备上操作滑动时,会产生种新奇、 有趣的休验,而这种体验正好与享乐型商品的特点相符合,会强化消费者对它们的偏好。 根据本文内容,下面推断正确的是:',
  null,
  '{"A":"人们在触屏上滑动的感受和享乐型物品带来的感受一样,因此他们更喜欢通过触屏设备购物。","B":"不同的思考风格决定了人们在购物时有些更感性,有些更理性。这两种风格相互排斥。","C":"当人们非常需要样物品时, 可以通过电脑来购物, 避免剁手行为。","D":"如果目前经济紧张,需要精打细算,那么最好在电脑上逛淘宝。"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '逐项对照原文，D项“如果目前经济紧张,需要精打细算,那么最好在电脑上逛淘宝。”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择D。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
