(
  '文字-137',
  '文字-137',
  '印度是一个大市场,"印度制造"进一步为中国在劳动密集型产业转移上获得利润,但并没有让印度成为又一个低成本制造商。相反,印度制造业结合了大量劳动力、技术发展、数字化,意在让印度成为"智能低成本制造"中心。数字化应用使其即使在庞大的劳动力市场中也能极大提高劳动生产率。同时,中国可以从印度获取一些消费需求,例如,中国是全球出境游大国,而印度市场尚属中国游客有待开垦的"处女地",且距离中国不远、价格便宜、拥有古老的文化及热情友好的传统。 下面对本文内容理解不正确的是:',
  null,
  '{"A":"\"印度制造\"让中国在劳动密集型产业转移上获得利润,也使印度有机会成为\"智能低成本制造\"中心。","B":"\"印度制造\"让中国在劳动密集型产业转移上获得利润,也使印度的劳动力、技术发展、数字化开始结合,","C":"印度制造业结合了大量劳动力、技术发展、数字化,即便在庞大的劳动力市场中也能极大提高劳动生产率。","D":"中国可以从印度获取包括旅游业在内的多种消费需求。"}'::jsonb,
