  '文字-143',
  '文字-143',
  '从就业角度看,扩大投资就是为后人增加的"饭碗";压缩投资就是压后人的"饭碗"。"饭碗" 压得过多,虽然有利于今天的稳定,却不利于明天的稳定,不利于中国社会的长治久安。 上面这段话主要支持了这样一种观点,即:',
  null,
  '{"A":"扩大投资就是压缩今人的\"饭碗\"","B":"压缩投资有利于暂时稳定,扩大投资有利于长远发展","C":"扩大投资有利于长远地解决就业问题","D":"压缩投资有利于解决当前的就业问题"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '“饭碗”即就业岗位,所以题干论述的是投资与就业机会两者之间的关系问题。A项错误,扩大投资能为后人增加“饭碗”,并不等于说其会压缩今人的“饭碗”;B项错误,压缩投资“有利于今天的稳定,却不利于明天的稳定”,所以不能笼统地说“压缩投资有利于稳定”;C项正确,因为扩大投资能为后人增加“饭碗”;D项错误,“压缩投资有利于今天的稳定”,并不等于说其能增加就业机会,解决当前的就业问题。',
