  '文字-145',
  '文字-145',
  '压力和焦虑抑郁情绪是怎么对血糖造成不良影响的?慢性压力其实是导致血糖升高的更危险的因素。慢性压力是指长时间具有心理上的压力,并且觉得自己无能为力,无法控制持续性的情绪问题。慢性压力造成由大脑内部下丘脑-垂体-肾上腺轴组成的调控网络分泌的皮质醇不断地涌入血液。肾上腺激素起到升高血糖的作用,在机体出现低血糖时能够很快发挥作用,来纠正低血糖。但是,在慢性压力状态下皮质醇水平持续增高,就会不断作用在肌肉和脂肪细胞中,降低它们吸收葡萄糖的能力;也会使肝脏对胰岛素的反应变得非常迟钝,进而制造出比实际所需更多的葡萄糖。慢性压力也会使身体处于低度的炎症状态下,导致机体对胰岛素的反应性下降。因此,慢性压力状态下会通过多种途径导致血糖的升高,增加糖尿病的风险。 下面对本文内容理解正确的是:',
  null,
  '{"A":"肾上腺激素可降低血糖","B":"慢性压力是一种情绪问题","C":"慢性压力状态下,肾上腺激素分泌水平降低","D":"身体处于炎症状态时,会导致慢性压力"}'::jsonb,
