(
  '文字-147',
  '文字-147',
  '当一项发明成功时,发明者通常有三种行为方式可供选择:通过出版方式把成果免费公布于世、将他的发明保密或者取得专利。取得专利是大多数发明者的选择。取得专利,即获得了某种授权资格,是发明者和国家之间形成的权利契约。根据契约,发明者对自己的发明获得了一定时期的垄断权、保护和隐秘,他人如果要使用,需要经过发明者的授权,否则就造成侵权。但专利的垄断时间并非是永久的,当保护照结束后,专利人应把发明的整个细节公布于众。也正因为此,专利局的架子摆放了成百数千个到期后被公开并可以被任何人使用的专利。针对这种现象,一些专家经常建议那些希望使用专利而不愿付高额费用的人使用过期专利,进而避免冒承他人专利权的风险。 材料的主要关注点是:',
  null,
