  '根据以下资料回答问题:水,是生命的摇篮,也是重要的动力资源。据估算,地球上大约有14亿立方公里的水,其中海水占97.5%, 淡水仅占2.5%,而且在淡水中又有70%是冰,实际上真正可以直接利用的江河湖泊的水量是不多的。估计只占地球总水量的千分之三。 以上资料显示,地球上约有( ) 亿立方公里的水。',
