(
  '文字-153',
  '文字-153',
  '一项调查结果表明, 某水域受到石油泄漏污染后,水鸟的存活率为95%。其根据是附近某动物诊所的统计:该诊所诊治的受污染伤害的水鸟中,有二十分之一死去。 在下列各项事实中,最能对水鸟存活率的结论提出质疑的是:( )',
  null,
  '{"A":"有20%的水鸟受到石油污染的严重伤害","B":"在受污染伤害的水鸟中存活希望较大的才被送到诊所","C":"死去的水鸟是体型较大的水鸟","D":"有些接受过治疗的水鸟又被重新送回诊所"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '本题为质疑题。题目中以在诊所中接受治疗的水鸟有二十分之一死去为依据,断定水鸟的存活率为95%,而B项中提出存活希望较大的才被送到诊所,这样的鸟都有5%死掉了,存活希望不大的鸟死去的可能性就更大了,所以,对水鸟存活率的结论提出了有力的质疑,故本题正确答案为B。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
