  'D',
  '甲说的人口统计发现的规律是整体,是普遍的情况,而乙却以某些地区和国家的个别情况来反驳,而且甲已说明男婴出生率是在22/43上下摆动的,说明女人比男人多的现象还是存在的,乙以片面的、个别的现象来反驳整体显然不合逻辑,应选D项。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
