(
  '文字-156',
  '文字-156',
  '艾森豪威尔烟瘾很大,烟斗几乎不离手。某天,他宣布戒烟,立刻引起轰动。记者们向他提出了戒烟能否成功的问题,艾森豪威尔回答说:"我决不第二次戒烟。"下面各项都可能是艾森豪威尔讲话的含义,除了:( )',
