(
  '文字-157',
  '文字-157',
  '在政策执行过程中,从上到下依然缺乏强有力的机构,专门负责检查监督各种政策的贯彻落实情况。往往是一遇到需要解决的问题,就下发一个文件,作出一些新规定,或成立新机构,而较少关心这些政策的执行情况。由于法律、法规或政策文件的落实缺乏监督保证体系,执行不执行都是一个样,时间一久,令不行,禁不止之风就会自然盛行。因此:( )',
  null,
  '{"A":"必须做到令行禁止","B":"必须加强政策执行的力度","C":"必须加强政策执行机构建设","D":"必须加强政策执行的监督检查工作"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '通过题干第一句话和最后一句话可知,由于在政策执行过程中缺乏强有力的监督检查,从而导致政策无法得到真正贯彻落实,因此需要加强政策执行的监督检查工作。故选D',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
