(
  '文字-159',
  '文字-159',
  '现代社会似乎热衷谈论"大师",越没有"大师"的时代越热衷于谈论"大师",这也符合物以稀为贵的市场原则。但"大师",尤其是人类的"大师",一定是通人, 而不仅是"专家"。但人为的学科分割,根本不可能产生"大师", 只能产生各科"专家"。学术文化真正的全面继承与发展,靠的是"大师"而不是"专家"。"专家"只是掌握专门知识之人,而"大师"才是继往开来之人。缺乏"大师",是学术危机的基本征象。这段话支持的观点是:',
  null,
  '{"A":"没有\"大师\",社会就不可能进步","B":"社会关注错位,并不存在所谓的\"大师\"","C":"人为的学科分割导致了社会缺乏\"专家\"和\"大师\"","D":"\"专家\"不一定是\"大师\", 而\"大师\"必然是一个专家\""}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '此题采用排除法,根据题意,提到了“大师”带给社会的意义,但并不包含没有大师社会就不可能进步的意思,故排除A,由此,也很容易排除B项。根据“但人为的学科分割,根本不可能产生‘大师’,只能产生各科‘专家’”可知,C项错误,故D项正确,符合题意。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-递进关系。',
