(
  '文字-160',
  '文字-160',
  '这是最好的城际竞技场。每一次申办承办,都是一次巧妙的城市公关。 对于新生显贵而言,这的确是千载难逢的登堂入室的绝好台阶。国际奥委会委员们在每一张选票上,并不是单纯的打勾划叉,他们亦在谱绘世界风云榜上城际间的升跌走势图。这段话意在表明:',
  null,
  '{"A":"国际奥委会委员们投票决定承办奥运会的城市","B":"公关工作是申办和承办奥运会成功的关键所在","C":"申办和承办奥运会是世界城市之间互相较量实力的体现","D":"申办和承办奥运会是新兴城市进入国际舞台的绝好契机"}'::jsonb,
