),
(
  '文字-161',
  '文字-161',
  '经过百年的衰落,南水北调工程也许是大运河的最后一次机遇, 倒流的长江水再次串联起大运河的主要部分,生气就此显现。一百年来大运河只是在等待一次让它融入新的文明中的机会。 大运河已经有两千五百年的历史,它并不害怕改变,但是如何改变却掌握在现代人的手中。这段话的主旨是:',
  null,
  '{"A":"南水北调工程是改变大运河命运的重要契机","B":"历史悠久的大运河已经衰落了一-百年","C":"倒流的长江水再次使大运河呈现生机","D":"大运河如何改变掌握在现代人的手中"}'::jsonb,
