),
(
  '文字-162',
  '文字-162',
  '在我国加入世界贸易组织、农业科技迅猛发展的形势下,农业面临的竞争首先是科技竞争。只有尽快提高农民的文化素质和科技意识,才能不断推广大批先进实用的农业科技成果,为农业和农村经济的发展提供有力的科技支撑。我国将继续推进农业和农村经济结构调整,大力发展优势农产品和特色产业,将在粮食主产区推广50个优质高产高效品种和10项关键技术。这些品种和技术的推广和运用都需要高素质的农民。为此,国家已经决定大力发展农村成人教育,在全国普遍开展农村实用技术培训,每年将培训农民超过1亿人次。这段文字的意思是在强调:',
  null,
  '{"A":"农民亟需提高科学文化素质","B":"国家加大农业和农村经济结构调整","C":"发展科技才能提高我国农业的竞争力","D":"每年有大量农民接受农村实用技术培训"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '该文段前两句是说加快农业科技竞争需尽快提高农民文化素质和科学意识,三、四句是说优质品种和关键技术的推广和运用需要高素质的农民。第五句说国家开展农村成人教育,由此可见这段文字意在强调农民亟须提高科学文化素质。正确答案为A。B项、D项都只是措施之一。C项用总概念偷换了属概念,文段谈的主要是提高农民的科技水平,而并非“发展科技”。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
