  '文字-165',
  '文字-165',
  '在试图与外星人沟通的历史上,人类充满了挫败。与外星人沟通,让人有一种无从着手的感觉。20世纪70年代,飞向太阳系之外的"先驱者"号和"旅行者"号探测器上,都被设计搭载了金属制成的人类名片。人们希望当探测器在飞出太阳系后能够被什么外星智慧</span><em class="em inline"><span>拾获</span></em><span>,发现我们的存在。它们除了携带金属名片外,还载有记录了地球照片和声音的磁盘。这样,外星人有可能会注意到我们是一支拥有科学的文明,然后与我们取得联络。但这种思路却遭到-些社会学家的质疑。他们怀疑,假如外星智慧是高度发达的文明,比地球人还要先进很多的话,也许会认为我们太低等了,导致外星人不屑于回复我们的信息。 文中第二段中的斜体"拾获"可以用下列哪个词代替并不改变词意。',
  null,
  '{"A":"拾掇","B":"捡取","C":"遗失","D":"寻获"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '拾获的意思是拾取、获得。拾掇:采拾、拾取;捡取:捡起;寻获:找到。所以选择A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
