(
  '文字-166',
  '文字-166',
  '为了探究怀孕过程中心理压力的影响,俄亥俄州立大学哥伦布分校的研究者,在美国收集了373名刚开始尝试自然受孕妇女的唾液样本,然后测量了一种可以用来指示心理压力大小的a-淀粉酶水平。研究人员发现,a-淀粉酶水平最高的妇女患有不孕不育的可能性,是a-淀粉酶水平最低的妇女的2倍。过往研究发现:在尝试怀孕的第一个月中, "压力酶"水平较高的人是不太可能成功受孕的。但本次是她们首次将a-淀粉酶与临床准确定义的不孕不育症联系起来。但是这项研究并没有揭示该现象可能的机制是什么,也没有研究男性的压力水平是否也会对妇女受孕产生影响。伦敦大学学院医院的医生指出:"这可能是我们所承受的压力导致了生理变化,或者仅仅是因为人们在面临生活压力时,减少了性行为的次数。"但是该研究的研究者并不同意这种观点。研究者认为:心理压力可能会造成目前无法解释的不孕不育症,而掌握这些相关的知识,可以帮助夫妇采取行动,解决问题。 以下内容在材料中提及到的是',
  null,
  '{"A":"用于研究的是尝试受孕的妇女的唾液样本。","B":"不孕不育的临床准确定义。","C":"患有不孕不育症的夫妻比例。","D":"研究结果可能会让人承受更大的心理压力。"}'::jsonb,
