(
  '文字-167',
  '文字-167',
  '读书是一件耗神的事儿,需要外部世界的信息来辅助记忆。其中最有效的方法就是将抽象的词形象化,通过具体物质锚点帮助记忆。阅读紙质书的过程中,指尖的触感,手指翻页的摆动幅度、手掌承受的重量,都起到了类似锚点的作用,帮助我们记忆。纸质书与阅读的记忆同在,其作用类似于某种气味突然勾起了段回忆,一个玩具让你想起了小时候的快乐时光。而阅读电子书,无论是深奥复杂的哲学书,还是轻松的言情小说,指尖的触感、手指翻页的摆动幅度、手掌承受的重量都是一样的,人拥有的完全是对文字的抽象记忆。因此人们在阅读电子书时的记忆难度远远大于纸质书。 下面最适合本文的标题是:',
  null,
  '{"A":"阅读纸质书和电子书的差异","B":"错点如何影响抽象记忆","C":"阅读纸质书,记忆更深刻","D":"锚点,让读书不再费神"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '标题需要同时覆盖文段的核心对象和主要内容。C项“阅读纸质书,记忆更深刻”概括范围最完整，也符合标题简洁准确的要求，因此选择C。',
  '先提炼核心对象和核心事件，再检查标题是否准确、全面且简洁。 本题重点：议论文。',
