(
  '文字-168',
  '文字-168',
  '我们的世界处于大变局之中,但如果只看到不确定性,只看到动荡、复杂、模糊、易变,心中就会不安、骚动、浮躁,就缺乏安稳、平静、安全。事实上,变化的只是外部环境,只是达成商业目标的手段和形式。商业世界的本质与使命、确定使命的基本准则、战略思维的核心理念与架构,是长期的,相对稳定的。只要心中有长期恒定的坚守,面对动荡不确定的未来,就可以降低迷茫与困惑,从容驾取不确定性,而不是成为不确定性的奴隶。长期主义为这样的信念所驱动:重视长远通常不会失去眼前,但仅仅重视眼前则常常会失去长远。所谓长期主义,就是在这种信念驱动下,企业形成的以长期价值提升为核心目标的系统化的战略思维,并保证核心利益相关者围绕着企业长期价值进行决策、选择行为的机制安排。 根据原文内容,下列推断不正确的是',
  null,
  '{"A":"世界格局不断变化,企业的核心利益相关者,如股东、核心员工等要以企业当下情况为第一出发点来考虑企业的决策。","B":"没有长期意识、长期坚守的组织,面对不确定、面对风浪,心中无根,自然随波逐流,漂泊不定,不知在何处倾覆。","C":"只有在长期坚守的理念、信条支持下,企业才能选择正确的战略,设计有效的管理机制,才能在动荡的时代保持成长和繁荣。","D":"商人为了眼前利益,坑蒙拐骗,囤积居奇,造假抬价,是因为没有驾取不确定性,没有长期稳定的坚守。"}'::jsonb,
