(
  '文字-171',
  '文字-171',
  '父亲忽然看见两位先生在请两位打扮得漂亮的太太吃牡蛎。-个衣服襤褛的年老水手拿小刀一下撬开牡蛎,递给两位先生,再由他们递给两位太太。她们的吃法很文雅,用一方小巧的手帕托着牡蛎,头稍向前伸,免得弄脏长袍;然后嘴很快地微微一动,就把汁水吸进去,蛎壳扔到海里。毫无疑义,父亲是被这种高贵的吃法打动了,走到我母亲和两个姐姐身边问:"你们要不要我请你们吃牡蛎?"母亲有点迟疑不决,她怕花钱;但是两个姐姐赞成。母亲于是很不痛快地说:"我怕伤胃,你只给孩子们买几个好了,可别太多,吃多了要生病的。"然后转过身对着我,又说: "至于若慧夫,他用不着吃这种东西,别把男孩子惯坏了。" 父亲请家人吃牡蛎的动机是:',
