(
  '文字-172',
  '文字-172',
  '曾经有一句流行语,说的是"天空飘过五个字....如今观看网络电影、 网剧或网络综艺节目,时常是屏幕飘过一串字,蔚为壮观,甚至对整个屏幕实现全方位的覆盖,形成另-种意义上的"霸屏"效应。弹幕评论已经成为人们在观看网络文艺节目时难以忽视的存在。有的刚开始观看就启动一键屏蔽的功能,让屏幕回归以往的干净,安心欣赏节目本身;有的却在满屏的弹幕飞速滚动之中饶有兴趣、见缝插针地体味节目的起承转合;有的关闭一会儿弹幕,又开启一阵,在交替之间,感受别样的观看体验;有的将弹幕视为网络文艺节目的一个组成部分,甚至还有直接奔着弹幕去的,对看弹幕的兴致压过了看节目的欲望;有的干脆参与其中,一边观看节目,一边脑洞大开,有话要说,而且是马上就要说,随手输出一条又一条的弹幕,成为"生产者"创作者"。 下面内容最适合本文的标题是:',
