  '文字-173',
  '文字-173',
  '有人像百灵鸟一样早起早睡, 也有人像猫头鹰一样晚起晚睡。有研究者认为晚睡晚起的人更聪明,他们测量了新兵的昼夜节律得分、记忆力、敏捷性,结果发现越是早起早睡的新兵,他们在记忆力和敏捷性方面都要弱于晚起晚睡的同伴。在创造思维的所有维度上(流畅性、灵活性、独创性以及跨越性),猫头鹰型的人得分都要高于百灵鸟型的人,特别是在独创性方面。猫头鹰型的人更喜欢使用右脑思考,强调直觉和综合,而百灵鸟型的人更喜欢使用左脑思考,讲究逻辑和分析,而创造性跟右脑有更密切的关系。研究中参与者的年龄从19岁到76岁,具有相当广的年龄跨度。 下面对本文内容理解正确的是:',
  null,
  '{"A":"晚睡晚起和早睡早起对记忆力和敏捷性的影响在新兵中表现最为明显。","B":"创造性思维中的独创性会影响人们使用左脑还是右脑思考。","C":"猫头鹰型的人创造性更高,直觉和综合性更强,这一结论在不同年龄段都适用。","D":"比起晚睡晚起的人,早睡早起的人在记忆力和敏捷性以及创造性方面都较弱。"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '由题意可知:选项A,文中并未提到影响在新兵中表现最为明显。所以A错。特别是在独创性方面。猫头鹰型的人更喜欢使用右脑思考,强调直觉和综合,而百灵鸟型的人更喜欢使用左脑思考。文中意思是早睡早起还是晚睡晚起,影响创造性思维中的独创性,使人们使用左脑还是右脑思考。所以B错。选项C,前半段对,在不同年龄段都适用,文中并未提到。所以C错。他们在记忆力和敏捷性方面都要弱于晚起晚睡的同伴。在创造思维的所有维度上(流畅性、灵活性、独创性以及跨越性),猫头鹰型的人得分都要高于百灵鸟型的人。所以D对,所以答案选D。',
