  '文字-174',
  '文字-174',
  '在中国传统医学中,许多水果被归为寒凉食物,吃多易腹泻。是否是水果中富含的果糖引起的呢?果糖是一种单糖,食物中的单糖不用经过消化,就能被小肠直接吸收到血液中。但果糖抵达小肠需要一种称为GLU5的蛋白质作为载体。载体的数量有限的,如吃的果糖太多,留在肠道内的没被吸收的果糖会使得肠液的渗透压高于血浆,水分流到肠道里。同时,果糖到了结肠,滋养结肠处的细菌,并使其发酵产生短链脂肪酸和大量气体,刺激肠道蠕动,肠道里的水分更无法被吸收,以致腹泻。正常人一次能够吸收25-50克果糖,而果糖载体运输效率差的个体一次能够吸收的果糖少于25克, 所以易出现腹痛、脂泻,这叫膳食果糖不耐。还有一种遗传性果糖不耐症, 是由于肝脏内缺乏分解果糖的酶。 以下对果糖理解正确的是: ( )',
  null,
  '{"A":"果糖摄入量高就会产生腹泻","B":"果糖需要蛋白质的运载才能进入到小肠的血液中","C":"果糖被吸收的前提是:先被消化","D":"果糖会减低血浆中的渗透压"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '由题意可知:果糖摄入量高容易产生腹泻不是一定会腹泻。所以选项A错。果糖是一种单糖,食物中的单糖不用经过消化,就能被小肠直接吸收到血液中。但果糖抵达小肠需要一种称为GLU5的蛋白质作为载体。所以B对。C错。如吃的果糖太多,留在肠道内的没被吸收的果糖会使得肠液的渗透压高于血浆。所以D错。所以答案选B。',
