  '文字-176',
  '文字-176',
  '生物芯片是根据生物分子间特异相互作用的原理,将生化分析过程集成于芯片表面,从而实现对DNA、RNA、多肽、蛋白质以及其他生物成分的高通量快速检测。相比基因芯片产业在国外发达国家的高速发展,国内基因芯片市场明显处于起步阶段,还未形成产业化,在分子诊断领域未得到广泛应用,仅仅应用在生物信息等科研领域,市场规模很小。其原因一是国内基因芯片应用领域开发不足,下游目标用户少,研发力度也略显不足;二是单个基因芯片诊断成本较高,个别推广对于患者无法承受。 下面对本文内容理解正确的是:',
