  '文字-177',
  '从垂直高度来看,世界人口分布的不平衡性十分明显。海拔200米以下的陆地面积占27.8%,而居住在这一高度内的人口比重却占到56.2%,200米500米高度的陆地面积占全部陆地的29.5%,而肩住在这一高度内的人口为24%,500米一1000米高度的陆地占总面积的19%,人口占11.6%。也就是说,世界人口90%以上是居住在海拔1000米以下的比较低平的地区。尽管目前世界上最高的永久性居民已达海拔5000米的高度(南美洲的安第斯山区和我国西藏)最高城市也达到海拔3976米(波利维亚的波托西)。 世界上海拔最高的城市是哪一个 ?',
