(
  '文字-178',
  '文字-178',
  '养成运动的好习惯,究竟可以给我们带来怎样的好处?坚持运动的人,身材会更紧致,机体摄氧能力更强,基础代谢更高。不仅如此,人们还发现,运动能改善不良情绪,使人精神欢愉,甚至有效预防和治疗神经紧张、失眠、 烦躁及忧郁等症状。总而言之,就是保持运动习惯的人,会比不运动的同龄人看起来更年轻、更精神,也更美。除了永葆年轻,运动还能让你变得更加聪明!美国科学家曾经用了35年的时间,对400名成年人进行了一系列的测试研究,最终得出一个结论:坚持锻炼的人,在智力和反应方面明显高于很少运动的同龄人。除此之外,《美国国家科学院院刊》 也曾有报告说:与久坐的同龄人相比,那些经常锻炼的人,海马体的体积增加了2%。而海马体,主要负责长时记忆的存储、转换和定向等功能。也就是说,长期坚持运动的人,记忆力会得到提升,也会更加聪明,年老之后患老年痴呆的概率也会更低。 下面内容最适合本文的标题是:',
