  '文字-180',
  '文字-180',
  '自然资源稀缺,产权就非常重要。因为产权明确,人们再也不会超负荷放牧。到发达国家农牧业地区看过的人都知道,分割牧场使用的都是铁丝网,这完全是君子界线,堵不住小人。但是在一个法制的社会,这种防君子不防小人的界线,是具有法律权威的。难怪有一本书说铁丝网是十九世纪人类社会十大发明之一。 下面不符合这段话所表达的意思的是:',
