(
  '文字-181',
  '文字-181',
  '过去,管理者的选拔和晋升,在很大程度上依赖于他们管理和评估员工在特定任务上的表现的能力。可是,"管理的主要职能应当是指导"这一观念在疫情中受到检验。远程工作常态化,加速应用技术管理员工,员工期望的改变这三大颠覆性、变革性的趋势冲击着管理职能的传统定义。要在这样的新环境下取得成功,管理者必须有同理心。而培养同理心,需要高度的信赖和关切,从而在团队内部建立起接纳文化。组织还需要投入资源设置专门职位提供支持,建立起支持体系,让管理者明白并非自己-一人承担重荷,他们就会更有动力培养和表达同理心。此外,管理者负责的团队规模只应该要在自己能把握的范围内,这样才能花时间与员工建立更深的联系,并以同理心应对问题。 这段文字意在说明:',
  null,
  '{"A":"高效的管理者应该具备怎样的能力。","B":"管理新时代员工需要有同理心的管理者。","C":"疫情背景下应该如何更新管理者的管理思路。","D":"疫情后时代管理者的灵活性至关重要。"}'::jsonb,
