(
  '文字-183',
  '文字-183',
  'VR,是Virtual Reaity的简称,意为虚拟现实。这种技术利用计算机图形系统和各种接口,如数据手套、眼球跟踪装置和超声波头部跟踪器等,生成可交互的的三维世界。与3D的"视觉欺骗"不同,VR不仅能让用户完全融入到虚拟环境中,还能捕捉用户的意图、举动,及时互动。VR应用系统分为三个部分:一是体感输入,通过摄像头等捕捉人的肢体姿态。二是虚拟三维场景。这也是VR与3D最直观的区别。VR实现了720度全景无死角,在水平360度的基础上,增加垂直360度的范围能让人看到天"和"地"的全景。三是显示与反馈,使用屏幕将虚拟场景显示出来,并通过多自由度运动平台等反馈力和运动。触觉反馈甚至可以模拟出中弹的感觉。VR广泛应用于娱乐社交、医疗保健、销售、教育、工程设计和军事训练六大领域,但在改变人类生活的同时也可能导致现实生活与虚拟生活的混淆。 根据本文内容,下面理解正确的是:',
  null,
  '{"A":"目前VR只应用于娱乐社交、医疗保健、销售、教育、工程设计和军事训练六大领域,是一门新兴的技术。","B":"VR系统-共有三个部分,其中触觉反馈是最重要的一步。","C":"VR的主要目的是通过虚拟情景捕捉用户的意图、举动,进而分析用户的心理状态。","D":"人们可以通过VR虚拟出来的三维场景看到上下、左右和前后的全景。"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '梳理文段的中心句与行文重点后，D项“人们可以通过VR虚拟出来的三维场景看到上下、左右和前后的全景。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择D。',
