  '文字-184',
  '文字-184',
  '长久以来,风俗从未被当成一个伟大的主题被研究。实际上,它与大脑的内部活动一样,是一种思维活动的同时,更是一种行为活动。这种行为活动在社会中有着令人惊奇的作用。没有人能够用最原初的眼光看待世界,他总会受到来自于特定思维方式的影响,甚至在哲学家的探索路途中也不能避免这些典型现象。同样,关于对与错的概念,它也会受到特定风俗的影响。一个人从出生起,他所在的团体中的风俗就会塑造他的经历和行为,进而促使其形成信念,这点是毋庸置疑的。 材料的中心思想是:',
  null,
  '{"A":"风俗的实质","B":"风俗在社会中的作用","C":"风俗对我们经验、信念形成的影响","D":"研究者对风俗研究的漠视"}'::jsonb,
  '{}'::jsonb,
