(
  '文字-186',
  '文字-186',
  '麻醉剂是一种使身体局部或全身暂时性失去知觉的药物,它施用于即将进行外科手术的患者,麻醉剂方面使他们免受痛苦,另一方面,病人在手术过程中的安静也有助于医生开展工作。在现代麻醉剂还没有发明之前,医生曾尝试各种手段去麻醉病人,例如使病人呼入一定量的乙醚气体使他们失去意识,让他们在漫长的手术中失去感觉。而今天,麻醉师通常会采用气剂或注射药品两种麻醉剂。在一些需要全身麻醉的重要手术,气剂和注射品有时会并用,在一些仅需麻痹部分神经的手术中则仅进行注射药品的局部麻醉,例如牙医在拔牙或补牙前用的奴佛卡因的方式,就属于这一类。 材料最合适的标题为:',
