(
  '文字-189',
  '文字-189',
  '两个人是否能成为朋友,接近性是一个强有力的预测源。事实上,地理距离并不是关键,入们的生活轨迹相交的频率才是关键。我们常常和那些共享居住区入口、停车场和娱乐场所的人成为朋友。为什么接近会诱发喜欢呢?其中一个原因便是易得性,还有一个原因是:熟悉不会导致轻视,也就是说,熟悉请发了喜欢。有关研究表明,对于各种新异刺激的喜爱程度会受它们的曝光程度影响。曝光次数的增加会提高人们时客体的评价这就是"曝光效应"。有学者指出,曝光效应有助于我们的祖先把熟悉的或安全的事物,与不熟悉的或不安全的事物区分开来,曝光效应还使我们在评价他人时戴上有色眼镜,我们会对熟悉的人评价更高。 基于原文,对"熟悉不会导致轻视",理解正确的一项是',
  null,
  '{"A":"在我们生活中出现频率高的事物,我们一般不会讨厌。","B":"如果一个人在我们生活中出现的次数越多,我越喜欢他。","C":"我们越熟悉的人,我们对他的评价越高,","D":"我们对熟悉的人评价都很高,"}'::jsonb,
  '{}'::jsonb,
