  '文字-191',
  '文字-191',
  '绿化地带能够提高城市环境质量这个观点已经被很多人所接受,虽然这并没有经过严格的科学论证。传统的城市规划把生活区、住宅区、娱乐区和交通地段彼此分隔开来,从而更多地重视远离住宅区的娱乐设施而忽视改善住宅地段周围的娱乐设施,而实际上人们却有相当一段时间是在家附近活动。因此,户外的娱乐活动应该始于家门,城市环境如果能尽可能地多地为人们提供娱乐用的绿化地带,才能使人们的生活真正舒适。 根据材料,我们知道:',
