(
  '文字-192',
  '文字-192',
  '最近,阿拉巴马大学综合癌症中心的研究团队再次证实,九价HPV疫苗加德西(Gardasil 9)可以有效预防HPV感染,减少90%的宫颈癌的发生,而且保护效果可以持续6年。HPV病毒又被叫做"人乳头瘤病毒"。目前已知的HPV有超过150种病毒亚型,而其中的一些高危病毒亚型,还会导致癌症。而99.7%的宫颈癌都是由于感染HPV造成的。感染HPV后大概需要很久才可能导致癌症,并没有明确的方法知道哪些人在感染HPV后会诱发癌症。因HPV感染的癌症,包括宫颈癌,阴道癌、阴茎癌、肛门癌早期通常都没有什么症状。新一代的九价加德西疫苗,将可预防的HPV类型增加至了9种,在长达8年的时间里让90%的宫颈癌可以被避免。毫无疑问,这个疫苗是相当有效的。 上述材料的主旨是:',
  null,
  '{"A":"HPV感染与宫颈癌密切相关。","B":"新一代的HPV病毒疫苗的推广是一个挑战。","C":"新一代的HPV病毒疫苗非常有效。","D":"并不是所有的HPV病毒感染都会引发癌症。"}'::jsonb,
  '{}'::jsonb,
