  '文字-194',
  '文字-194',
  '在过去很长一段时间内,银行等持牌金融机构亦为企业恶意逃废债所困,但随着央行征信系统的接入,曾经因逃废债不堪重负的银行终能放下"重担"",轻装上阵。但这并不代表着所有的机构都能像银行如此"幸运"。近年来,金融科技机构以便捷、高效之优势在市场上迅速崛起,向传统金融机构无法覆盖的人群提供服务,这也决定了其需要面临更多的风险。最大风险便是遭遇恶意逃废债。"一些借款人逃避还款、趁机闹事,干扰平台的正常经营秩序,逃废债问题已经严重影响行业未来发展。"一名地方监管的行业人士直言,近年来,金融科技行业监管趋严,再加上经济处于下行周期,叠加借款人恶意逃废债等情况,不少金融科技平台无奈倒下。 根据本文内容,下面推断正确的是:',
