  '文字-197',
  '文字-197',
  '据考古发现证明,在距今4000-5000年之前的埃及古墓中发现了最早的玻璃艺术品,甚至是玻璃壁画。人们推测,埃及最早发明了玻璃制造术并陆续传到欧洲各国。也有另一种说法: 公元前10世纪前后在地中海沿岸活跃着善于航行的腓尼基人,有一次,一只满载苏打的商船在大海中遇到强烈的飓风,被迫驶到河湾里暂避。水手们在这里做饭时,把船上的苏打当作炉灶的支架,事后在偶然的机会中发现产生了像玻璃样的物质,推测这可能是由于苏打与沙粒融合的结果。于是,腓尼基人最早学会了制造玻璃。 从材料内容出发,玻璃最有可能是先由谁制造的:',
