(
  '文字-198',
  '文字-198',
  '他人大量的需求令人生畏,深思熟虑后的拒绝也是一种自我保护。在答应或拒绝一个需求时,你就是在决定将自己的资源投到哪里,所以要谨慎考虑,要坚持让对方明确包括成本和收益在内的各个方面的需求。除此之外,在正确的时间深思熟虑地拒绝可以给相关人员节省时间、免除麻烦。好的拒绝,重要的是时机和逻辑,你应该拒绝不能做、做不到或综合考虑各种因素后,不应该做的事情。拒绝的目的是为了接受更有价值的需求,这将提升自我的价值、建立良好的关系并提高声誉。这样的好需求会让你把时间、精力和资源投入到很有可能成功的事情上,并带来巨大的潜在利益。想要保持长期成功就要擅长合理拒绝同时让对方感觉到被尊重。 下面对本文内容理解正确的是:',
  null,
  '{"A":"为了维护良好的人际,个体应该不加区别的对待他人的需求。","B":"面对他人的各种需求,你更容易拒绝他人提出粗略的需求。","C":"匆忙决定、处理失当的拒绝,会给每个人特别是给自己带来麻烦。","D":"接受他人的需求只会浪费时间、精力和金钱,还让自己在真正重要的事上分心。"}'::jsonb,
