  '文字-199',
  '"厌恶敏感度"可以测试你对恶心事物(看挤痘痘的视频)的敏感程度。它不是去测试你有多容易被恶心到,而是这种感觉来临的时候有多强烈,以及由此你有多困扰。这不是种不变的情绪,人可能对某些情境的敏感度高,但对其他情境无感。其中暴露会影响每个人具体的厌恶敏感度。假如在你生活的社会中,某件事被认为很恶心,你便会很少遇到这件事,因此对它有高厌恶感。研究者据此提出了良性受虐狂的概念,这些人会通过情绪和感觉的起伏,如坐过山车的恐怖感、吃辛辣食物的灼热感或拉伸酸痛肌肉时的痛感来获取愉悦感,以避免更大的不愉快。保持良性的一个关键因素,就是让人感觉安全的环境,或者精神上的愉悦超过了身体。你享受正在发生的事情,是因为你知道它不会真的伤害到你。 下面对"厌恶敏感度"理解正确的是:',
  null,
  '{"A":"不同人的厌恶敏感度不同,每个人的厌恶敏感度也会不断变化。","B":"厌恶敏感度越高的人越容易对被挤痘痘的视频恶心到,并获得愉悦感。","C":"如果在当下社会中,挤痘痘不再被认为是恶心的事,人们就不会厌恶它了。","D":"厌恶敏感度主要形容的是人们的恶心程度和被恶心带来的各种情绪。"}'::jsonb,
