(
  '文字-201',
  '文字-201',
  '提到进化论,很多人想到的是达尔文的进化论,并且认为进化论中的"进化"是不对的,应该是演化。而且在网络上还有种声音,认为进化论是错的,并指出既然人是由猿类演化而来的,那为什么现在的黑猩猩没有演化成人呢?其实现在的进化论并不仅仅是达尔文的进化论,达尔文相当于开了一个头,后续有无数的科学家又继续为进化论添砖加瓦,也就是说,进化论本身也在进化,现在的进化论已经和达尔文没多少关系了,所以我们把现如今的进化论称之为"现代进化论"。黑猩猩之所以不会演化成人类,是因为直立行走的基因属于突变型基因,这种基因出现的概率非常低,低到就像人类演化出翅膀样。 而且,即使这种基因能够出现,黑猩猩还需要一系列的基因突变, 才能真正适应直立行走。 根据对文本内容的理解,下面推断正确的是:',
  null,
  '{"A":"当代社会人们认为进化论是正确性。","B":"现代进化论是从达尔文时期开始不断发展和修正的结果。","C":"只要突变型基因出现,黑猩猩就能演化成人。","D":"人类是可以进化出翅膀的。"}'::jsonb,
  '{}'::jsonb,
  4,
