(
  '文字-203',
  '文字-203',
  '最新研究发现你心中认定是朋友的人,只有53%的人也把你当朋友。研究者让一群大学生按照五分制始其他人打分: 0分是完全不熟,5分意味着最好的朋友。同时他们还要按照五分制猜测别人给自己的打分。在所有评分中,那些把他人当朋友的大学生有94%认为对方也把自己当朋友。但在所有数据中,只有53%的友谊是双向的,即双方给对方的分数都大于3.其他47%的"友谊"都只是一厢情愿,这一研究结果目前只在大学生中得到了验证。之所以对友谊存在高估,研究者认为人类有"情感防卫"本能,"他/她没把我当朋友"的意识会伤害自我感情和自我形象。因此,对于"别人爱不爱我"这件事,很多人的感知都会出现偏差--往乐观那边偏。 下面最适合本文标题的是:',
  null,
  '{"A":"我们不是真正的朋友","B":"过度乐观:我认为我们是朋友","C":"单向友谊:你说我们不是朋友","D":"友谊:保护自己的假象"}'::jsonb,
  '{}'::jsonb,
