  '文字-204',
  '文字-204',
  '"羊群效应"是指管理学上一些企业的市场行为的一种常见现象。经济学里经常用"羊群效应"来描述经济个体的从众跟风心理。羊群是一种很散乱的组织,平时在一起也是盲目地左冲右撞,但一旦有一只头羊动起来,其他的羊也会不假思索地一哄而上,全然不顾前面可能有狼或者不远处有更好的草。因此,羊群效应"就是比喻人都有一种从众心理,从众心理很容易导致盲从,而盲从往往会陷入骗局或遭到失败。"羊群效应" 的出现一般在一个竞争非常激烈的行业上, 而且这个行业上有一个领先者(领头羊)占据了主要的注意力,那么整个羊群就会不断摹仿这个领头羊的一举一动,领头羊到哪里去吃草,其它的羊也去哪里淘金。 根据本文内容,下面推断正确的是:',
  null,
  '{"A":"竞争激烈的行业必然存在\"羊群效应\"。","B":"如果行业领先者(领头羊)占据了主要的注意力,那么整个羊群一定会不断摹仿。","C":"从众心理是\"羊群效应\"的内在机制。","D":"只要从众就是\"羊群效应\"。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '由题意可知:"羊群效应" 的出现一般在一个竞争非常激烈的行业上。文中是一般会出现,并没说是必然会出现。所以A错。如果出现了羊群效应行业领先者(领头羊)占据了主要的注意力,那么整个羊群定会不断摹仿。所以B错。C对。羊群效应"就是比喻人都有一种从众心理,从众心理很容易导致盲从,而盲从往往会陷入骗局或遭到失败。而不是只要从众就是羊群效应。所以D错。所以答案选C。',
