(
  '文字-205',
  '文字-205',
  '自然界中每天都有不可计数的动物死亡。动物尸体分解速度缓慢,容易积瘸许多动物尸体,如果大量的动物尸体不能快速分解,那么该尸体上携带的微生物将会传播到附近生活的动物,引发动物瘟疫,之所以地球没有发生这样的情况,是因为食腐动物的存在,它们能快速将死亡生物上的肉类消灭干净,大大加快了尸体分解的速度,因此食腐动物又被称为"自然界的清理工"。一旦病毒在动物之间传播, 将会导致该地区的动物集体生病, 但在自然界却很少发生动物大规模生病。因为食腐动物把会传播病毒的动物尸体都吃了,食腐动物的胃酸非常强大,能够杀死大多数病毒,再加上免疫力非常强,即使是毒性较强的肉毒表都无法对它们起作用,因此食腐动物是动物界重要的一道防线。 下面最适合本文的标题是',
  null,
  '{"A":"食腐动物是\"自然界的清理工\"","B":"食属动物是动物界重要的一道防线","C":"如果没有食腐动物,地球的动物可能早就灭绝了","D":"毒性再强烈的病毒对食腐动物也不起作用"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '由题意可知:食腐动物不仅能吃掉死亡的动物,还能杀死大多数病毒,防止自然界发生大规模的动物生病。标题要有简洁概括性。所以答案选B。',
  '先提炼核心对象和核心事件，再检查标题是否准确、全面且简洁。 本题重点：说明文。',
