(
  '文字-209',
  '文字-209',
  '城市雕塑的发生发展与建筑雕塑休戚相关。西方城市历程中大量的城市雕塑艺 术品都是建筑的装饰部分或者组成部分。从希腊的人形廊柱到广场雕塑,西方古典艺术中雕塑与建筑向来是一种共生关系。例如,为了与城市雕塑形成对照,我们把建筑雕塑分为室内和室外两部分,室外建筑雕塑虽然建筑是主体,雕塑是依附,但就总体而言,无论是地域范畴还是造型范畴我们都应当将其直接纳入城市雕塑的范畴之类,而且应该说是城市雕塑的重要组成部分。 根据上述材料,我们可以推断出:',
