(
  '文字-212',
  '文字-212',
  '虽然今年全国各地陆陆续续发生了一些小规模的旱灾,但在十八级台风山竹面前,不过是( )而已。 填入括号内最恰当的词语是:',
  null,
  '{"A":"引虎拒狼","B":"疮疥之疾","C":"肘腋之患","D":"祸起细微"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '由题意可知:前面小规模的旱灾,后面十八级台风山竹,后面的事情比前面的事情大得多,前面的事情不过是很小的祸患。引虎拒狼:比喻引进另外一种恶势力来抗拒原来的恶势力,其祸患将更甚。疮疥之疾:比喻轻微的祸患。肘腋之患:近在身边的祸患。祸起细微:灾祸发生在小事情上。所以答案选B。',
  '先判断上下文逻辑关系，再比较词义、感情色彩、程度和固定搭配。 本题重点：题干逻辑-转折关系。',
  '入门',
  '文字推理',
  '逻辑填空',
  '["题干逻辑-转折关系"]'::jsonb,
  '北森言语理解',
  null,
  214,
  '{"kind":"verbal","analysisSource":"原题解析","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-213',
  '文字-213',
  '人们不喜欢丢掉自己的原有"地盘",不喜欢丢面子。他们往往陷入一种思想陷阱,也就是经济学家所说的"沉没成本",它指一种时间和金钱的投资,只有在产品销售成功后才可顺利回收。在英语国家中,也被称为"将钱掉进排水沟里"。 这段文字意在告诉我们:',
  null,
  '{"A":"很多人有怀旧情绪,不善于放弃","B":"所有金钱和时间上的投资都会得到回报","C":"计算投资成本时,应该把沉没成本也加进去","D":"当决定是否进行投资的时候,必须忘掉自己过去的投资"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '本题主要考查考生理解文意概括中心的能力抓住中心句,围绕中心说明问题这段文字的中心句为第一句,"人们不喜欢丢掉自己的原有''地盘'', 不喜欢丢面子",说的是人们在社会中处理问题时的选择,后面文字全部用了一个比喻,将此比喻为经济学中的"沉没成本",这段文字的本意是告诉我们一个社会学的问题,而非经济学上的问题。故B、C、D项都属于肤浅理解文意。故选A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
