(
  '文字-215',
  '文字-215',
  '在中国传统医学中,许多水果被归为寒凉食物,吃多易腹泻。是否是水果中富含的果糖引起的呢?果糖是一种单糖,食物中的单糖不用经过消化,就能被小肠直接吸收到血液中。但果糖抵达小肠需要一种称为GLU5的蛋白质作为载体。载体的数量有限的,如吃的果糖太多,留在肠道内的没被吸收的果糖会使得肠液的渗透压高于血浆,水分流到肠道里。同时,果糖到了结肠,滋养结肠处的细菌,并使其发酵产生短链脂肪酸和大量气体,刺激肠道蠕动,肠道里的水分更无法被吸收,以致腹泻。正常人一次能够吸收25-50克果糖,而果糖载体运输效率差的个体一次能够吸收的果糖少于25克, 所以易出现腹痛、脂泻,这叫膳食果糖不耐。还有一种遗传性果糖不耐症, 是由于肝脏内缺乏分解果糖的酶。 根据本文内容,下列符合原文意思的项是:',
  null,
  '{"A":"运载果糖的载体是叫做GLU5的蛋白质,它的数量是有限的。","B":"人每天至少要摄入25克果糖才能满足身体的基本需求。","C":"膳食果糖不耐症是由于体内缺乏果糖载体导致的。","D":"当GLU6无法运输走所有的果糖,就会将多的果糖留在肠道内,果糖到了结肠,产生细菌,导致腹泻。"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '依照上文,果糖抵达小肠需要一种称为GLU5的蛋白质作为载体,载体的数量有限的。所以选择A。',
