(
  '文字-216',
  '文字-216',
  '人类的正常活动是白天工作晚上休息,然而工业自动化却要求机器 24小时不间断工作。一个人大约需要 6天才能适应黑夜和白天颠倒,但在工业生产中几乎每星期都要倒班,倒班制度使工人的所有生活都变得混乱。解决这个问题似乎只有把夜班固定给一批人干,但同时也要挑选一些能快速适应倒班的人来环节轮班干活的紧张。根据提问挑选人员不失为一种好方法,因为人们工作效率高时体温也较高,只是这种方法至今并未得到实际的应用 材料的中心思想是:',
