(
  '文字-218',
  '文字-218',
  '城市夜晚的灯火霓虹繁华美丽,这美丽在很大程度上都要归功于这些色彩斑斓的灯火。霓虹灯为什么能够出现斑斓的色彩?这绝不是给普通的灯管加上了一个彩色的玻璃罩子那么简单,霓虹灯的原理其实和闪电非常接近。霓虹灯的原理并不复杂,就是通过释放类似闪电的电流来电特殊的气体,就能够产生白色以外的光。在雷雨交加的夜晚,闪电-般都是白色,其实这只是因为闪电出现得太快,使我们没能仔细观察罢了。其实除了白色以外,有时候闪电会呈现出淡蓝色,而有时又会偏向于红色。那么为什么闪电也会出现不同的颜色呢?每一次闪电所释放的能量并不是相同的。-般来讲,能量适中的闪电则会呈现出常见的白色,而能量越高则会越接近于蓝色,如果能量很弱则会向红色靠拢。 根据本文内容,下面推断不正确的是',
