  '{"A":"人类能在各种自然现象中得到灵感和启发","B":"闪电和霓虹灯的原理一样, 但闪电变颜色不需要特殊气体","C":"闪电只有红白蓝三种颜色","D":"音通的电灯发出黄白的光不需要特殊气体"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '逐项定位原文，B项“闪电和霓虹灯的原理一样, 但闪电变颜色不需要特殊气体”与原文信息不符、表述过度或未被提及，符合题干要求，因此选择B。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-排除错误项。',
