(
  '文字-222',
  '文字-222',
  '日常表达我们经常使用泛化的"你"来表达日常行为规范、负面经历或分享个人见解。尽管"泛化的你"用得相当普遍,还没有人仔细研究过它的心理学功能。密歇根大学的研究人员募集了2489名参与者,通过9项实验,了解到人们为什么如此喜欢使用"你",参与者被要求写下一些个人经历,其中201位参与者需要从一段消极经历中寻找意义,198位参与者需要回顾一段消极经历,还有203位参与者仅仅需要写下一段既不消极也不积极的中性经历。实验结果显示,"寻找意义"小组在他们提交的小短文中使用了更多的"你"--有46%的参与者至少使用了一次"你",而"回顾"小组和"中性经历"小组各自只有10%和3%的参与者至少使用了一 次"你"。人们在日常生活中如此频繁地使用"泛化的你",已经使得它成为人们从普通经历和情感经历中寻找意义的主要工具。 下面哪一项不是"泛化的你"的使用场景?',
