  '{"A":"人口生产总是破坏生态平衡的,因而一般属于\"逆向改变\"","B":"精神生产有比物质生产和人口生产更为积极的作用","C":"精神生产存在着\"顺向改变\"和\"逆向改变\"两种可能性","D":"科学技术发展总是维护生态平衡的,应该说是\"顺向改变\""}'::jsonb,
