(
  '文字-228',
  '文字-228',
  '运动是现代化人常用的锻炼方式,经常运动可有效减少高血压、冠心病的发病率,也可有效捷高机体抗疲劳的能力。但当入在突然的高强度运动之后,有时会出现上呼吸道不适或感染的现象,也就是大强度运动后免疫力降低的"开窗理论"。大量研究表明,超过九十分钟的高强度运动,会让运动者的免疫力降低15%-70%。 "开窗理论"是指在大强度运动后,淋巴细胞浓度降低,增殖分化及活动降低,免疫球蛋白含量及功能也受到影响,出现的免疫低下期。高强度、长时间的运动会使机体很多免疫细胞的功能受到抑制,使血液中的自然杀伤细胞的细胞毒性效应下降,中性粒细胞功能受损,淋巴细胞和单核细胞的计数下降。从免疫细胞凋亡的来讲,外周淋巴细胞凋亡率在运动后显著升高,而免疫细胞的异常增多或减少都可能给机体带来不利的影响,所以,便出现了短暂的易感疾病侵袭的"开窗期"。 根据本文内容,下列推论正确的是:',
  null,
  '{"A":"在进行中等强度的运动后,血液中的自然杀伤细胞的计数会有所下降。","B":"小张做了60分钟的高强度运动,他会出现上呼吸道感染的现象。","C":"免疫细胞的浓度升高,说明免疫细胞的功能有所提高,从而有助于机体健康。","D":"持续做了2小时的运动,将会导致免疫细胞浓度降低。"}'::jsonb,
