  '文字-230',
  '文字-230',
  '怀孕很容易让曾患过抑郁症的人旧病复发,那些在怀孕期间停止服药的女性复发的可能性是继续服药女性的三倍左右。但一些研究表明使用选择性 血清素再吸收抑制剂(SSRI) 会导致一系列问题:例如某些类型的婴儿心脏缺陷、流产、早产、新生儿体重偏轻,自闭症等。很多患有抑郁症的孕妇会因为这些含糊不明、难以确认但又无可否认的风险而拒绝服用SSRI。虽然服药有风险,但在怀孕期间患上抑郁症同样有很多问题,受抑郁或焦虑折磨的孕妇压力更大,神经系统会受到影响,而这一后果又会导致子宫环境发生变化,从而影响胎儿发育。所以我们必须灵活对待:对于抑郁问题十分严重的孕妇来说,用药显然是最佳选择;需要咨询医师和精神病专家,从而决定应该怎么做。 上述材料中SSRI是一种:',
  null,
  '{"A":"孕妇服用的药物","B":"治疗抑郁症的药物","C":"治疗新生儿的药物","D":"缓解孕妇对胎儿影响的药物"}'::jsonb,
