(
  '文字-235',
  '文字-235',
  '陌生人社交平台引发了荷尔蒙经济的热潮,之所以如此是因为由荷尔蒙引起的欲望本就存在于人性中,经验告诉我们,所有基于人性的生意都是刚需,并且长久不衰。尤其是在中国市场,人们既被传统思想束缚,表面上必须遵守许多规矩,尤其是伦理与道德的标准,但也许正是因为这样,被压抑的荷尔蒙才更容易刺激人们做一些不那么遵守规则的事情。所以,陌生人社交提供给荷尔蒙经济一个极好的发展平台,在这个平台中,荷尔蒙可以被无限次消费,而且收益惊人。以陌陌为例,去年第四季度,陌陌的付费用户达到390万人,季度净增人数30万.在第四季度增值业务的营收中,陌陌的收入为4.99亿元,余下的则是探探创造的2.23亿元。 根居本文内容,下面推断正确的是:',
  null,
  '{"A":"只要欲望存在,陌生人社交平台就可以长盛不衰","B":"中国传统思想不利于荷尔蒙经济的发展","C":"陌生人社交平台带来了伦理与道德的颠覆","D":"去年陌生人社交平台第四季度增值业务营收的第二名是探探"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  'A项,定位到文段第一句,能长久不衰的是基于人性的生意、即荷尔蒙经济,而不是引发荷尔蒙经济热潮的陌生人社交平台,排除;B项,定位到第二句,在中国传统思想的环境下陌生人社交平台能让荷尔蒙经济能更好,由此可知中国传统思想不仅不会不利于荷尔蒙经济发展,反而会刺激发展,排除;C项,题干说的是会刺激人做不那么遵守规则的事情,并不是颠覆伦理与道德的事情,过于绝对,排除;D项,最后一句,第四季度增值业务营收中,除了4.99亿是陌陌,余下的2.23亿都是探探创造的,2.23亿<4.99亿,探探排第二名。选D。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
