(
  '文字-237',
  '文字-237',
  '社区暴力可能会导致情感、杜交和认知上的问题:目睹过暴力活动的孩子,可能难以调节情绪,或难以集中注意力,随着时间的推移,这些孩子可能不会积极参加学校活动、孤立自己、甚至出现创伤后应激障碍。研究发现,那些在少年早期目睹社区及校园暴力的孩子们,在接近成年时,其大脑中的海马体及杏仁核比普通人更小,海马体在学习和记忆中起重要作用,应激激素会使得海马体收缩,因此黑暗的童年经历会导致海马体体积变小,并表现出学习和认知困难。而杏仁核位于海马体附近,它与情感、威胁等过程相关,杏仁核体积较小则与抑郁风险和行为问题有关。 下面对本文内容理解正确的是:',
  null,
  '{"A":"那些经历过社区暴力的孩子会出现情绪障碍、注意力分散和创伤后应激障碍。","B":"那些海马体和杏仁核更小的人有可能在少年早期经历过社区及校园暴力。","C":"目睹过暴力活动后,应激激素会刺激海马体导致其体积变小,产生认知困难。","D":"杏仁核之所以在目睹暴力活动之后更小,是由于它靠近海马体,受到海马体的影响。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '梳理文段的中心句与行文重点后，C项“目睹过暴力活动后,应激激素会刺激海马体导致其体积变小,产生认知困难。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择C。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-因果关系。',
