(
  '文字-238',
  '文字-238',
  '桃花,作为一种自然物,本来不具有"文化"的涵义。但桃花作为人们共同认可的一种信息载体,如同中国的"梅文化"、"菊文化"一样,成为我们民族集体记忆和心理深层的积淀物, 奠定了中国的"桃花文化"。中国的"桃花文化"和女性有不解之缘。《诗经,周南》 中就有"桃之夭夭"描写茂盛的桃花,并用桃花比喻年轻美貌的女子。春秋时代,息国的夫人息妫容貌美丽,被人称作"桃花夫人"。唐代崔护曾在京都邂逅一少女,题诗慨叹"人面桃花相映红"。次年再访,人去桃花在,令人伤怀。桃花还渗透着"儒与庄禅互补"的文化精神。中国文人在儒家"修身齐家治国平天下"的人生理想被现实不断击碎时,他们只好"穷则独善其身",回归田园,在庄禅的境界中求得精神的解脱。陶渊明的《桃花源记》,为他和与他样的失意文人创造了一个虚幻的理想世界,形成了文人学士的"桃花源情结"。 下面与崔护的"桃花"经历相符合的诗句为:',
  null,
  '{"A":"人面不知何处去,桃花依旧笑春风。","B":"忽闻仙踪一朝至,桃花人面分外红。","C":"若将人面比桃花,面自桃红花自美。","D":"年年岁岁花相似,岁岁年年人不同。"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '崔户原诗下半阙就是人面不知何处去,桃花依旧笑春风,只能选a',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-主题词。',
