(
  '文字-239',
  '文字-239',
  '严密的逻辑论证,历史上有个确实的来历:公开辩论。古典时代的雅典人好辩,还有一套民主选举办法,雄辩术风行,甚至还有一个奇怪的习惯:两人争辩一件事,可以有彩金,谁辩胜就得彩金。辩证法的原意本是辩论,一方说话有漏洞,对方力图辩驳,怕输,就要严密。逻辑学显然也是从这来的。 不符合这段话意思的是:',
  null,
  '{"A":"雄辩术曾经在古典时代的雅典风行","B":"辩证法不仅仅是为了在和别人的论辩中取得胜利","C":"为一件事情争论不休在古典时代的雅典可能是很奇怪的","D":"逻辑学的产生可能和古典时代的雅典人好辩有关"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '本题属于细节判断题型,主要考察局部精读类,本题对应的解法是对原文信息进行提取。根据原文“雄辩术风行”可知A项正确。B项根据原文最后一句话“辩证法的原意本是辩论......逻辑学显然也是从这采的”可以得出。C项的表述与原文不符。原文中“奇怪的习惯”是作者的看法,而C项的表述“在古雅典时代”,显然偷换了时间概念。原文中“甚至还有一个奇怪的习惯:两人争辩一件事,可以有彩金,谁辩胜就得彩金”可知在古代雅典为一件事情争论不休是司空见惯的。根据原文可知在当时的雅典,雄辩术是风行的,并不奇怪。本题选择的是不符合文段意思的,所以,本题选择C答案。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-递进关系。',
