  '北森言语理解',
  null,
  241,
  '{"kind":"verbal","analysisSource":"原题解析","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-240',
  '文字-240',
  '记忆可能非常不可靠,甚至是那些当时看来非常鲜明的、高度情感化的记忆,即"闪光灯记忆"。我们的记忆常含有空白、错误暗示和近似。记忆通常随时间衰退。大脑并不是完美的电脑似的数据存储设备,而是易错的肉质器官。例如,在名的辛普森谋杀案审判后开展的一项研究发现,人们关于如何听到审判裁决的记忆在15个月后只有一半正确,而在32个月后,正确率只有29%。在911事件7周后进行的研究发现,73%的曼哈顿大学生认为自己在事件发生当日看到了第一架飞机撞击世贸中心的镜头,但这是不可能的。该组镜头直到9月12日才对公众公开。研究人员相信,当记忆被频繁唤起时,它们最容易变得扭曲,并且这可能意味着,回忆越重要,回忆的次数越多,就越可能出错。重要的回忆一直伴随着你,而它们一遍-遍在你脑中重演,却可能离事实越来越远了。 上述材料主要讲述了:',
  null,
  '{"A":"记忆随时间会衰退","B":"记忆并不可靠","C":"记忆有欺骗性","D":"记忆有错误暗示"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '梳理文段的中心句与行文重点后，C项“记忆有欺骗性”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择C。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
  '提高',
  '文字推理',
  '中心理解题',
  '["做题辅助-对策词"]'::jsonb,
  '北森言语理解',
  null,
  242,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-241',
  '文字-241',
  '人体所需的蛋白质氨基酸有20多种,其中有八种通过摄取食物来供给。人在进食后,食物中的蛋白质会在各种蛋白属的作用下水解产生各种氨基酸,然后会被吸收并重新组合,形成人体所需要的蛋白质。蛋白质中的氨基酸不仅是机体所需的营养物质,对于某些疾病也有治疗作用,因此也被制成氨基酸原料药。目前,氨基酸类药物主要有补充营养、降低血氨、慢性肾衰以及急惯性肝灸的辅助治疗作用。此外,人体必需氨基酸还被广泛应用在蛋白质食品加工中。有些氨基酸可以对食品强化处理来保证其营养价值,但是需要严格控制和掌握氨基酸的加工条件,因为人体对必需氨基酸并非越多越好,而是需要合理摄入,如果摄入过量会对儿童的智力发育造成严重影响。 下面最适合本文的标题是:',
  null,
  '{"A":"蛋白质氨基酸在人体的转化过程","B":"蛋白质氨基酸对疾病的治疗作用","C":"蛋白质氨基酸在食品生产中的应用","D":"蛋白质氨基酸的摄入吸收及对人体价值"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '标题需要同时覆盖文段的核心对象和主要内容。D项“蛋白质氨基酸的摄入吸收及对人体价值”概括范围最完整，也符合标题简洁准确的要求，因此选择D。',
  '先提炼核心对象和核心事件，再检查标题是否准确、全面且简洁。 本题重点：议论文。',
  '提高',
  '文字推理',
  '标题填入题',
  '["议论文"]'::jsonb,
  '北森言语理解',
  null,
  243,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-242',
  '文字-242',
  '儿童教养方式是父母在各种情境下表现出的教育子女行为的集合体。区分有效教养和无效教养的三个特征为接纳、控制与自主性,基于此,教养方式可划分为四种。权威型最为成功。表现为对子女的高接纳,恰当控制并给予一定的自主性。亲子关系紧密而理性。专制型表现为对子女的低接纳和低介入、高强迫控制。他们喊叫、命令和批评孩子。如果孩子反抗,就会武力相向,严厉惩罚。孩子的自主性低。放任型表现为对孩子疼爱、接纳,但不介入。过分溺爱孩子,很少控制其行为,放任自流,在过小的年龄就让孩子自己做决定。不过问型表现为对子女的低接纳、低介入、低控制,漠视孩子对自主性的要求。这种教养方式的极端是"忽视",会阻碍孩,子各方面的发展。 按照控制度从高到低的顺序,四种教养方式的排列为:',
  null,
  '{"A":"专制型一权威型一放任型一不过问型","B":"权威型一专制型一放任型一不过问型","C":"放任型一专制型一权威型一不过问型","D":"专制型一放任型一权威型一不过问型"}'::jsonb,
