(
  '文字-246',
  '文字-246',
  '20多万年前,在如今的南非,一个约90厘米的孩子不知因何天折。这位年轻人类与其近亲的遗体停放在一个黑暗幽深的洞穴里,直至2013年,这些遗骸一直无人发现,无人扰动。大多数早期人类的化石都是分散的、单块的骨骼,而非明显属于同一个个体的成套的骨骼。迄今为止,研究人员只发现了屈指可数的几具南方古猿阿法种,南方古猿源泉种和直立人青少年骨架。不过,新发现的纳勒迪人骨架很突出。其他早期古人类物种都生活在一百万年前,而纳勒迪人在时间上与我们更近,DH7和与之一同被发现的其他化石掩埋于22.6万年前至33.5万年前之间 ,与现代人类出现在非洲大陆的迹象一致。但是,尽管这两个人种可能共存过纳勒迪人的几个身体特征却与古人类更像,比如其臀部和肩部。 这段文字是一篇文章的开头部分,文章接下来最可能讲述的是',
