  '文字-247',
  '文字-247',
  '在预估未来的喜好时,我们总是过于相信自己能够把握未来的"口味",但我们对未来喜好的预估与未来的实际选择定间存在分离,这就是过度自信。研究者让被试在实验第一天选出自己当前想吃和未来一周及两周后想吃的食物,并用百分比率说明他们有多大自信能实现自己的预估。结果发现,人们都非常确信自已能够掌控未来喜好,但一而或两周后,只有46%的人按照自己之前的预估出牌。此外,女性在当期偏好与来来选择之间的差值要比男性更高。 下面对本文内容理解正确的是:',
