(
  '文字-248',
  '文字-248',
  '有些人害怕高处或狭小的空间,而另一些人则害怕具体的事物,如蛇、蜘蛛或小丑,但更加曾遍的是对黑暗的恐惧。即使身处熟悉、舒适的环境,在白天被忽视的无害的东西都有可能在黑夜里产生威胁。但并不是所有的事情在黑暗中都更可怕。当灯灭了,人们对传染性疾病(季节性流感)的恐惧会减少。研究者认为人们对传染病感知风险的降低是由于我们感知和思考世界的方式的变化。当周围环境黑暗时,我们关注到的是周围人的整体轮廓,而不是具体的细节(如眼睛颜色)。这种对全局的感知会增加我们感知到的与人的社会距离。当我们认为自己与他人的距离更远时,对传染病风险的感知就会降低。 下面最适合本文的标题是:',
