  '文字-250',
  '当人们对他人说的话感到困惑时,出于礼貌,他们并不会打断他人,只会以眼神涣散。表情呆滞的形式表达自己的迷惘。但在大多数时候,讲话者都会觉得自己讲的很清楚,因此这样的反馈很难让讲话者了解沟通的问题所在,反而让事情变得__________ 填入横线处最恰当的词语是:',
