(
  '文字-255',
  '文字-255',
  '碎片化时代的基本特征是"信息碎片化",从而导致"思维碎片化",最终导致"行为碎片化"。员工的行为碎片化给企业带来很大的挑战。一个表现是员工在解决问题时缺乏耐心,缺乏系统思维,很难拿出有深度思考的解决方案。另一个表现是犯过的错误,会一犯再犯。 "碎片化"给企业带来巨大的挑战,但现实中,企业打造学习型组织也面临着重大困难和挑战。对于员工来讲,学习要付出很多的业余时间,常因看不到具体的好处而缺乏动力。另一方面,即使员工不学习也很难受到处罚,强制的处罚也很难产生实际效果。学习必须是一种内在动力,而不是靠奖金来驱动。因此,如何建立学习型组织,从而驱动员工自主学习成为企业成长的迫切需要。 下面适合本文标题的是:',
  null,
  '{"A":"碎片化如何影响员工行为","B":"行为碎片化的表现","C":"企业如何快速成长","D":"碎片化时代中的企业"}'::jsonb,
