(
  '文字-258',
  '文字-258',
  'AI热度的与日俱增让人们经常在展览、电视、报纸杂志上看到机器人,但它们却还没真正走入千家万户。其中,价格问题直观可见,家庭陪护、教育等方面的交互型机器人,其市场价格大约在2-3万,这超出了一般家庭的支付能力。此外,交流木讷、动作呆板等均是消费者针对服务型机器人的主要槽点。就中国机器人和世界机器人目前的差距来看,自主品牌的机器人还处在中低端,同时还存在低价竞争,其中在核心零部件和工业集成的应用工艺方面,还有不小的差距。 下面对本文内容理解正确的是:',
  null,
