(
  '文字-260',
  '文字-260',
  '最近,一种新型心脏起搏器问世,它的大小只有一个大胶囊的大小,没有电极导线,直接植入心脏。而且它可以通过股静脉穿刺的方式完全植入到右心室里,手术时间也只有传统起搏器的一半时间,大概32分钟。因此,术后就不会留下丑陋的疤痕,也不会在胸部凸起会影响您的美丽。它也不太容易发生感染--心脏起搏器植入术最讨厌的敌人。去年八月,新加坡国家心脏中心开创了在新加坡开始使用这种无导线心脏起搏器的先河。目前,无导线起搏器最适合那些只需要调节右心室心律或双侧锁骨下静脉闭锁的老年人使用。相信随着技术的不断成熟,无导线起搏器将成为更多病人的最佳选择。 根据本文内容,下面推断不正确的是?',
  null,
  '{"A":"传统心脏起搏器植入术会留下丑陋的疤痕,以及造成胸部凸起会影响美观。","B":"目前,无导线起搏器技术还不够成熟。","C":"新加坡国家心脏中心设计发明了无导线起搏器。","D":"安装无导线起捕器采用股静脉穿刺技术,能减少创口和缩短手术时间,所以相对于传统手术不容易发生感染。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '由题意可知:去年八月,新加坡国家心脏中心开创了在新加坡开始使用这种无导线心脏起搏器的先河。去年八月,新加坡使用这种无导线心脏起搏器,而不是发明了这种无导线心脏起搏器。所以C错误。目前,无导线起搏器最适合那些只需要调节右心室心律或双侧锁骨下静脉闭锁的老年人使用。相信随着技术的不断成熟,无导线起搏器将成为更多病人的最佳选择。无导线起搏器技术还不够成熟。所以B对。且它可以通过股静脉穿刺的方式完全植入到右心室里,手术时间也只有传统起搏器的一半时间,大概32分钟。因此,术后就不会留下丑陋的疤痕,也不会在胸部凸起会影响您的美丽。它也不太容易发生感染--心脏起搏器植入术最讨厌的敌人。所以A、D对。所以答案选C。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-排除错误项。',
