),
(
  '文字-262',
  '文字-262',
  '扩声系统的基本作用是通过建筑声学和电声学的手段使听众或技术、艺术人员获得所需要的声音信息。所有的扩声系统按照工作环境可分为室外系统和室内系统。室外扩声的特点是反射声音小,有回声干扰,扩声区域大,声学条件复杂,噪声干扰强,音质受气候条件影响比较严重。室内扣声的特点是对音质要求高,有混声干扰,打声质量受房间的声学缺陷影响较大。而按照声源性质,扩声系统又可分为语言扩声系统、音乐扩声系统、信息发布系统、语言同声传译系统、转播系统和已录声音的重放系统等,其中后两种系统的扬声器和话筒并不处于同一声场环境中。 根据上述材料我们能够推断出:',
  null,
