  'D',
  '逐项对照原文，D项“语言扩声系统的扬声器和话简处于同一声场环境中”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择D。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
