(
  '文字-263',
  '文字-263',
  '众所周知饮酒过量会给身体带来严重影响,包括损伤肝脏。但多少是过量呢?对于肝硬化等疾病,通常每周饮酒超过210克纯酒精,相当于一周大约两瓶葡萄酒或一天饮用230毫升左右的啤酒。英国的首席医疗官建议成年人每周饮酒应不超过140克纯酒精,以降低患病风险。研究发现,即使是适度饮酒也会导致脑容量下降。饮酒超过英国目前的低风险指标,就会增加患痴呆的风险。一般人认为的合理和适度的饮酒方式,可能也会缓慢地损伤我们的大脑。减少饮酒量或者完全戒酒可以降低脑损伤的风险,但这也需要我们保持良好的生活方式,包括健康的饮食习惯和锻炼。 根据本文内容,下面推断正确的是:',
  null,
  '{"A":"酒精对大脑的损害能够被经验丰富的饮酒者敏锐地感知。","B":"人们很少能够主动察觉到酒精对大脑的潜在损伤。","C":"过早检测大脑损伤对于喝酒的人没有任何好处。","D":"酒精对年轻人的危害比老年人大的多。"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '由题意可知:一般人认为的合理和适度的饮酒方式,可能也会缓慢地损伤我们的大脑。所以A正确B错误。过早检测大脑损伤对于喝酒的人应该是有好处。所以C错误。英国的首席医疗官建议成年人每周饮酒应不超过140克纯酒精,以降低患病风险。并未提到酒精对年轻人的危害比老年人大的多。也推断不出。所以D错。所以答案选B。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
