  '文字-264',
  '文字-264',
  '人的头发直径仅60-70微米,但却含有18种氨基酸。这些氨基酸用途众多。用头发提取合成的精氢酸。胱复酸已临床应用于医治肝炎及各种脱发症,组氨酸可治行消化道溃疡,脯氨酸可治疗高血压,赖要酸为儿童身体发育所必不可少。由于氨基酸对人类的健康有重要作用,人发已逐渐代替鲸鱼成为生产氮基酸的重要原料。此外,头发还被用以生产各种毛笔。近年來,科学家又发现人发中含丰富的黑色素和角朊--制造防晒油的高级原料。过去用人造原料制成的防晒油易引起皮肤过敏,而以人发为原料的防晒由不仅不会造成过敏,还具有吸收紫外线光谱范围广、在强烈光鹏下不会变质等诸多优点。 下面不属于头发的用途的是:',
