(
  '文字-267',
  '文字-267',
  '通过学习音乐课程,孩子能获得诸多益处,如演奏乐器能激发创造力,锻炼自律能力与注意力,增强孩子的自信心等。但对于提高智力却没有明显帮助。为探索音乐和认知之间的关系,研究者招募了29对父母和四岁的孩子,在给孩子进行初步的词汇测试,并对父母做了音乐才能测试后,所有参与家庭被随机分配为两组:一组接受音乐训练,另一组接受视觉艺术训陈。研究者对早期研究做了关键性变化:由于不同老师会造成不同影响,所以有别于以往研究,研究者自己同时教授音乐和视觉艺术两门课程,并利用评估工具测试认知能力的四个特定方面:词汇、数学和两种空问能力。研究结果表明,没有证明表明音乐训练对认知能力有任何好处。两组儿童在词汇和数学测验中表现旗鼓相当,而在两种空间能力测试中,受过音乐训练和视觉艺术培训的儿童各赢得一筹。 上述材料主要讲述了:',
  null,
  '{"A":"音乐课程学习与孩子性格形成的关系。","B":"音乐课程学习对孩子有诸多好处。","C":"音乐课程学习能提升孩子的自信。","D":"音乐课程学习对于提升认知能力没有帮助。"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '通过题意可知:文中并未提到性格,所以A错。通过学习音乐课程,孩子能获得诸多益处,如演奏乐器能激发创造力,锻炼自律能力与注意力,增强孩子的自信心等。所以B对。文中并未主要讲述音乐课程学习能提升孩子的自信。所以C错。而在两种空间能力测试中,受过音乐训练和视觉艺术培训的儿童各赢得一筹。并利用评估工具测试认知能力的四个特定方面:词汇、数学和两种空问能力。所以音乐课程学习对于提升认知能力并不是完全没有帮助。所以D错。答案选B。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
