(
  '文字-272',
  '文字-272',
  '技术和创新让资本市场现代化,获取资金的渠道变得更简单,进一步将权力从资本转移到人才手中。独特人才对组织的工作价值乃至工作本质有着深远影响。随着知识经济的不断发展,拥有稀有专长和技能的员工影响力日益强大。顶尖人才给组织带来的绩效是其他人办不到的,他们的表现远超平均水平。如果你依靠他们获得出色的组织绩效,就必须将他们看作受重视的独特个体,优秀人才之所以能取得最高级別的成功是因为他们在培养自身技能的过程中倾注了大量心血,所以永远不要忽视他们的想法。同时,不要阻碍他们的发展,也不要放过任何在成功时赞美他们的机会,当杰出人才需要认可和感谢的时候,泛泛地总结说"你今年表现很出色"往往只会适得其反,即便有可观的奖金也一样,你要认可优秀员工具体的贡献。 下面对本文内容理解正确的是:',
  null,
  '{"A":"技术、创新、资本的重要性远远比不上人才对于企业的重要性。","B":"项尖人才的能力和专长是决定未来企业发展方向的关键因素。","C":"领导者应该将每一个员工都看作是独特的存在并尊重他们的劳动。","D":"领导者对优秀人才表达出泛泛的夸奖并不会让他们产生好的感受。"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '由题可知:独特人才对组织的工作价值乃至工作本质有着深远影响。随着知识经济的不断发展,拥有稀有专长和技能的员工影响力日益强大。顶尖人才给组织带来的绩效是其他人办不到的,他们的表现远超平均水平。所以选项A、B错误,题中并未提到。如果你依靠他们获得出色的组织绩效,就必须将他们看作受重视的独特个体,优秀人才之所以能取得最高级別的成功是因为他们在培养自身技能的过程中倾注了大量心血,所以永远不要忽视他们的想法。所以选项C错误,题中讲的是要重视优秀人才,并没有说是每一员工。当杰出人才需要认可和感谢的时候,泛泛地总结说"你今年表现很出色"往往只会适得其反,即便有可观的奖金也一样,你要认可优秀员工具体的贡献。所以选项D对,所以答案选D。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
