(
  '文字-273',
  '文字-273',
  '竞争优势是一个公司相对于竞争对手的位置。由于竞争者总是干方百计复制其它公司保持的竞争优势,许多形式的竞争优势不能无限期维持下去。一旦竞争优势被其他公司复制,将很快成为消费者的基准预期,就不再是竞争优势。 上述论点不支持以下哪个结论?',
  null,
  '{"A":"竞争优势并不完全受希望拥有竞争优势的公司的控制。","B":"不同的公司有各自不同的竞争优势;因此,不止一家公司能够凭借自己的竞争优点而生存下来。","C":"确保竞争优势的其中一种做法是复制自己最大竞争对手的竞争优势。","D":"公司必须定期重新审视并修改自己的策略方针才能保持竞争优势。"}'::jsonb,
