(
  '文字-275',
  '文字-275',
  '一家信用卡公司决定投资建立数据库,以便能够利用该数据库向更广泛的客户销售更多种类的商品和服务,从而获得竞争优势。 以下哪一项陈述(如果正确)削弱了上述论点?',
  null,
  '{"A":"其他信用卡公司已经建立了数据库系统。","B":"许多其他信用卡公司正通过降低利息以获得竞争优势。","C":"数据挖掘技术是当今商业竞争环境下的最新趋势。","D":"数据库的网络系统适应信用卡公司目前的系统。","E":"产品和服务的增加并非客户最期待的。"}'::jsonb,
