(
  '文字-278',
  '文字-278',
  '市场推动技术革新,并不意味着技术革新完全决定于市场。技术革新包括"产品革新"与"工程革新"这两个侧面。过去是生产决定需要,工厂 生产千篇一律的中山装,老百姓就得人人穿中山装。然而在市场经济时代,是需要决定生产。你再生产千篇一律的中山装,老百姓不买你的帐,他们的意志通过市场表现出来,逼着你去开发新产品,实行"产品革新"。产品革新需要工程革新给予支持,工程革新也需要产品革新加以引导。市场既然具有刺激产品革新的作用,当然也对工程革新貝有间接的刺激作用。特别是激烈的市场竞争,推动广大企业努力提高产品质量,降低成本,这些都要通过工程革新来实现。然而对于一个企业来说,市场仅仅是刺激工程革新的"外因",而直接导致工程革新的内因,则在于生产内在的矛盾。这种矛盾推动尚未发生革新的生产环节乃至整个生产技术体系出现"工程革新"。 下列对"产品革新"的叙述中,与原文相符的一项是',
  null,
  '{"A":"中山装在产品革新过程中被抛弃","B":"市场经济可以促进产品革新","C":"计划经济中不存在产品革新","D":"老百姓可以直接参与产品革新"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '梳理文段的中心句与行文重点后，B项“市场经济可以促进产品革新”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择B。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
