(
  '文字-280',
  '文字-280',
  '每个人都喜欢捡便宜,所以给商品标上折扣是促销的好办法,但所谓的"原价"不一定靠谱。研究分析了某主流零售连锁的直营店,发现他们的原价都是虚构的-----这些商品从未以标示的高价销售过。进步分析发现,"原价"每高一美元,顾客就平均愿意多支付77美分。有观点认为消费者足够精明,因而相对于其他形式的欺骗,虚假标价的害处不大,但研究结果显示,仍然有很多消费者看不穿。 根据本文内容,下面推断正确的是:',
  null,
  '{"A":"商品的原价都是虚假的,真正的原价都比标签低得多。","B":"实际上商品的折扣价格才是它的真实价格。","C":"即使知道折扣商品的原价是假的,很多消费者还是会选择购买。","D":"折扣商品的原价越高,消费者愿意付出的购买价格就越高。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '逐项对照原文，C项“即使知道折扣商品的原价是假的,很多消费者还是会选择购买。”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择C。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
