  '北森言语理解',
  null,
  284,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-281',
  '文字-281',
  '从众效应是指人们受到多数人一致性思想或行动的影响,而跟从大众的思想或行为。它常常会使人忽略自己真实的想法或感受。有研究要求参与者随意走动且不和其他任何人交流,同时提前规定了大部分参与者走动的路线。结果发现,那些被告知随意走动的参与者却跟在了那些事先被定好路线的参与者后面,他们甚至没有意识到自己被其他人引领了。在很多情况下,复制其他个体的行为是有道理的,它可以帮助你决定买什么样的手机更靠谱,规避一定的风险。此外,当你身边有大量人群时,购物体验会得到增强,并将糟糕的体验变成有趣的体验。但很多时候人们会过度使用社交信息,过多地复制他人,这可能会打乱我们自己的生活节奏。 下面最适合本文的标题星:',
  null,
  '{"A":"过度从众,打乱自我节奏","B":"从众让生活体验更有趣","C":"从众:跟随他人的选择","D":"从众:看重他人,忽视自己"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '标题需要同时覆盖文段的核心对象和主要内容。D项“从众:看重他人,忽视自己”概括范围最完整，也符合标题简洁准确的要求，因此选择D。',
  '先提炼核心对象和核心事件，再检查标题是否准确、全面且简洁。 本题重点：说明文。',
  '提高',
  '文字推理',
  '标题填入题',
  '["说明文"]'::jsonb,
  '北森言语理解',
  null,
  285,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-282',
  '文字-282',
  '自17世纪开始,生物学家开始注意到一种特殊的生态系统一——地下水生洞穴系统。 这种系统和其他栖息地的最大区别在于洞穴下食物稀缺,同时光照缺乏,并且外界季节性和年度的环境变化对这里的影响都非常小。欧洲东南部阿尔卑斯山下面的水下洞穴中,演化出一种通体雪白、没有眼睛的生物洞螈。作为真正的"洞穴之王", 洞螈是古近纪以来唯一的穴居脊索两栖动物,也是欧洲标志性物种之一,属于洞螈科洞螈属下的唯一物种。 环境所迫,为了维持机体各项生命活动,洞螈会主动调慢自身的新陈代谢,减少一切耗费能量的事情。 根据本文内容,下面推断正确的是:',
  null,
  '{"A":"阿尔卑斯山下的水生洞穴使洞螈唯能够生存的地方。","B":"洞螈是唯一种能在水下洞穴中长期生活的生物。","C":"洞螈喜欢在食物稀少的洞穴中不停徘徊以寻找食物。","D":"长期生活在暗无天日的地下洞穴使洞螈的眼睛慢慢退化。"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '逐项对照原文，D项“长期生活在暗无天日的地下洞穴使洞螈的眼睛慢慢退化。”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择D。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
