(
  '文字-310',
  '文字-310',
  '芬兰研究人员开发出一种黑硅光电探测器,其外部量子效率达130%,这是光伏器件这一效率首次超过100%的理论极限, 有望大大提高光电探测设备的效率,而这些设备广泛应用于汽车、手机、智能手表和医疗设备内。光电探测器是可以感测光或其他电磁能星的感测器,可将光子转换成电流,被吸收的光子形成电子-空穴对。光电探测器包括光电二极管和光电晶体管等。子效率是用来定义光电探测器等设备将其受光表面接收到的光子转换为电子空穴对的百分比,即星子效率等于光生电子除以入射光子数。当-个入射光子向外部电路产生-个电子时,设备的外部量子效率为100%(此前被认为是理论极限)。在最新研究中,黑硅光电探测器的效率高达130%,这意味着一个入射光子产生大约1 .3个电子。 根据对文本内容的理解,下面推断正确的是:',
