(
  '文字-311',
  '文字-311',
  '大量研究证明,无论处在人生的哪个阶段,音乐都能深深影响人们的行为和认知。2014年在加拿大建成的大型交互虚拟环境实验室(简称LIVElab), 是全球首个兼具音乐厅和实验室功能、 专门研究音乐对大脑作用的设施。神经学家、生理学家和心理学家已在这个实验室里,验证了各种有关表演、观众反应、音乐的即兴创作的假想。为了研究音乐对群体的影响,研究人员将借助多组脑电图扫描仪、心率监视器,以及呼吸和汗液传感器,来监测音乐会上观众的情绪起伏。他们还将使用能够捕捉动作的红外线相机,观察同一动作在观众中的传播效应。科学家想知道,在不借助言语的情况下,大脑怎样让我们与他人互动;他们还希望能够探明,大脑如何快速纠正脱口而出的错误。借助脑电图和捕捉人体动作的相机,科学家还计划探明,音乐家如何完成一段协奏曲, 以及一起跳舞的人在完成一个重要舞步时, 大脑是如何协调的。 根据上述材料我们能推论出:',
  null,
  '{"A":"借助交互虚拟环境实验室,科学家已经证实了声学对学习的影响。","B":"交互虚拟实验室最初就是一个普通的音乐厅。","C":"还没有研究在交互虚拟实验室中完成。","D":"2014年之前没有兼具音乐厅和实验室功能的设施。"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '由文中第二句话“2014年在加拿大建成的大型交互虚拟环境实验室(简称LIVElab), 是全球首个兼具音乐厅和实验室功能、 专门研究音乐对大脑作用的设施。”可知,在2014年以前没有兼具音乐厅和实验室功能的设施。因此,本题选D。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
