  '梳理文段的中心句与行文重点后，B项“越来越多离异夫妇能够和平相处, 并能够和孩子起度过假期”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择B。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
