(
  '文字-314',
  '文字-314',
  '电话和网络使所有的人都成了邻居,但却不可以延伸到太空中去,想跟另一个星球上的人对话是不可能的,因为电波的传递需要时间,你听到的话至少是别人三分钟以前说过的,在这种情况下,话语交换是可能的,但却不是交谈。同样地,光波也有速度,它与电波的速度相同,通常情况下,地球上的电波信号需要近20小时的时间穿过冥王星,它是太阳系中离太阳最远的一颗星球。而目前,人类的宇宙飞船远远达不到这个速度。人们通常将旅行太空的愿想寄希望于科学家,可些保守的科学家却不孚众望,他们否认自己能够跨过速度和空间的障碍。而历史证明,那些在理论上存在可能,也没有基本的科学规则阻止其发展的事情,最终都有可能实现。 我们为何无法与其他星球的人交谈?',
