  '文字-318',
  '文字-318',
  '"厄尔尼诺"一词来源于西班牙语,意思为"圣婴"。由于这种现象最严重时往往在圣诞节前后,于是遭受天灾而又无可奈何的渔民将其称为上帝之子--圣婴。厄尔尼诺现象的基本特征是太平洋沿岸的海面水温异常升高,海水水位上涨,并形成一股暖流向南流动。它使原属冷水域的太平洋东部水域变成暖水域,结果引起海啸和暴风骤雨,造成一些地区干旱,另一些地区又降雨过多的异常气候现象。厄尔尼诺现象是指:',
