  '文字-319',
  '王国维将做学问分为了三种境界,这首先就体现在读书学习上。首先,必须要耐得住"昨夜西风凋碧树,独上高楼"的清冷与寂寞,刻苦读书,静心领悟;其次应该做到"衣带渐宽终不悔",勤奋钻研,肯下功夫,即使"为伊消得人憔悴"也心甘情愿;最后,坚持独立思考,学用结合,便能在"灯火阑珊处"领悟书的真谛。上面一段文字的主旨是:',
