(
  '文字-320',
  '文字-320',
  '人无论是高尚的、龌龊的、优秀的、猥琐的、睿智的、愚钝的,身处寂寞的境遇,不等于陷入寂寞的窘迫。人无非生活在这两片天地里,环境似云,有聚时的热烈,有散时的寡落;心境似水,有静时的轻柔,有动时的汹涌。人无非生活在这两片天地里,以不断变幻的角色,把各个不同的命运去演示。"这两片天地"分别指:',
