(
  '文字-321',
  '文字-321',
  '蜜蜂群体中有蜂王、工蜂和雄蜂三种类型的蜜蜂,蜂王是一个蜂巢中所有蜜蜂的母亲,经过与来自其他蜂群中的几个雄蜂的交配,它便产下受精卵,而这些受精卵则发展成为全雌性的工蜂,它所产下的未受精卵则变成全雄性的雄蜂。在蜂王死后,工蜂经常产下未受精卵,发育成雄蜂。但在蜂王主幸蜂群时,工蜂很少繁殖后代。科研人员将工蜂和蜂王所产的未受精卵置于同一个蜂果中,其他工蜂迅速地将该工蜂的卵吞噬一空,而蜂王的卵却安然无恙。这说明( )。',
