(
  '文字-323',
  '文字-323',
  '关注民生是各地政府的工作重点,其中执行和提升最低工资标准是近来的重要举措之一,但关于最低工资在全球学术界也有不同的观点。支持者认为这是增加贫困人群收入的理想方法,让政府花很少的钱解决社会贫困问题,提高最低工资标准可以使穷人的境况变好,有助于社会稳定。然而反对者却认为最低工资会引起失业,达不到改善贫困的目的。反对者提出这样的观点,最有可能的根据是( )。',
