(
  '文字-326',
  '文字-326',
  '从公元前7000年起,辣椒就进入了人类的食谱。如今辣椒已经以各种方式存在于我们的饮食中,比如调味菜、辣味零食、老干妈和重庆火锅等,而以辣闻名的川菜也是中国人最喜欢菜系之一。不过,人们对于吃辣椒的态度还是存在两极分化,有的人无辣不欢,有的人却避之不及。而这主要是因为辣椒对消化系统的刺激,会让人瞬间产生强烈的生理反应,不同的人受到的刺激不同,感受也不一样,因此有的人能吃辣、爱吃辣可能就是因为受到的刺激度低。最适合作本段标题的是:',
  null,
