(
  '文字-327',
  '文字-327',
  '在目前移动阅读的市场上,付费阅读模式是业内主流的商业模式。除此以外还有出版图书、平台广告收入、用户打赏、出售硬件等盈利模式。而随着IP市场的火热,通过文学IP改编影视、动漫、游戏等的形式将文学IP价值最大化。下列说法与原文相符的是:',
  null,
  '{"A":"一些数字阅读企业开始出售专业的阅读硬件,是为了不断为用户提供更好的阅读体验。","B":"传统的出版社出版作者的作品,作者和出版社合作,或者网络文学网站与出版社合作,网站、作者、出版社,三位一体的营销模式。阅读平台拥有大量的版权资源,通过整合出版读物及网络小说进行电子版出版发售,获取一定收入。","C":"数字阅读行业也出现了版权增值的变现方式。","D":"用户通过对具体作品或者作者等进行打赏,来表现自己喜好的一种方式,是移动阅读最主要的商业模式。"}'::jsonb,
