(
  '文字-328',
  '文字-328',
  '和发育成生命个体,因此孕育过程与自然生殖并非完全一样,也就决定了克隆宠物会有多种多样的先天性疾病。此外,对于克隆宠物的伦理问题,现在还没有提上议事日程。克隆宠物会毁掉许多胚胎,这是否是对动物生命的尊重,是值得考虑的。例如,报道中提到的克隆猫"大蒜",有3个猫妈妈,分别提供细胞核DNA、卵细胞和负责孕育,用了40个胚胎进行克隆和代孕,最后才获得成功。从目前的行业态势来看,克隆宠物虽然可以,但是主人要做好接受克隆宠物的复杂心理准备,而且商业克隆宠物这一行业也需要做好接受伦理规范和监管的准备。这段文字主要阐述的是:',
