  '文字-329',
  '请将下列句子组成一段逻辑连贯、语言流畅的文字,排列顺序最合理的是:1近百年来,中华文化面临着被西方文化转基因的危险,现代人浮躁难安,如同离家出走的孩子。2同为炎黄子孙,文化同根同源,这正是中华民族统一的希望所在。3尽管海峡两岸分隔已久,但都有一个共同的人文始祖一黄帝。《回家》希望更多人回归中华传统文化的精神家园。5《回家》也希望台湾早日回归祖国的怀抱。6唯有回家,回归中华传统文化的源头,才能唤醒中国人的文化基因,恢复中国人应有的生命气象。',
