  '文字-333',
  '文字-333',
  '系统风险是指由于多种因素的影响和变化,导致投资者风险增大,从而给投资者带来损失的可能性。系统性风险的诱因多发生在企业等经济实体外部,其带来的波动面一般都比较大,有时也表现出一定的周期性。此类系统风险是不可分散的。根据上述定义,下列描述中属于系统风险的是:',
