  '文字-334',
  '文字-334',
  '矩阵对策的含义是处于利益竞争的两个关系主体,各自可选策略有限,且对一局对策中双方得失和为零的现象。对策中,一方真正成功的措施是,针对对方采取的行动制定有利于自己的应对策略,各方选择的策略必定是自己对对方策略预测的最佳反映。根据上述定义,下列属于矩阵对策的是:',
