  '文字-336',
  '文字-336',
  '据外媒报道,饮酒对人体的影响一直引起争议,多国学者前日在医学期刊《柳叶刀》发表涵盖全球195个地区的研究报告,指出即使只摄取少量酒精,也会增加患上严重疾病的风险。科学家强调摄取酒精没有"安全剂量",估计仅在2016年,全球便有280万人死亡涉及酒精。科学家定义每杯酒含有10克酒精,相当于一杯啤酒或小杯烈酒。若一般人每天饮用一杯酒,患上严重疾病的风险将增加0.5%;每天饮用两杯将增加7%;每天5杯则为37%。在15至49岁人士中,酒精带来的健康风险最明显,估计多达20%死亡个案涉及酒精。以下哪个选项可增强上述结论的权威性:',
  null,
  '{"A":"研究由来自243个机构的512名研究人员共同进行,收集各地由1990年至2016年期间的居民饮酒概况","B":"与饮酒与心血管疾病风险研究相比,饮酒与其他疾病风险的研究还比较有限","C":"2004年意大利学者发表的一项研究表明,适量饮酒有助于减少心血管疾病的发病率,因为与不喝酒的人相比,每天喝20g酒精的人冠心病的发生率低大约20%","D":"研究发现丹麦饮酒比例最高,97%男性有饮酒习惯,亚洲国家则以韩国称冠。在各地区中罗马尼亚男性饮酒量最高,平均每人每天饮用8.2杯酒,巴基斯坦和伊朗则最少"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '增强上述结论的权威性,即表示赞同或者表示该调查样本的选取真实合理,具有普遍性。科研结果更能表现权威,故正确答案为A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-并列关系。',
