(
  '文字-337',
  '文字-337',
  '现如今我们的生活在共享经济的作用下,是发生了许多积极的变化的;比如滴滴打车、共享单车、共享洗衣机,共享雨伞等共享事物的出现,都让我们的生活变得更加便捷。因为共享经济的成本低,并且有着可建立连接性和可持续的特点,所以无论于国于民的影响都是较为积极的,它既给国民提供了便捷,又创造了就业机会,还成就了一批新的企业家以及新产业链。但为什么共享经济偏偏只能在中国大行其道,--旦到了其他国家就水土不服甚至被扼死在摇篮了呢?因为共享经济有四个原则:社会闲置生产力陌生人之间的信任、群聚信任、对民间力量的相信。这段文字接下来最有可能的论述是:',
  null,
  '{"A":"其他国家与中国的国情不同","B":"共享经济对中国经济发展的影响","C":"共享经济的利弊","D":"共享经济有4个原则的概念与介绍"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '前文最后提到共享经济的四个原则,承接上文,所以接下来是对这四个原则的介绍。故正确答案为D。',
  '重点看尾句的新话题和未展开内容，下文通常紧接这一落点。 本题重点：尾句衔接。',
