),
(
  '文字-338',
  '文字-338',
  '当天智库与社交媒体结合,充分发挥其社会影响力成为必然。信息经济的发展不仅改变了社会公众理解公共政策的方式,还刺激了公共政策的需求。进入自媒体时代后,信息( )且明显( ),受众在爆炸式的信息潮和充满噪音的传播环境中,其注意力很容易分散,智库若想有效发挥其影响力,善用社交媒体( )公众眼球更为关键。填入括号中最恰当的一句项是:',
