(
  '文字-340',
  '文字-340',
  '获指标逾期不买车该受罚吗?如果无法保证市民在多长时间内参加摇号一定能摇到,就没有理由对这些_的市民予以处罚,这是基本的公平。况且,国家政策尚且可能__,普通家庭因各种原因临时改变购车计划,为何就要被惩罚呢?填入画横线部分最恰当的一项是:',
  null,
  '{"A":"未雨绸缪 朝令夕改","B":"防患未然 反复无常","C":"居安思危 变幻莫测","D":"临渴掘井 变化多端"}'::jsonb,
  '{}'::jsonb,
