  '"防患未然"指在事故或灾害尚未发生之前采取预防措施。"居安思危"指处在安乐的环境中,要想到可能有的危险。指要提高警惕,防止祸患。这两个词都侧重于对可能发生的危险的预防,而文中没有"危险"的含义,故排除B、C。"临渴掘井''"指感到渴了才掘井,比喻平时没有准备,事到临头才想办法。与文意相反,故排除D。"朝令夕改"指早晨下命令,晚上就改变。形容政令多变,让人无所适从。也形容主张、办法等经常改变,符合文意。故选A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-主题词。',
