(
  '文字-344',
  '文字-344',
  '"明天的降水概率是30%",听到天气预报这句话,你会装好雨伞,还是满不在乎?其实,人们对概率数字的理解会受到先前数字的影响。同样大小的概率数字,在不同的变化趋势中时,人们会对它们产生不同的感觉。无论是海洋污染还是动物灭绝,读到上升趋势数字(从20%上升到30%)时,人们认为事件更有可能发生,尽管他们与读到下降趋势(例如从40%下降到30%)和概率不变时(30%)面对的概率值是一样的。同时这种变化趋势也影响着人们的选择。当概率上升的趋势与好事联系起来时,人们会更愿意为其冒险;而当上升的趋势与坏事联系起来时,人们更倾向于选择稳妥的选项。此外,如果将小概率事件的概率分数的分子与分母都换成比较大的数字时,就会让人产生一种事件更可能发生的感觉,这种现象被称为"比率偏差"。下面哪个词能够代替"满不在乎",而且保持文章的意义不变:',
  null,
  '{"A":"漠不关心","B":"置之不理","C":"泰然处之","D":"毫不在意"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '满不在乎在该语境的意思是不在意。漠不关心和置之不理都形容对人或事物冷淡,语意没有冷淡的意思,排除AB项;C项,泰然处之形成沉着冷静,语意为不在意,没有冷静的意思,排除。D项,毫不在意,意为不在意,符合。选D。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
