  '文字-347',
  '文字-347',
  '30年前日本遭遇能源危机,这个资源匮乏的岛国不是被动地应对--在油价高起时节制消耗,在油价低廉时又恢复消费的无度,而是把能源危机变成提高国家经济竞争力的"黄金时机",举国上下厉行节能,政府打出一系列"政策环保"牌,使得该国的能源使用效率不断提升,成为全球楷模。现在,高油价不仅对日本经济的冲击有限,反而,之前未雨绸缪建立的低资源消耗发展模式,使得日本企业在高油价时代更具竞争优势,低油耗汽车等日本产品风靡全球。可以推知,日本应对能源危机的主动策略是_____。',
  null,
  '{"A":"油价高起时节制消耗,油价低廉时恢复无度消费","B":"改变能源使用方式,以非稀缺能源代替稀缺能源","C":"调整经济增长发力点,改变过分依赖能源的缺点","D":"改变消费观念,加强环保意识,提高能源利用率"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '第一步,定位原文,"日本应对能源危机"话题出现在文段首句,根据"不是被动地......而是......"可知,其主动策略在"而是"之后,即"把能源危机变成提高国家经济竞争力的''黄金时机'',举国上下厉行节能,政府打出一系列''政策环保''牌"。',
  '根据横线位置判断作用，再核对话题一致、逻辑连贯和前后照应。 本题重点：横线在段尾。',
