(
  '文字-348',
  '文字-348',
  '因此,选择D选项。 将下列打乱了次序的语句进行调整,使其还原为-篇精美的小小说。正确的一项是:1他直起腰,快步朝前走去。2五分硬币从他手指缝钻出,掉到地上。3后面传来低低的细语和响亮的、富有节奏的高跟鞋敲打路面的声音;恍惚间,他看到了那熟悉的,随风摆动的裙子。4他朝着校门外的瓜子摊儿走去,手伸进裤兜....5只有那五分硬币静静地躺在那里....6他弯下腰,刚要将它拾起....7高跟鞋的声响也渐渐远去。',
