  '文字-351',
  '文字-351',
  '对于消费者来讲,传统零售业最大的弊端在于信息的不对称。而互联网可以将一件商品的真正定价变得透明,让每个人都知道商品的真正价格区间。传统制造业属于封闭式生产,由生产商决定商品品种、型号,生产者与消费者之间是割裂的。而互联网会让消费者全程参与到生产环节,由用户决定他们想要的商品。这段文字旨在说明:',
