  '文字-352',
  '文字-352',
  '种粮大户们认为,要真正使种粮有效益,农民种粮有积极性,一方面是要加大对种粮新主体的扶持力度,特别是要加大各类补贴力度,规范操作运行,确保各项政策不折不扣地兑现到农民手中,使种粮有效益、不吃亏、得实惠。另一方面,要对稳定多年的种粮规模经营主体优先安排基础设施建设,在国土整治、农业综合开发、粮食基础能力建设、粮食高产创建、测土配方施肥等方面向种粮大户及粮食专业合作社倾斜。对这段文字理解不准确的一项是:',
