  '.等方 面向种粮大户及粮食专业合作社倾斜"得出;D项可由"要对稳定多年的种粮规模经营主体优先安排基础设施建设"得出。B项,原文说的是"要真正使种粮有效益,农民种粮有积极性,一方面是.....",可见此处"种粮有效益"与"农民种粮有积极性"是并列关系,B项"取决于"表述错误。故本题选B。 "土地代耕"是指一些不愿种地或者没能力种地的农民将土地委托给大户或专业合作社,由其代耕、代种。对农民而言,支付一定服务费用,保证自家土地不撂荒,还能增产增收;对代耕大户或合作社而言,收入主要靠代耕费及赚取农资差价等。在一些地区,农民"不想种又舍不得",在打工和务农之间两头忙,两头不得利。而"土地代耕"一方面有利于农业社会化服务组织培育发展,解决务工农民的后顾之忧,另一方面也为农业标准化、规模化经营降低成本、提高效益创造条件。根据这段文字,对"土地代耕"理解准确的是:',
