  '文字-355',
  '当前政府工作中,存在公开的内容不够深,表面事项公开多,深层次的问题公开少,且多存在应付检查的情况严重,公开内容也不全面,事后公开多,事前事中公开少,公开的资料管理也不规范,对政务公开的内容无据可查,失去了应有的监督制约功能。公开信息反馈制度不健全,对群众提出的要求没有做进一步的说明和解释,或避重就轻。对这段话概括准确的是:',
