(
  '文字-357',
  '文字-357',
  '根据联合国教科文组织通过的《保护非物质文化遗产公约》中的定义,"非物质文化遗产"指被各群体、团体、有时为个人视为其文化遗产的各种实践、表演、表现形式、知识和技能及其有关的工具、实物、工艺品和文化场所。各个群体和团体随着其所处环境、与自然界的相互关系和历史条件的变化不断使这种代代相传的非物质文化遗产得到创新,同时使他们自己具有一种认同感和历史感,从而促进了文化多样性和人类的创造力。在本公约中,指考虑符合现有的国际人权文件,各群体、团体和个人之间相互尊重的需要和顺应可持续发展的非物质文化遗产。下列对于"非物质文化遗产"的理解错误的一项是:',
  null,
  '{"A":"非物质文化遗产既可以是被团体或群体认同的文化遗产,也可以是被个人认同的文化遗产。","B":"对于世界上那些已经被认定了的非物质文化遗产来说,各个团体都应该具有认同感和历史感。","C":"关于自然界与宇宙的知识与实践也属于\"非物质文化遗产\"。","D":"非物质文化遗产应该体现各个团体、群体以及个人之间的相互尊重,以顺应可持续发展的要求。"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  'B项错误,非物质文化遗产不是要求各个团体都应该具有认同感和历史感。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
