  '北森言语理解',
  null,
  368,
  '{"kind":"verbal","analysisSource":"原题解析","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-358',
  '文字-358',
  '一个语言无味的世界,必定是一个坚硬、僵死的世界。这样的世界,显然不适合于人类居住,因为人心所需要的温暖、柔软和美好,并不会从这个世界里生产出来。这就不由得让人想念起文学来了--文学的重要功能之一正是软化人心、创造梦想。诚如台湾作家张大春所说,文学带给人的往往是"一片非常轻盈的迷惑",它不能帮助人解决人生问题,它的存在,只是"一个梦、一则幻想"而已。然而,谁都不能否认,只有那种存着梦想的人生,才是真的人生。对这段话理解正确的一项是:',
  null,
  '{"A":"没有文学就没有梦想,人生就没有希望","B":"人居住的世界里需要文字来帮助解决人生问题","C":"文学的存在是为了使人心变得柔软","D":"文学虽没有实际意义却也必不可少"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '根据文章的最后一句话"然而,谁都不能否认,只有那种存着梦想的人生,才是真的人生"可以推断出选D。A项夸大了文学的作用;',
