  '文字-360',
  '常随时间衰退。";B项对应原文"大脑并不是完美的电脑似的数据存储设备,而是易错的肉质器官。";D项对应原文"记忆常含有空白、错误暗示和近似。";只有C项和原文"当记忆被频繁唤起时,它们最容易变得扭曲,并且这可能意味着,回忆越重要,回忆的次数越多,就越可能出错"表达不符,故答案选C。 从下述四句中选出没有语病的句子:',
