(
  '文字-365',
  '文字-365',
  '抑郁症最为突出的症状表现主要有由两个方面,一是情绪低落,二是兴趣丧失,此外通常还伴随睡眠障碍、体重剧烈变化,严重的还会伴有思维障碍、自杀意念与尝试等等。到底是先失眠再抑郁,还是先抑郁再失眠?专家表示,长期睡眠不足容易引起脑内神经递质分泌紊乱,这其中就包括多巴胺、五羟色胺等与抑郁症形成有密切联系的神经递质。由于这些神经递质的变化,患者自然而然容易变得情绪低落,对所有事物都丧失兴趣。这个改变可能在没有意识到的时候就已经悄然发生了。另方面,睡眠问题也可以用于判断抑郁症、焦虑症及其他多项心理问题的标准之一。抑郁症患者通常容易早醒或白天嗜睡,而焦虑症患者通常难以入睡且睡眠深度较浅。根据文段下列说法中错误的是( )。',
  null,
  '{"A":"对任何事物都提不起兴趣是抑郁症的表现之一","B":"脑内神经递质五羟色胺与抑郁症有密切关联","C":"睡眠问题是判断抑郁症和焦虑症的标准","D":"焦虑症患者通常会伴有睡眠问题"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '选项C中说得过于绝对了,睡眠问题只是判断抑郁症和焦虑症的标准之一。故答案选C。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-排除错误项。',
