  377,
  '{"kind":"verbal","analysisSource":"原题解析","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-366',
  '文字-366',
  '梦,是一种私人的、神秘的、稍纵即逝的体验。研究者调查了其中的暴力梦,通过对参与者进行性格测试,并调查了他们做暴力梦的频率、暴力梦发生的动机。结果发现在参与者所有的噩梦中,有暴力行为的梦占比为18%至28%。梦中大多数的攻击行为都是有意图的,最严重的是杀人,而动机大多数都是自我防卫。而这些更容易做暴力梦的人,通常在过去的现实生活中也更暴力。同时更容易做暴力梦的人在性格测试中表现得更神经质、更具有攻击性、也更有创造力。在现实生活中,相对于不做噩梦、不做暴力梦的人而言,容易做暴力梦的参与者获得的创造性成就也更多。下面对本文内容理解正确的是:',
  null,
  '{"A":"那些创造力更高的人在现实生活中也更加容易做出暴力行为。","B":"不做暴力梦的人虽然攻击性更低,但创造性成就也更少。","C":"暴力梦在每个人的梦中占有不同的比重,从18%到28%不等。","D":"暴力梦产生的动机大多是自我防卫。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '梳理文段的中心句与行文重点后，C项“暴力梦在每个人的梦中占有不同的比重,从18%到28%不等。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择C。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-并列关系。',
