(
  '文字-368',
  '文字-368',
  '高跟鞋是女士们最大的敌人。多样的款式令她们炫目,时尚神话让她们觉得高跟鞋十分漂亮,而这实际上却给她们造成了不间断的痛苦。任何一位足病医生都知道,高跟鞋会导致脚变形,增大患腰伤骨折伤痛的概率。当然,为公平起见,高跟鞋也有积极的一面,例如给草坪通风或防身,但与双脚肿胀后带来的痛苦比起来,这些"好处"实在是不值一提。作者期待女士们应该怎样去做?',
