  'D',
  '梳理文段的中心句与行文重点后，D项“扩声系统的特点”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择D。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
