  381,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-370',
  '文字-370',
  '一个自私的人要比性格随和的人更有可能获得权力地位吗?这是大多数人都比较关心的问题,谁也不愿意在权力位置上的人是个自私的人。一项新研究发现那些自私、不被信任和好斗的人并不比那些慷慨、可靠和友善的人更容易获得权力。这是因为他们用手段获得的权力提升都会被他们糟糕的人际关系所抵消。但坏消息是,在组织中,让自私的人担任主管的次数与友善的人并没有差异。之前的研究表明,亲和力是担任有权力和领导力职位的重要条件。相比之下,外向的人最有可能在他们的组织中获得提升,这是基于他们的社交能力、经历和自信。下面对本文内容理解正确的是:',
  null,
  '{"A":"权力地位的易得性并不完全受性格所决定。","B":"那些自私的人不会被允许拥有权力。","C":"只要拥有亲和力就能获得权力地位。","D":"在组织中担任主管的都是外向的人。"}'::jsonb,
  '{}'::jsonb,
