(
  '文字-371',
  '文字-371',
  '与外貌毫无吸引力的人相比,美貌的人拥有更多的社会理想属性。研究者发现当外貌信息是人们已知的唯一信息时,它会在很大程度上影响他人对这个人的判断。实验中,被试被告知一位女性犯了入室盗窃罪或诈骗罪,他们需要为罪犯量刑。结果显示,在入室盗窃案中,被试给外貌吸引人的罪犯的平均量刑低于外貌不吸引人的罪犯;在诈骗案中,情况则截然相反——被试对外貌吸引人的罪犯的平均量刑高于外貌不吸引人的罪犯。当犯罪行为本身与罪犯的外貌无关时,人们会对貌美的罪犯从宽处理;当犯罪行为本身与罪犯的外貌有关时,人们会对貌美的罪犯更严厉。下面最适合本文的标题是:',
  null,
  '{"A":"美貌的人犯罪惩罚更轻?","B":"美貌决定惩罚力度","C":"美貌——逃脱惩罚的工具","D":"美貌带来的犯罪"}'::jsonb,
