(
  '文字-372',
  '文字-372',
  '咖啡是全世界最受欢迎的日常饮品之一。重要的是,喝咖啡可以降低多种健康风险,包括减少肥胖。最近,在一项发表于《营养学杂志》的研究中,研究人员通过分析由美国健康和营养检查采集的数据,研究了参与者每日的咖啡摄入量与全身脂肪百分比及腹部或躯干脂肪之间的关系。结果表明,与不喝或少喝咖啡的女性相比,每天喝2~3杯咖啡的所有年龄段女性的平均全身脂肪百分比低2.8%,而饮用的咖啡是否含有咖啡因及饮用者的健康状况并不影响这种关系,但在男性中,这种关系的显著性较低。研究认为,即使咖啡被证明能减少脂肪,但应该结合健康的饮食,才能更加有效。下面对本文内容理解正确的是:',
  null,
  '{"A":"只要长期坚持喝咖啡就能减肥成功。","B":"不喝或少喝咖啡的女性普遍肥胖。","C":"女性喝咖啡减少脂肪的效果比男性显著。","D":"喝咖啡的女性比不喝咖啡的女性更加苗条。"}'::jsonb,
