  '文字-373',
  '文字-373',
  '最近,一项发表于《科学》的研究也许有助于填补东亚遗传学史上由狩猎采集转变为农耕经济的空白。研究人员从25个分别来自新石器时代东亚南部和北部的人骨骼中提取了DNA样本。分析显示,当时的人类已经显示出现代东亚人的遗传特征,但当时南北人群的遗传分化比现在更明显。现代的东亚人来自新石器时代东亚的南北人群的混合,但在基因上,与当时的北方人更接近。这证明了一个重要的混合事件——在新石器时代晚期,黄河以北人口向南流动。下面对本文内容理解正确的是:',
