  '{"A":"狩猎采集到农耕经济的过渡时期得到了明确。","B":"研究提取了25个DNA样本。","C":"新石器时代东亚的南北人群的交往逐渐加深。","D":"现代东亚人的遗传特征在新石器时代开始体现出来。"}'::jsonb,
