(
  '文字-374',
  '文字-374',
  '在探索某种成分是否具有抗癌功效时,最先进行的是细胞层面的实验。研究发现柠檬苦素在抑制癌细胞(白血病细胞、乳腺癌细胞等)生长方面效果不错,柠檬中的几种黄酮类成分也有抑制功效。此外,柠檬所含的柚皮素成分具有保护细胞,促进DNA损伤修复的功能,而DNA损伤是导致细胞癌变最主要的原因。在进一步的动物实验中,同样都是患乳腺癌的大鼠,那些经常食用柠檬果汁的大鼠比不食用这种果汁的大鼠,癌症发展速度更慢。但也有研究者认为,柠檬中的叶酸在抗癌作用上更像一把双刃剑——条件适宜时它可以减慢乳腺癌的发展,但过度摄入的情况下它也可能促进癌症发生。下面对本文内容理解正确的是:',
  null,
  '{"A":"在细胞层面,柠檬苦素具有抑制白血病细胞、乳腺癌细胞出现的功效。","B":"柠檬中的黄酮类成分可以加强柠檬苦素对癌细胞的抑制功效。","C":"癌细胞的出现是由于DNA损伤,而柠檬中的柚皮素可以促进DNA修复。","D":"柠檬中的黄酮类成分、柚皮素、叶酸以及柠檬苦素对抗癌都有一定功效。"}'::jsonb,
