  '文字-375',
  '医疗产业可通过四个维度进行考察——需求、供给、准入和支付,这四个维度构成了完整的医疗服务链条。需求通常产生于患者出现症状(一般在显性化之后),然后通过信息渠道到达供给方。供给方通常为医疗机构或药店,它们会对患者的信息或数据进行判断,并通过物理准入给出解决方案(即治疗或处方),提供服务。患者最后根据供给方报价全部或部分通过第三方支付(不同形式的医疗保险)进行支付。根据本文内容,下面推断正确的是:',
