  '文字-376',
  '文字-376',
  '麻醉药是从罂粟中提炼出来的。人类比较熟悉的麻醉药包括吗啡、海洛因和美沙酮。由于海洛因进入人脑的速度比吗啡快,所以它能引起较大的快感和较强的成瘾性。麻醉剂可使人们减少对现实问题的注意和降低对痛觉的敏感性。尽管麻醉剂常引起成瘾,但在医学监督下作为镇痛剂使用时几乎不会成瘾。成瘾性取决于个体、服药原因、剂量和社会背景。研究发现,大脑可以产生被称为内啡肽的神经肽,它表明麻醉剂是通过作用于大脑中的受体来缓解疼痛的。内啡肽间接刺激多巴胺的释放。内啡肽突触抑制腹侧被盖区神经元,而后者释放一种抑制多巴胺神经元激活的神经递质——GABA。通过抑制这种抑制剂,增加多巴胺的释放。然而,内啡肽不借助多巴胺也可产生强化作用。以下内容在文中有体现的是:',
