(
  '文字-390',
  '文字-390',
  '3G时代使获取信息的能力在时间和空间上达到了极致;4G通信技术开启了移动互联网产业链的新时代,满足了人们学习、生活、工作等各方面的需求。5G的应用将促进信息产品和服务的创新,智能终端设备性能将进一步提升。同时,互联网+物联网线上线下融合将为生产生活方式带来变革。新型技术和新型产业深度融合将全面应用于工业物联网、车联网及其他垂直行业的特殊应用需求,大量信息的采集、处理、分析及管理,将全面应用于智慧城市、环境监测、智慧农业、森林防火等场景。十四五必将是智能发展的五年,各行各业都将通过新信息技术的升级步入新的发展模式。因此,规划必须充分预测、考虑到可能出现的新机会、新问题、新发展,才能够更有效的符合时代诉求,真正起到规划引导的作用。下列说法与原文相符的是:',
