  '文字-391',
  '文字-391',
  '最近,以色列特维拉夫大学的科研人员使用人体组织制造出了世界上第一颗3D打印心脏,给需要通过"换心"来延续生命的晚期心衰患者带来了新希望。自上世纪60年代前后的首例肾脏和心脏移植手术相继成功以来,器官移植的临床技术日益完善,手术成功率也在不断提高。然而在很多国家,器官等待者和捐献者的数量相差很大。即便有幸等到合适的器官并成功移植,术后的排异反应也仍然会对患者生命构成威胁。下文可能讲述的是:',
