(
  '文字-395',
  '文字-395',
  '法律和道德很大程度上构成了当代社会秩序的保障,法律法规等明确的规则既塑造了人们相当一部分的道德观念,又能够在道德争议出现时及时有效地给出回答,可以说,遵守法律等规则就已经有可能更快地做出一些道德判断。除此之外,做事情考虑后果也能辅助人进行道德判断,通常来说,如果一种行为很大概率会导致不好的结果。那这个行为很有可能是不道德的。这些道德判断的逻辑已经广为人知。而近期的一项最新研究通过心理实验和模型发现,普遍化的逻辑也在道德判断中起着重要的作用。而且在规则尚缺失或后果难以推理预知的情况下,通过"如果每个人......"将行为普遍化,有可能产生独特的思维价值。下列说法与原文不相符的是:',
