(
  '文字-399',
  '文字-399',
  '牛津大学的研究人员从1月初开始研发2019新型冠状病毒疫苗。当时疫情极度轻微,这种病毒甚至还没有正式名称。6个月后,已经有超过60万人死于新冠病毒。现在,牛津大学团队在开发有望阻绝疫情的疫苗上,占据领先地位。阿斯特捷利康公司也已经快速进行全球布局,准备生产数十亿剂疫苗,但两个关键问题依旧悬而未解:这款疫苗是否安全?有无功效?7月20日,在《柳叶刀》期刊上发布的研究结果,让大家一窥解答。那份针对牛津疫苗的试验研究,从4月起开始进行,并募得1000名自愿者参与。作为论文作者之一的希尔表示,这款新疫苗会触发强烈的免疫反应,而且看起来接种者耐受度高、使用上又安全。接种者获得抗体并出现「非常卓越」的T细胞反应。抗体与T细胞是免疫系统的两大支柱,前者会辨识、连上病原体,并使其失能,后者则会辨识并杀死已遭受感染的人体细胞,阻止病毒在那些细胞中继续增生。根据这段文字,以下说法正确的是:',
  null,
