(
  '文字-403',
  '文字-403',
  '值得注意的是,_____。有研究者担忧:"电子产品依赖症"会不会影响这一代人的信息获取偏好、阅读习惯、思考能力?电子媒介形式多样,但对知识的呈现、信息的传递却往往是浅层次、碎片化的,浮光掠影之下极易让人陷入一知半解、囫囵吞枣,更别说其间信息繁芜、泥沙俱下。当孩子们习惯用碎片化娱乐化的轻松方式接受信息,便难以在门槛更高的文字世界中专注阅读、深入思考。一项科学研究也为此提供了佐证:重度使用智能电子产品会对孩子的大脑皮层产生损害,长时间下去孩子的语言和推理思考能力都会受损。我们不能任由电子产品占领孩子的世界,相关部门划出红线、发出警告,为的就是帮助孩子保持与屏幕的距离。填入画横线部分最恰当的一项是:',
