(
  '文字-406',
  '文字-406',
  '5月30日从北京空间信息传输中心获悉,我国天基测控系统圆满完成天舟二号发射、入轨及与天和核心舱交会对接段测控任务。此次对接是我国在轨进行的第二次快速交会对接,与上一次2017年天舟一号货运飞船与天宫二号飞行器的交会对接相比,此次对接中,天舟二号货运飞船增加了"全相位全自主交会对接方案"。"全相位"就是无论目标飞行器在入轨时和空间站相距多少,天舟都能以最快速度或者在规定时间点实现对接,而不用专门根据空间站的位置来选择飞船发射时间,真正实现了全天候发射。"全自主"就是从飞船入轨到交会对接成功,全程不需要人工干预,飞船上的控制器自主规划完成。手控交会对接和自动交会对接是空间交会对接系统的左右手,互为备份,是系统可靠性的重要保障,天舟二号飞船也装备了手控系统。在货运飞船与空间站交会对接的最后平移靠拢段,手控系统具备支持空间站内航天员进行手控遥操作实现前向或后向交会对接或撤退撤离的能力。一旦自动交会对接模式出现故障,空间站上的航天员可以通过"遥操作",以遥控的方式"驾驶"飞船,帮助货运飞船规避空间站,或者安全、准确地与空间站对接。下列说法与原文相符的是:',
  null,
  '{"A":"\"全相位全自主交会对接方案\"真正实现了飞船全天候发射和全程自主控制","B":"到目前为止,我国已成功完成两次在轨进行的全相位全自主快速交会对接","C":"在货运飞船与空间站交会对接的最后阶段,需要宇航员通过手控系统遥控\"驾驶\"飞船,实现对接","D":"自动交会对接是空间交会对接系统可靠性的唯一保障"}'::jsonb,
