(
  '文字-407',
  '文字-407',
  '近日发布的有关网络视听研究报告显示,截至2020年12月,中国网络视听用户规模达9.44亿人,用户平均每天花两小时看短视频,28.2%的网络视频用户不按原速观看视频节目,00后群体近4成选择倍速观看方式。这些倍速看视频的年轻人到底在赶什么?现在年轻人的工作、生活节奏较快,用快进的方式观看网络影视,表明他们的影视感、互联网思维、网感逐步增强,鉴赏、分析网络影视的水平不断提高,能够准确判断各种网络影视内容对自己具有什么价值。用正常速度观赏优秀或是良好的网络影视,用倍速观看制作水平一般的网络影视,不把时间浪费在较差的网络影视上,正是网络世界的观影现实。而正是这种观影现实,将倒逼有关网络影视创作团队尊重网民需求,不断提高制作质量。包括短视频在内的网络视频节目在叙事、表演、摄影、剪辑等方面都要适当加快节奏,不断提高品质。网络电影、网络剧、网络节目、网络短视频在文化多样化的基础上进行精品化,有助于挤压拖泥带水的部分,避免冗长拖沓,并保留精华。这段文字主要叙述了:',
  null,
  '{"A":"倍速观看的观影现实将倒逼创作团队提高制作质量,加快节目节奏","B":"00后因为生活和工作节奏较快而倾向于倍速观看视频","C":"00后能通过判断网络影视的价值高低而选择是否倍速观影","D":"倍速观看网络影视成为00后的观影趋势"}'::jsonb,
