  '文字-408',
  '文字-408',
  '巴纳姆效应是一种心理现象,人们会对于他们认为是为自己量身定做的一些人格描述给予高度准确的评价,而这些描述往往十分模糊及普遍,以致能够放诸四海皆准适用于很多人身上。下列情形中属于巴纳姆效应的是:',
