  '文字-409',
  '永久收入,又称持久收入,由美国著名经济学家弗里德曼提出。它是指人们可以预期到的长期收入,即预期在较长时间以上(3年以上)可以维持的稳定的收入流量,一般用过去几年的平均收入来表示。根据上述定义,下列选项最不可能属于永久收入的是:',
