(
  '文字-410',
  '文字-410',
  '"互联网司法"是经过大量司法实践总结出的一个全新概念。从本世纪初开始,英国、韩国、新加坡、奥地利等国就把互联网作为公众"触达司法"的重要手段,客观来讲,中国互联网司法起步较晚,没有先发优势。党的十八大以来,随着网络强国战略全面实施,我国互联网司法在技术应用、程序规则、实体裁判等领域全方位转型升级;放眼国际,已从"跟跑""走向"领跑。从早期的在线缴费、视频听证、庭审网络公开,到现在的全流程在线诉讼、智能化应用、协同化办案,近年来,中国大力推进互联网司法、智慧法院建设,已逐步构建起中国特色、世界领先的"互联网司法"新模式。下列最适合作为文段标题的是:',
