(
  '文字-411',
  '文字-411',
  '如果说山地大猩猩有什么标志性动作,那就是快速用手捶打胸部产生"嘭嘭嘭"的鼓声。而据自然科研旗下《科学报告》近日发表的一项动物学研究认为,这一捶胸行为,或能传递关于其体型的重要信息,同时依据声音帮助它们识别不同个体。这一发现展现了非言语行为或有助于山地大猩猩的交流。研究团队发现,体型较大的雄性,捶胸的声音频率显著低于较小的雄性。他们指出,体型大的雄性喉囊也较大,令捶胸时声音频率较低。不同大猩猩捶胸的时长和次数也有所差异。这些与体型无关,但或使其它大猩猩辨认出正在捶胸的个体。鉴于此,研究人员认为,大猩猩或许能利用捶击胸部的声音,在自己生活的热带密林中互相交流,尽管它们看不到彼此。他们推测,山地大猩猩可能会使用捶胸传递的信息来宣告择偶以及评估竞争者的战斗能力。下列说法与原文相符的是:',
