  '{"A":"体型较大的山地大猩猩捶胸声音频率较低","B":"科学家能根据山地大猩猩捶击胸部的声音判断传递的信息内容","C":"山地大猩猩用捶击胸口来传递特定信息","D":"体型不同的大猩猩捶胸的频率和时长也不同"}'::jsonb,
