  '文字-412',
  '文字-412',
  '近30年来,有理论曾预测银河系自转速度在减慢,但并没有实证。近期英国牛津大学、伦敦大学等机构研究人员利用盖亚空间望远镜,对银河系棒旋结构的一组恒星——赫拉克勒斯星流进行了数据分析。分析发现,赫拉克勒斯星流所富含的重元素(天文学所称的"金属")可以表明它们正远离银河系中心,由于旋结构不断减速,它们在向外围移动,进一步数据及推断表明:这个由数十亿颗恒星组成、相当于数万亿个太阳质量的棒旋结构,自诞生以来它的自转速度变慢了至少24%。作为文章的引言,该文章最有可能谈的是:',
