  '压力会加速头发变白吗?美国研究人员在近日发表于e-Life的一项新研究中,首次提供了心理压力与人们头发变白之间的定量证据。他们还发现,当压力消除后,头发的颜色可以恢复。研究人员分析了14名志愿者的头发,将结果与每个志愿者的压力日记进行比较。在日记中,志愿者被要求回顾一天内发生的事情,并对每周的压力水平进行评级。当研究人员将头发与压力日记进行比对后,发现压力与头发变白之间作存在惊人的关联,在某些情况下,随着压力的解除,头发变自的趋势出现了逆转。下列最适合作为文段标题的是:',
