(
  '文字-425',
  '文字-425',
  '人以意义来理解世界,也以此与他人交流、合作。米塞斯管举过一个例子,例如某人闯入了一个从未去过的原始部落。那些原始人未开化,没有语言,或者即使有语言他也听不懂。但是,如果他看到这些原始人架锅生火,他就会知道,他们是要做饭了。人类有相似的心智结构,即使语言不通,也可以相互理解。如果换成机器人呢?除非是科幻电影里那些由演员扮演的机器人,否则它只会搜索和输出代码,而不会真正试图去理解眼前所发生的事。可见,填入画横线部分最恰当的一项是:',
