(
  '文字-426',
  '文字-426',
  '现今的民事诉讼愈见复杂,讼辩双方除了会传召就事实作供的证人外,也有不少案件会邀请专家证人出庭作供。所谓专家证人,是指具有专业知识或专家资格并在法庭上提供专家意见的人。根据上述定义,以下涉及专家证人的是:',
  null,
  '{"A":"小念因为长相在学校遭受校园霸凌,出现了严重的心理问题。小念的母亲对霸凌小念的同学提起了诉讼,并聘请小念的心理咨询师出庭说明霸凌与小念心理问题间的关联","B":"甲某在小区楼下被乙某从高空抛出的垃圾砸伤。甲某对乙某提起诉讼,并且目睹本案经过的李医生出庭描述事故经过","C":"小黄家有一幅据传是清朝知名画家的画作,小黄为了确认其真实性,登上某电视台的宝物鉴赏节目,请专家帮忙鉴定","D":"A货运公司同B供应商之间因货物由于大火产生毁损而产生国际贸易争端,作为国际贸易仲裁委员会的C介入为A与B进行仲裁"}'::jsonb,
