(
  '文字-427',
  '文字-427',
  '汽车业从诞生之日起,有两类公司始终处于行业金字塔的顶峰,一个是石油公司,另一是整车厂,两者共同主导了过去百年的汽车业沉浮,也是整个行内市值最高的两类公司。但随着电动车的兴起,石油公司已经被革命,价值正一步步降低、剩下的整车厂又会是什么命运呢?其实。整车厂之所以能够成为汽车业号令天下的"王者",在于燃油车的基础技术属于机械学,需要一个动力总成架构,这个框架只能由整车厂去统筹,所以一大批的配件厂商只能围着整车厂转,用时髦的话说,那是硬件定义汽车的时代。但到了自动驾驶时代。整个汽车的基础性架构变由软件来定义,机械动力的重要性降低,数据收集、分析、决策、执行站上了C位。整车厂的统筹作用被降低了一个档次,和当初的配件厂一样、整车厂也只能围绕着软件转。如果整车厂没有软件能力,那就真的只剩下加工制造这个价值了,而自动驾驶对于整车厂的颠覆,还远不止于此。这段文字紧接着谈论的内容最可能的是:',
  null,
  '{"A":"自动驾驶带来了软件定义汽车的时代","B":"自动驾驶引起汽车周边需求的变化","C":"自动驾驶将如何颠覆汽车行业的商业模式","D":"自动驾驶普及会淘汰互联网打车平台"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
