(
  '文字-428',
  '文字-428',
  '世界正在经历百年未有之大变局,新一轮科技革命和产业变革 _____,人类面临的共同挑战需要各国携手共进,没有一个国家可以成为独立的创新中心,或独享创新成果。新科技革命和产业变革的时代浪潮奔腾而至,开放包容、互惠共享的国际科技创新交流才是,各国应为推动全球经济复苏、保障人民身体健康作出贡献。让科技创新成果为更多国家和人民所及、所享、所用。依次填入下列各句横线处的词语,恰当的一组是;',
