(
  '文字-429',
  '文字-429',
  '中国人民银行原行长周小川曾在采访中提到,目前定位下,央行发行的数字货币主要是替代实物现金。那么,数字人民币自然与银行存款有本质的区别--持有数字人民币如同钱包里装了现金,不能指望它"钱生钱",而银行存款则可以产生利息。第三方支付平台里的电子货币本质上也属于存款,虽然我们拿不到平台里"零钱"的利息,但这些电子货币其实都需要依托平台开设的银行账户,所以不能与数字人民币混为一谈。不计息、匿名交易、无需网络都是纸钞和硬币的特性,同一定位的数字人民币也模仿了一些类似的功能。以匿名交易为例,客户可以选择开立不同等级的数字人民币钱包,钱包权限越低,交易限额、余额限额也越低。最低权限钱包仅需手机号即可开立,依照法律规定,电信运营商不得将客户信息披露给银行等第三方,所以数字人民币在一定程度上实现了匿名支付。下列说法与原文相符的是:',
  null,
  '{"A":"数字人民币包含了纸钞和硬币的所有特性,包括不计息、匿名交易、无需网络","B":"央行发行的数字货币的定位是代替银行存款进行支付","C":"第三方支付平台里的电子货币不产生利息,因此本质上和实物现金没有区别","D":"数字人民币钱包可以进行匿名交易,交易额度受到钱包等级限制"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '逐项对照原文，D项“数字人民币钱包可以进行匿名交易,交易额度受到钱包等级限制”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择D。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
