(
  '文字-430',
  '文字-430',
  '造成亚洲市场和北美市场财富分配差异化的原因主要有两个方面。第一,发达国家有更完善的金融市场。个人投资者也更容易进入市场。其次,发达国家的货币体系也相对稳定,稳定的货币有助于鼓励富人持有现金、存款、证券和其他流动资产。然而在缺乏这些要素的成长型市场,个人投资者就往往会将更倾向于将财富投资于实物资产,但在下一个五年,情况将发生改变。在亚洲,金融资产的增长将超过不动产增长。特别是,投资基金将成为增长最快的金融资产类别,预计至2025年复合年增长率将达到11.6%,这一势头也将加快个人投资者投资方向的转型。填入画横线部分最恰当的一项是:',
  null,
  '{"A":"资本市场的日益成熟,将改变成长型市场的财富结构","B":"成长型市场的投资市场发展会超越发达国家,个人投资者的收益得到改善","C":"实际上,成长型市场的高增长投资机会更多,亚洲就属于成长型市场","D":"金融普惠性的加深,将缩小富人和普通人投资的差距"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
