  '文字-434',
  '文字-434',
  '可更新资源是指能够通过自然力以某一增长率保持或增加蕴藏量的自然资源。如太阳能、大气、水等,当代人消费的数量不会使后代人消费的数量减少;又如森林、各种野生动植物等,不人为破坏基本上持续稳定。根据上述定义,下列说法正确的是( )',
  null,
  '{"A":"煤由太阳能转化而形成,因此是可更新资源","B":"很多金属机械报废后可以回收,因此是可更新资源","C":"春风吹绿了草原,草原是可更新资源","D":"地球上的淡水资源已经非常稀少,属于不可更新资源"}'::jsonb,
