  '文字-439',
  '文字-439',
  '河南许昌市灵井遗址出土了一个微型鸟形雕像,这是我国发现的最古老的艺术品。研究发现,这种雕像由烧过的骨头雕刻而成,使用了研磨、琢切、刨削和刮削四种技巧,制作于约1.3万~1.38万年前。相比在西欧和西伯利亚出土的同时期的鸟类雕塑,这个雕像具有一个独特的基座替代可能的短腿使之站立。在东亚,之前并未发现过这类雕塑艺术,之后也不见其继承者。过去中国发现的最古老的雕像是在北京东部上宅遗址中出土的鸟形玉器,距今约5000年,而这一新发现将中国雕塑的起源向前推进了至少8501年。根据本文内容,下面推断正确的是:',
  null,
  '{"A":"灵井鸟雕塑出土损毁严重且难以修复。","B":"目前灵井鸟雕像的来源和传承仍然是一个谜。","C":"河南出土的灵井鸟雕像比北京出土的鸟形玉器更加精致。","D":"灵井鸟雕像的出土对中国雕塑史没有任何影响。"}'::jsonb,
  '{}'::jsonb,
