(
  '文字-443',
  '文字-443',
  '有人像百灵鸟一样早起早睡,也有人像猫头鹰一样晚起晚睡。有研究者认为晚睡晚起的人更聪明,他们测量了新兵的昼夜节律得分、记忆力、敏捷性,结果发现越是早起早睡的新兵,他们在记忆力和敏捷性方面都要弱于晚起晚睡的同伴。在创造思维的所有维度上(流畅性、灵活性、独创性以及跨越性),猫头鹰型的人得分都要高于百灵鸟型的人,特别是在独创性方面。猫头鹰型的人更喜欢使用右脑思考,强调直觉和综合,而百灵鸟型的人更喜欢使用左脑思考,讲究逻辑和分析,而创造性跟右脑有更密切的关系。研究中参与者的年龄从19岁到76岁,具有相当广的年龄跨度。下面最适合本文的标题是:',
  null,
