  '文字-445',
  '文字-445',
  '人类的正常活动是白天工作晚上休息,然而工业自动化却要求机器24小时不间断工作。一个人大约需要6天才能适应黑夜和白天颠倒,但在工业生产中几乎每星期都要倒班,倒班制度使工人的所有生活都变得混乱。解决这个问题似乎只有把夜班固定给一批人去干,但同时也要挑选一些能快速适应轮班的人来缓解轮班干活的紧张。根据体温挑选人员不失为一种好方法,因为人们工作效率高时体温也较高,只是这种方法至今并未得到实际的应用。下列哪项内容在材料中没有被提到:',
  null,
  '{"A":"人的体温可以随着工作状态变化","B":"可以把体温当做挑选轮班工人的参考","C":"让所有工人黑夜颠倒不利于提高工作效率","D":"让固定的人上夜班已被证明是解决问题的最好方法"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '梳理文段的中心句与行文重点后，C项“让所有工人黑夜颠倒不利于提高工作效率”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择C。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
