  '文字-463',
  '文字-463',
  '现代社会,人们越来越注意养生,许多老人选择晨练。但是,早晨刚起床时交感神经兴奋,较其他时间更易出现心血管意外,糖尿病患者晨起空腹运动时发生低血糖的风险也更高。如果是赛冷的季节。也压会随温度降低而升高,在气温很低的时候外出锻炼更容易诱发心血管及脑血管疾病。并且寒冷还可能诱发支气管哮喘。如果空气污染指数爆表了,那最好就不要出门了。这段文字作者要阐明的道理是( )。',
