  '文字-466',
  '文字-466',
  '概念同化,就是利用学习者认知结构中原有的概念,以定义的方式直接给学习者提示概念的关键特征,从而使学习者获得概念的方式。在这一过程中,认知结构中的原有概念可以为一个新概念的吸收提供一个固定点,当学习者在已有的概念和新概念之间建立起一种实质性的联系以后,学习者就会获得新概念的具体意义。根据上述定义,下列不属于概念同化的是( )',
