  '文字-472',
  '文字-472',
  '成瘾的概念最早来自于药物成瘾。很多人以为"孩子天天到晚老玩游戏,怎么说都不听"是网络游戏成瘾。但实际上,"网络游戏使用时间的长短"并不是网络游戏成瘾的核心诊断标准,甚至不是标准之一。比如电竞选手,虽然每天接触网络、接触游戏的时间非常长,但他们并不是成瘾,因为这是工作,是可控制的使用。对这段文字意思理解最为准确的是( )。',
