(
  '文字-476',
  '文字-476',
  '先天性心脏病是多基因疾病,个案的发病原因往往难以确定。要解决这一难题,首先需要尽可能地发现先心病相关基因。专家发现4号染色体长臂(4q35.1)片段缺失与先心病相关。2012年曾有文献报道提示其中的SORBS2基因可能与先心病相关。而SORBS2缺失与先心病的可能关联在近十年里一直没有明确证明。专家通过胚胎千细胞定向分化体系、先心病患者靶向测序等多个研究途径来确认SORBS2缺失的致病性。在Sorbs2敲除小鼠中,研究人员发现房间隔缺损或双房间隔等发育异常表型。这项研究从疾病群体、动物以及细胞水平提供了多重证据,证实了SORBS2是先心病的致病基因并阐明了其致病机制,这为更多地发现先心病的弱效致病基因提供了借鉴。根据这段文字下列说法中错误的是( )。',
