  '{"A":"Sorbs2敲除小鼠会出现心脏发育异常的情况","B":"SORBS2基因在4号染色体上","C":"先心病患者基因靶向测序是研究先心病发病原理的有效途径","D":"SORBS2基因缺失与先心病的关联并没有得到证实"}'::jsonb,
