(
  '文字-486',
  '文字-486',
  '今年的寒冬,其实恰恰部分源于全球变暖,这种反常的现象,和一种极地漩涡的气候现象有关。极地旋涡是一种发生于极地、介于对流层和平流层的中上部、持续性长且规模大的气旋。最早记载极地涡旋现象的文献出现于1853年。在北半球的冬季,这种现象会导致突然性平流层暖化。1952年,无线电探空仪在海拔高度超过20公里的观测中发现了这种现象导致的平流层暖化。在2013年后的北美冬季,媒体报道中经常提到这种现象,使得该术语推广成为了对极低温寒潮的解释。下列关于极地旋涡的表述正确的是: ( ) ?',
  null,
  '{"A":"极地旋涡现象最早出现于1853年","B":"极地旋涡说明了极低温寒潮现象","C":"极地旋涡是全球气候变暖的\"元凶\"","D":"极地旋涡是一种反常的气候现象"}'::jsonb,
