(
  '文字-487',
  '文字-487',
  '司马氏建立的西晋,结束了三国乱世,是东汉之后中国历史上又一个大一统的王朝。政治方面,西晋完善了九品中正制,将各省部独立出来,这为以后隋唐的三省六部制打造了基础。经济也开始恢复和发展,文化走向多元发展,是一个文化开创、冲突又融合的时代。但是晋朝统一后不久,就发生了八王之乱。八王之乱是史上最为严重的皇族内乱之一,使得国家遭受了极其严重的破坏。长达十六年的动乱导致整个西晋军队伤亡达到五十余万!·受到波及的平民更是达到百万之众!北方游牧民族趁机入侵,从而开启了五胡十六国时代,汉人沦为了肆意杀戮的对象,汉族人口数量从初期的1200余万降到了不足400万!东晋还造成了造成了如王敦之乱、苏峻、祖约之乱等叛乱。晋朝作为继秦、汉以后第三个大一统的王朝,反而给华夏带来了巨大的灾难。下面最适合本文的标题是',
  null,
  '{"A":"晋朝带来的灾难导致汉人被肆意屠杀","B":"大---统的晋朝,但却给华夏带来了更大的交难","C":"晋朝八王之乱导致国家被入侵,开启了混乱的五胡十六国时代","D":"晋朝给带来了多场叛乱,给华夏文明造成了巨大的打击"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
