  '文字-494',
  '文字-494',
  '"粽子香,香厨房。艾叶香,香满堂。"端午节也称端阳节、龙舟节、浴兰节等,与春节、清明节、中秋节并称为中国的四大传统节日。《荆楚岁时记》曾记载,因仲夏登高,顺阳在上,第一个午日正是登高顺阳好天气之日,故五月初五亦称端阳节。事实上,端午节除了诱人的粽香和精彩的龙舟赛之外,还蕴含着丰富的文化价值。"节分端午自谁言,万古传闻为屈原。"虽然关于端午节的历史渊源众说纷纭,但影响深远的主要还是爱国诗人屈原。"长太息以掩涕兮,哀民生之多艰"、"路漫漫其修远兮,吾将上下而求索"........屈原的爱国忧民之心,让端午文化更加璀璨夺目。中华民族几千年来之所以能够生生不息薪火相传,原动力就在于拥有着以爱国主义为核心的民族精神。本文是一篇文章的节选,文章接下来最有可能讲( )',
  null,
  '{"A":"屈原与端午节的渊源","B":"端午节的其他文化知识","C":"民族精神的核心价值观","D":"如何传承端午节的文化"}'::jsonb,
  '{}'::jsonb,
