(
  '文字-497',
  '文字-497',
  '一些人发现自己在与人交谈时很难一直注视着对方的眼睛,最新的研究发现这不仅仅是因为我们感到尴尬。事实上,大脑难以做到一边思考如何应答,一边还注视着对方。当人们保持眼神接触而又试图使用不熟悉的词语时(研究认为这两种活动使用相同的大脑部位),这种感觉会变得更加强烈。研究人员对26名志愿者做了测试,让他们一边盯着计算机生成的脸,一边玩词语联想游戏。当发生眼神接触时,被试者觉得更难找到词语之间的联系。尽管眼神接触和语言处理过程看似相互独立,人们在谈话时还是经常避开对方的目光。这暗示着两种过程可能会相互干扰。实验发现,当有眼神接触时,被试者需要更长的时间进行思考,但这只发生在词语关联较难时。研究者认为,这种迟疑说明大脑当时正超负荷运转,同时处理太多问题。上述材料主要讲述了:',
  null,
  '{"A":"眼神接触对大脑运转的影响。","B":"眼神接触会损耗大脑的认知资源。","C":"眼神接触和词语联想的关系。","D":"眼神接触的实验研究。"}'::jsonb,
