(
  '文字-498',
  '文字-498',
  '人类大肠里生活着许多微生物,它们每天可以发酵约40g的碳水化合物,产生约13升的气体。但这些气体并不都会从肠通排出,一部分气体会在排出前被再次分解成其他化合物。而剩下的从肠道排出的,就是屁。研究发现男性平均每天放12.7次屁,女性为7.1次。放屁的次数和摄入的纤维含量成正比——纤维含量越高。放屁次数也越多。大多数屁是没有气味的——1/4是我们吸进的氧气和氮气,剩下的主要是二氧化碳和氢气。屁的主要味道来自占屁体积不到1%的氢、挥发性氨基酸、知链脂肪酸等气体。下面对"屁"理解正确的是:',
