  '文字-499',
  '一些同卵双胞胎中的一个拖延,另一个也会拖延。进一步分析发现TH基因与拖延有紧密关系。TH基因是调控多巴胺分泌的小组成员,多巴胺的释放既会让恋人产生怦然心动的感觉,也会让人注意力不集中并且难以控制。多巴胺会使一个人无法一直保持明确的行动意图,因此,当多巴胺含量高的时候,拖延症的行为就会表现出来。TH基因使得某些人生来就比别人多巴胺水平更高,更容易快乐也更容易拖延。下面最适合本文的标题是;',
