  '文字-500',
  '某巿将公开发行股票,共四家公司股票上市。为此,某报就发行股票问题对3000余人进行调查。结果显示:非股民对四家公司股票发行价的评价较温和,一半以上的人因无炒股经验而无从评价。虽然五分之一强的人认为发行价偏高,认为偏低的几乎近于零,但这应视为人之常情---买东西的人多倾向于认为东西贵。老股民认为新股发行价格偏高,因为他们对二级市场的情况熟悉。近年来二级市场股价低迷,相比之下,四新股的发行价就显得高了。从这段话中可以知道:',
