  '每年武器攻击都会夺走三万多美国人的生命,许多入认为限制枪支的持有量能够增加国家安全。但另一部分人声称谋杀、犯罪和大规模枪击事件的发生是因为人们手中没有足够的枪支。他们认为更多的人武装起来将使社会更女全、更和平,因为如果罪犯知道他们周围的人都持有枪支,就不会随便做坏事。但研究发现持枪率最多的州发生武器攻击的几率是持枪率最低的州的6.8倍,而那些拥有枪支的人被谋杀的可能性是没有枪支的人的两倍。下面最适合本文的标题是:',
