(
  '文字-510',
  '文字-510',
  '在大家印象中,肉眼可见的云像棉花糖一样软绵绵、轻飘飘。但真实的云,尤其是云团是有重量的,而且重量超乎大家的想象。根据科罗拉多博尔国家大气研究数据表明,积雨云的重量平均重110万磅,相当于100头大象的重量。既然云那么重,那它究竟是怎么漂浮起来的呢?答案其实和组成云的小水滴有关。我们知道的云是由上亿万个小水滴或者小冰晶组成,这些小水滴以及小冰晶的直径大概约2微米宽,比人类的头发还小。这些小冰晶会受到地球的引力向下坠落,但由于自己的体积、质量实在是太小了,以至于降落的速度非常慢。然而小冰晶在降落的过程中,会受到空气阻力的摩擦而重新蒸发形成水汽,这些水汽又会凝结在微尘周围,重新形成小水滴或者小冰晶。下面对本文内容理解正确的是:',
  null,
  '{"A":"云是由比人类头发还小的小水滴组成的。","B":"大家对云的想象都是错误的。","C":"小水滴受地球引力的影响不断降落。","D":"云的平均重量为110万磅,相当于100头大象还重。"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '逐项对照原文，B项“大家对云的想象都是错误的。”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择B。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
