  '文字-511',
  '文字-511',
  '那些过度自信的人,即使被其他人发现他们表现得其实比自称的水平要糟糕,其社会地位也没有严重下降,因为他们不是直接吹嘘自己,而是用了更微妙的肢体语言——说话声音更大,更坚定,大胆提出自己的观点,点头以强调自己,在人群里展现出更大的存在感。因此,我们可以先假装自信,让别人会用积极的眼光看自己,相信自己有比实际更高的社交水平与任务技能。然后我们就可以利用这种社会反馈来获得真正的自信。下面对本文内容理解正确的是:',
  null,
  '{"A":"人们通常通过说话声音更大,更坚定,点头等来展示自信。","B":"人们往往对那些过度自信的人更加宽容,评价也更高。","C":"当别人认为自己很优秀的时候,我们会真的变得更优秀。","D":"过度自信的人往往实际能力并不如自称的水平。"}'::jsonb,
