  '文字-512',
  '文字-512',
  '核桃是很多人喜欢的一类食物。由于其形状与大脑相似,一些人深信"以形补形"的理论,认为核桃具有"补脑"的功效,长期食用能够起到健脑益智的效果。越来越多的研究显示,适量吃核桃,对健康有益,尤其是对心血管。之前有研究发现,核桃可能是一种有益于肠道和心脏健康的食物。将核桃作为日常饮食的一部分,有助于肠道中某些益生菌的生长,促进肠道健康;而肠道益生菌的变化,能改善心脏健康,降低心脏病风险。近日,还有一项研究显示,与不吃核桃的人相比,经常食用核桃可能会减轻炎症。炎症在心血管疾病的发生、发展中起着重要作用,而炎症的减轻,有助于降低心血管疾病风险。这段文字意在说明:',
  null,
  '{"A":"核桃影响肠道益生菌的种类和数量的变化。","B":"合理日常饮食如何影响人们身体健康。","C":"核桃可能减轻炎症、降低心血管风险。","D":"饮食上的小幅改善对健康大有脾益。"}'::jsonb,
