  '文字-513',
  '文字-513',
  '鲁迅将神话解释为"昔者初民,见天地万物,变异不常,其诸现象,又出于人力所能以上,则自造众说以解释之:凡所解释,今谓之神话。"同时,神话是一类极具生命力的传奇故事,它通过在叙述中心保持高度不变的常量和在边际保持变化来生存。它的恒常性产生了通过艺术或礼仪的再现而被认识的魅力,而它的可变性则产生了探索新的个人化的表现手段的魅力。这就构成了"主题"与"变奏"的关系。不论是作曲家还是听众,都不难领略音乐的魅力。因而,那些不能做丝毫变更的"神圣文本"与神话不可同日而语。材料的核心思想是:',
