  '文字-514',
  '"微电网"是指把分布式能源和它所供能的负荷以及储能等设备连接形成一个微型的完整电网。这种"微型"的电网是从发电、输变电,直到终端用户的完整电力系统,既可以自身形成一个功能齐全的局域性能源网络;也可以通过一个公共连接点与市政电网并网连接;当微电网电源功能不足时可以通过大电网补充缺额,发电量大时可以将多余电量馈送回大电网。必要时,两种模式间可以进行切换。下面对本文内容理解正确的是:',
