  '文字-516',
  '文字-516',
  '资本主义政治经济学以亚当·斯密的《国富论》为代表作,主要强调自由竞争,认为市场有自动调节的功能,政府不应干扰资本的运营,政府的作用只是维护自由竞争的秩序。资本主义的政治经济学在资本主义发展的早期起到了反对封建主义专制的作用,早期的资本主义国家都是依照自由竞争的法则管理经济的。但自由竞争发展到一定时期必然导致周期性的经济危机,执行自由竞争政策最为彻底的美国发生的经济危机最严重。下列说法正确的是( )',
