  '文字-517',
  '文字-517',
  '研究表明,企业高管层中的女性占比越大,企业的效益越好,越富有社会责任感,并能提供更安全、高质量的客户体验。当然,提升高层管理团队的多样性也有道德原因。研究人员发现,在任命女性高管之后,企业在战略思维转变上会出现不同的趋势。首先,研究人员发现,在女性加入高管团队后,企业对变革持更包容开放的态度,且愿意减少风险。基于此,随着高管层扩大女性占比,企业会逐渐从侧重于并购的知识购买战略转变为侧重于内部研发的知识构建战略。最后发现女性在高管团队中融入得越好,对高管层决策的影响就越大。这段文字意在说明:',
  null,
  '{"A":"新增女性高管后企业战略思维的变化。","B":"企业引入女性将会对高管层带来怎样的影响。","C":"企业应该如何增加高管团队的多样性。","D":"女性高管比男性高管更愿意挑战现状。"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '梳理文段的中心句与行文重点后，A项“新增女性高管后企业战略思维的变化。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-主题词。',
