(
  '文字-518',
  '文字-518',
  '电子产品容易受到突然断电的损害。断电可能是短暂的,才十分之一秒,但对于电子产品却可能是破坏性的。为了防止这种情况发生,不间断电源被广泛应用于计算机系统,通讯系统以及其它电子设备。不间断电源把交流电转变成直流电,再对蓄电池充电。这样,在停电时,蓄电池即可以弥补断电的间歇。这段文字主要谈论的是:',
  null,
  '{"A":"断电对电子产品的损害","B":"如何用蓄电池防止断电损害","C":"防止断电损害电子产品的方法","D":"不间断电源的工作原理及功能"}'::jsonb,
