(
  '文字-520',
  '文字-520',
  '为了预防新冠际炎,对居家环境进行酒精消毒成为重点。能有效杀灭细菌或病毒的酒精浓度范围为60-80%,浓度过高的酒精(95%)由于脱水能力太强,会快速地将微生物最表层的蛋白质脱水而凝固,反而会妨碍酒精继续渗透进入微生物的表层,导致微生物内部仍保有活性。浓度75%的酒精效果最好。但洒精对能产生内胞子的细菌无效,对无外套膜的病身效果也有限。下面对本文内容理解正确的是;',
  null,
  '{"A":"微生物表层的蛋白质可以保护微生物内部病毒的活性。","B":"即使是75%的酒精,也无法降低无外套膜的病毒活性。","C":"浓度太高的酒精反而会增加病毒活性。","D":"酒精消毒的原理是消灭细菌表层的蛋白质。"}'::jsonb,
