(
  '文字-521',
  '文字-521',
  '判断力,是将个人素质和相关知识、经验结合起来形成观点并做出决定的能力,也是"横范领导力的核心"。在缺乏明确相关数据、没有显而易见的解决方案的情况下,领导者要做出好的选择,只能依据判断力。具备优秀判断力的领导者往往擅长倾听和阅读——能够听出其他人真正要表达的意思,因此能够察觉别人看不见的规律。这些人拥有广泛的经验和人脉,能够发现其他人忽略的共通之处——即使他们自己缺乏某方面知识,也能找到具备相应能力的人,依靠其判断行事。他们能够意识到自己的情感因素和认知偏误,不让这些因素影响判新。他们擅长寻找多个选项。他们始终脚踏实地,在做选择时不会忽略其可行性。优秀的判新力是领导者做出正确选择的关键。这段文字意在说明',
  null,
  '{"A":"领导者与一般人不同,他们擅长选择多个选项。","B":"领导者做出好的选择的方法。","C":"具备优秀判断力的领导者的特点。","D":"判断力对于领导者做出选择的重要性。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '梳理文段的中心句与行文重点后，C项“具备优秀判断力的领导者的特点。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择C。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-因果关系。',
