  '所有经典的、值得阅读的小说不仅内容需要可读性,更重在将生活与艺术相融合,把时代与人物命运相结合。诸如《悲惨世界》、《简爱》等文学著作之所以享誉全球,就是因为有着_____的故事情节及超越现实的思想高度。填入横线处最恰当的词语是:',
