(
  '文字-527',
  '文字-527',
  '在我们从计划经济向社会主义市场经济过渡、企业取得越来越多的自主权时,作为社会及组织的最小单元——员工个人也要求拥有照顾他们个人愿望和爱好,考虑如何最好地发挥他们的特长的权利,应当容易理解了。最能准确复述这段短文的意思的是:',
