  '文字-528',
  '文字-528',
  '对于教育方式,我们无法简单地给予好或不好的评价,因为每个孩子的成长背景、兴趣禀赋都不尽相同,适合的教育方式也不应。"顺木之天,以致其性",孩子的成长和树木一样有着自身规律,如果不顾实际一味加压,让孩子完成超越年龄的事情,那么我们一点一点加之于孩子的,可能不是锦绣点缀的花朵而是压垮骆驼的稻草。',
