(
  '文字-533',
  '文字-533',
  '随着社会的发展与进步,证据的种类也在不断发生变化,以往闻所未闻的电子邮件。微信等,在信息化时代,经过必要的手候或程序后,也已跻身证据"家族",发挥着重要的作用。不过,由于法律最终调整的是人与人之间的关系,无论时势如何变迁,相关的证人证言对于几乎所有的案件来说,都是必不可少的。因此证人出庭作证就成为庭审中一个重要的环节。这段文字接下来最可能讲的是:',
  null,
  '{"A":"庭审需证人证言的原因","B":"证人可出庭作证的意义","C":"信息化时代证据的种类","D":"法律庭审的内容和环节"}'::jsonb,
