(
  '文字-535',
  '文字-535',
  '新科技的应用为大多数人带来便利的同时,也对那些未能跟上科技潮流的人带来负面影响。以"银发一族"为代表的群体,常常在生活中体会到这种无奈:不会用自助机。只能排队办业务:不会手机叫车,只能路边苦等:不会使用移动支付,导致在购物时"步履维艰"。科技应用必然离不开利益导向,但如果企业应用科技时秉持"利益为先"的原则,只抓住"科技易感"的年轻人。不照顾特殊群体,就违背了人人平等的价值理念,科技进步也可能会产生与初衷相反的异化。这段文字意在说明',
  null,
  '{"A":"新科技的应用要坚持以人为本的价值导向","B":"科技进步也应当为\"银发一族\"提供便利","C":"企业创新应根据不同群体特点满足其需求","D":"科技应用要兼顾不能跟上潮流的特殊群体"}'::jsonb,
