(
  '文字-536',
  '文字-536',
  '在国画中,烟林寒树,雪夜归舟,深山萧寺,渔庄清夏..这些习见的画题,都在幽冷中透出宁静。这里没有鼓荡和聒噪,没有激烈的冲突,即使像范宽《溪山行旅图》中的飞瀑,也在空寂的氛围中失去了如雷的喧器。如北宋画家王晋卿的传世名作《渔村小雪图》,画山间晴雪之状,意境清幽,气氛静寂,西中渔村山体均以薄雪轻施,寒林点缀于石间崖隙江水荡漾,与远山相应,"如诗如画,诗画合一"。画中的一切都在清晖中浮动,真是清幽静谧之极。最适合做上文标题的是:',
  null,
  '{"A":"国画的独特技艺","B":"给画的传统意象","C":"中国画中的宁静","D":"诗画合一的国面"}'::jsonb,
