(
  '文字-537',
  '文字-537',
  '随着市场经济的逐渐建立,国人对大学办学自主权的关注点只在于大学所受的外部控制和影响,认为只要政府放权了,大学与市场"联姻"了,大学自然就有了自主性。这样可以一劳永逸地改变大学缺乏办学自主权的状况,大学自主办学问题也可迎刃而解。这种观点的错误之处在于,它人为地切割掉了探究大学自主性的内部向度,导致在屡次的改革实践中,大学内在的自主性并未得到应有的增强和提升。这段文字接下来最可能说的是',
