  '文字-538',
  '文字-538',
  '套路贷是指一些违法犯罪团伙利用部分人需要资金又无法从正规渠道获取的急切心理,打着借贷公司的幌子钻法律空子,通过翻倍催讨债务,将原本少量的债务通过反复平帐等手段,最终变成巨额债务。根据上述定义,下列属于套路贷的是;',
  null,
  '{"A":"吴某在理财软件平台上贷了4万元,后因还不起贷款,家长和老师、同学开始不断收到催收团队催债,无奈之下家人替他还清了共计4万多的本金和利息","B":"周某为买最新的苹果手机向网上的借贷机构借钱,在网站上填写了银行卡账户信息和动态验证码后,结果不但没借到钱反而帐号密码被窃取,损失惨重","C":"刘某担心自己因为之前有逾期行为而贷不到钱,于是找到声称可以\"修改征信\"的中介机构、交了五千元手续费,结果中介收了包装费后就再也联系不上了","D":"王某通过民间借贷的方式向某放贷机构借了少量钱款,在还款期临近时被各种阻挠还款。期限一过却被野蛮催债,依据\"违约协议\"要求交出抵押的房产"}'::jsonb,
