  '文字-539',
  '文字-539',
  '生物放大现象是指在生态系统的同一食物链上,由于高营养级生物以低营养级生物为食物,某种元素或难分解化合物在机体中的浓度随着营养级的提高而逐步增大的现象。根据上述定义,以下属于生物放大的是:',
  null,
  '{"A":"某池塘的污染物铜通过鱼类的呼吸进入其体内,然后根据血液循环分散至身体的各个部位,被鱼类的多种组织和器官吸收后浓度越来越高","B":"由于核武器试验导致放射性散落物在全球范围内的增长,人体内锶、铯、铈等多种放射性同位素的浓度要远远高于其他生物体中的浓度","C":"为了加快海参的生长速度,人工养殖时会在海水中喷洒含有激素的养料,随着海参的生长发育,激素的浓度不断增加","D":"以蚱蜢、蝗虫、蟋蟀、蚂蚁等昆虫为主要食物的小鹧鸪体内含有的一种有机氯杀虫剂(DDT)浓度比其周围各种草本植物的浓度要高出50多万倍"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '梳理文段的中心句与行文重点后，D项“以蚱蜢、蝗虫、蟋蟀、蚂蚁等昆虫为主要食物的小鹧鸪体内含有的一种有机氯杀虫剂(DDT)浓度比其周围各种草本植物的浓度要高出50多万倍”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择D。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-主题词。',
