(
  '文字-540',
  '文字-540',
  '表演型人格障碍是一种以过分感情用事或夸张言行以吸引他人注意为主要特点的人格障碍。具有表演型人格障碍的人的表现有:十分关注自己的外表,会以自我表演,过分的做作和夸张的行为引入注意,暗示性和依赖性特别强,情绪外露,喜怒哀乐皆形于色,易发脾气,喜欢别人同情和怜悯,思维肤浅,不习惯于逻辑思维,言语举止和行为显得天真幼稚。根据上述定义,以下不属于表演型人格障碍的是:',
  null,
  '{"A":"玲玲从小被娇生惯养,非常喜欢在各种热闹场合耍小聪明来博得客人的夸奖,参加工作后,虽然表现较好,但总是喜欢标榜自己。","B":"小文正在上小学,平时爱穿鲜艳的衣服,模仿模特走路,如果别人说了令她不高兴的话,她就跟别人争吵,有时候父母批评她几句,她可以一连几天都不跟父母说话","C":"小明觉得自己手有问题,结果检查未发现任何疾病,他大吵大闹强烈要求住院,而且为了证明自己的手有问题,把手举了一个晚上,即使累得发抖也没放下","D":"资深化妆品公司的培训经理,思维敏捷,说话流畅动听,仅凭一张七星级酒店的图片,就能编出一大套奢华的背景,狗血的爱情故事"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '梳理文段的中心句与行文重点后，D项“资深化妆品公司的培训经理,思维敏捷,说话流畅动听,仅凭一张七星级酒店的图片,就能编出一大套奢华的背景,狗血的爱情故事”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择D。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-主题词。',
