(
  '文字-541',
  '文字-541',
  '强迫性重复最早由弗洛伊德提出,指的是一个人固执地、不断地重复某些似乎毫无意义的活动,或反复重温某些痛苦的经历和体验。根据上述定义,下列选项不属于强迫性重复的是:',
  null,
  '{"A":"小姚童年时有个酒鬼父亲,长大后不自觉找了个家暴男朋友","B":"刘磊受不了母亲什么事都要控制,长大后要了个爱管的妻子","C":"有的小朋友会不厌其烦地一再要求大人同他们一起玩某游戏","D":"牧师幼年缺乏母爱,长大后便对自己的孩子照顾得无微不至"}'::jsonb,
