(
  '文字-542',
  '文字-542',
  '成功的领导者从根本上来说应该具有影响他人的能力,而信任则是这种能力的基础。因此,管理者必须努力培养与其共事的每个人对他的信任感,同时,在一个真正的团队中,除了共同的目标和价值观念,成员们也重视自己的成员身份,并且努力不让同事失望。而聪明的管理者能够建立并利用这些强大的关系来塑造成员们的行为。除此之外,每个团队都需要依赖外部人员和团队的支持与合作。有效的团队领导者会积极主动地建立和维护这些关系网络。强大的、有效的领导者能够在日常事务中把这三个因素贯穿其中,有效发挥领导作用和领导能力。根据本文内容,下面推断正确的是:',
  null,
  '{"A":"领导者很难影响那些他们没有取得信任的员工。","B":"能够建立一个团队并管理它就是成功的管理者。","C":"提高管理能力的三个关键因素是需要各自独立执行的任务。","D":"领导者应该避免当下就与团队实现未来目标所需要的人员建立良好关系。"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '逐项对照原文，A项“领导者很难影响那些他们没有取得信任的员工。”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择A。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
  '提高',
  '文字推理',
  '细节判断题',
  '["信息核对-定位原文"]'::jsonb,
  '北森言语理解',
  null,
  563,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-543',
  '文字-543',
  '过去几十年,将绩效指标与战略捆绑在一起已经成为商界公认的最佳实践。如果说战略是构建组织的蓝图,那么指标就是混凝土、木材、石膏板和砖块,但这种架构中隐藏着陷阱:公司很可能忽视战略,反而严密关注本应代表战略的指标。在商业中,我们通常会期望指标能将一些无形的深层目标具象化,但几乎总是事与愿违。事实证明,用指标替代战略的心理倾向,即所谓的替代倾向相当普遍,组织战略因此受到数字的挟持,公司价值遭到破坏。如果指标和战略不一致,替代倾向的危害性会更大,而且不一致的地方越多,潜在的危害就越大。而且如果不能及时采取行动进行防范,管理者可能迟早会亲眼看到自己的战略走向失败。下面对本文内容理解正确的是:',
  null,
  '{"A":"以牺牲战略为代价来追求指标会给企业带来损失。","B":"只要指标与战略保持一致就不会产生替代倾向。","C":"因为战略太过抽象所以它对于员工来说是没有效用的。","D":"在商业中出现的替代倾向是无法被人为控制的。"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '梳理文段的中心句与行文重点后，A项“以牺牲战略为代价来追求指标会给企业带来损失。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-因果关系。',
