(
  '文字-545',
  '文字-545',
  '在快节奏的生活里,去外面就餐已经成为很多人的"家常便饭"。之前有研究发现,相比于在家烹饪的饭菜,外出就餐时的饭菜,尤其是快餐店的饭菜,其饮食质量(包括食品安全、健康程度等)通常较低;而且脂肪和钠含量较高,水果、蔬菜、全谷物占比少,膳食纤维和抗氧化剂等营养素含量较低。近日,一项研究结果显示,经常外出就餐,可能与肥胖、糖尿病和其他慢性疾病风险增加有关,进而增加心血管疾病、癌症以及全因死亡风险。而在家烹调不仅可增加生活乐趣,还有助于实践少盐少油的清淡口味饮食。同时还可促进情感沟通,让家长了解孩子对食物、味道的喜恶,进而调整烹饪方法或及时纠正和引导儿童健康的饮食习惯。这段文字意在说明:',
  null,
  '{"A":"只有在家就餐才能满足人们对健康的需要。","B":"人们多回家吃饭才能同时享受食物和亲情。","C":"避免外出就餐是降低患心血管疾病、癌症的根本方法。","D":"经常外出就餐可能是不健康的习惯,应该鼓励尽量在家就餐。"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '梳理文段的中心句与行文重点后，D项“经常外出就餐可能是不健康的习惯,应该鼓励尽量在家就餐。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择D。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-递进关系。',
