(
  '文字-546',
  '文字-546',
  '不管在学校还是在社会,人都要做到敢作敢为,( ),敢于为自己的过错承担责任。填入括号内最恰当的词语是:',
  null,
  '{"A":"聊以塞责","B":"非异人任","C":"罪责难逃","D":"责有所归"}'::jsonb,
  '{}'::jsonb,
  4,
  'D',
  '根据上下文的逻辑关系、语义侧重和搭配习惯，D项“责有所归”代入后最通顺、准确，因此选择D。',
  '先判断上下文逻辑关系，再比较词义、感情色彩、程度和固定搭配。 本题重点：词语辨析-词义。',
  '入门',
  '文字推理',
  '逻辑填空',
  '["词语辨析-词义"]'::jsonb,
  '北森言语理解',
  null,
  568,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-547',
  '文字-547',
  '每个人都同时具有"长期择偶偏好"和"短期择偶偏好"。但由于男性在追求多个性伴侣的过程中希望这样的伴侣关系是短期的并避免承诺,因此短期配偶动机会激发男性"花心"的思维范式。但女性则正好相反:女性在追求唯一伴侣的过程中希望伴侣关系是长期的、忠诚的,因此长期配偶动机会激发女性"忠诚"的思维范式。不同的思维范式会影响男性或女性对消费产品的选择。研究发现"花心"的男人在消费时选择会更加多样化,而"忠诚"女性的选择则更少多样化。下面对本文内容理解正确的是:',
  null,
  '{"A":"男性在消费选择时更加多样化,这些多样的选择会诱发男性的短期配偶动机。","B":"男性拥有短期配偶动机,女性拥有长期配偶动机,男性比女性更\"花心\"。","C":"男性渴望拥有多个性伴侣,关系短暂,不用承诺,因此诱发短期配偶动机,激发\"花心\"。","D":"男性拥有\"花心\"和\"忠诚\"两种思维范式,但在消费时只会激发\"花心\"范式。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '梳理文段的中心句与行文重点后，C项“男性渴望拥有多个性伴侣,关系短暂,不用承诺,因此诱发短期配偶动机,激发"花心"。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择C。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：关联词语-转折关系。',
  '提高',
  '文字推理',
  '中心理解题',
  '["关联词语-转折关系"]'::jsonb,
  '北森言语理解',
  null,
  571,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-548',
  '文字-548',
  '全球化进程的加快和贸易战的发生让人们处于一种自我不安全的状态中,即人们的自我安全感受到了威胁。研究发现,自我安全感受到威胁的人更容易依恋可以提供常规生活和构建个人身份的家乡,以此寻求自我安全感的恢复,从而增加了对家乡品牌的偏好。研究还发现,当展现在草地树木的大自然情景中时,自我安全感受到威胁的人能够通过对这一情景的依恋来对抗自我安全感威胁,不再需要寻求家乡依恋来缓解自我安全感威胁,从而使其在对家乡品牌和非家乡品牌的偏好上不再呈现出差异。下面对本文内容理解正确的是:',
  null,
  '{"A":"之所以人们的自我安全感受到了威胁,是因为受到了全球化进程加快的影响。","B":"只有自我安全感受到了威胁的人才会格外依恋家乡,偏爱家乡品牌。","C":"大自然情境的展现能够调节自我安全感威胁与家乡品牌偏好之间的关系。","D":"对家乡的依恋比对草地树木的大自然的依恋更能够缓解本体安全感威胁。"}'::jsonb,
  '{}'::jsonb,
  4,
  'C',
  '梳理文段的中心句与行文重点后，C项“大自然情境的展现能够调节自我安全感威胁与家乡品牌偏好之间的关系。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择C。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-对策词。',
  '提高',
  '文字推理',
  '中心理解题',
  '["做题辅助-对策词"]'::jsonb,
  '北森言语理解',
  null,
  572,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-549',
  '文字-549',
  '在这个社会中,每个人看起来都很忙,人们在这忙碌的世界中手脚不停的生活。就好像一直在旅途中,乘着汽车匆匆忙忙的走过,没有闲暇去欣赏沿途的风景。于是,这原本美丽的世界在忙碌的我们眼中变得空无一物,只剩下匆忙和忧愁。这段文字的主要内容是:',
  null,
  '{"A":"人们为了工作无暇顾及周围的世界。","B":"美丽的世界只是与忙碌的人们无关的风景。","C":"人们应当去欣赏这个世界。","D":"社会中的人们更加关注自己的生活。"}'::jsonb,
  '{}'::jsonb,
