(
  '文字-552',
  '文字-552',
  '有研究发现,对男性参与者而言,在由男性作为观察员或者没有观察员的情况下,男性给乞丐捐献的金钱相差无几。而在由女性作为观察员时,男生捐献的金钱则明显上升。相比之下,女性则没有出现这种情况,无论身边是男性还是女性,都激不起她们更多的捐献欲望。因此,在异性在场的情况下,男性更愿意做个好人。这是由于女性自身可生育的时间较男性来得短,抚养后代的代价也比男性要来得高,因此女性在挑选自己伴侣的时候更加谨慎。为了获取女性的芳心,男性就需要拼命展现自己关爱他人的一面。下面对本文内容理解正确的是:',
  null,
