  '文字-553',
  '制度机制的建立,都是从粗略开始,经由长时间的执行累积实务经验,不断改善优化,逐渐提升细致度及增加涵盖度。这是精益求精、不断提升制度效益的必要做法。但是长久以往,制度机制往往变成一个庞大、复杂的系统。然而组织是一群不同经验、不同能力与层级的人所组成。一个庞杂的系统难以让组织的一般人员易于理解并掌握,更别说融会贯通。假如公司的制度十分复杂,落地时会更容易陷入全面的低效率及僵硬固化。下面最适合本文的标题是:',
