(
  '文字-557',
  '文字-557',
  'PC互联网时代,传统电商平台掌握着中心化的搜索流量入口,商品信息的传播依靠传统的电商广告投放,在此阶段流量分发的顶级商业模式是"人找货"。但在移动互联网时代,搜索引擎日渐式微,每一个在线用户均成为了一个即时信息分发节点,以微信、微博为代表的移动社交应用占据潜在消费者主要的在线时长,在线社交关系网络成为消费者获取、传播商品信息流的重要通道。此时流量分发模式变为"去中心化"的社交关系链中的推荐,是"货找人"。下面对本文内容理解正确的是:',
  null,
