  '文字-559',
  '文字-559',
  '将下列句子组成一段逻辑连贯、语言流畅的文字,排列顺序最合理的是( )。(1)当义务教育优质资源供给充足并在定区域内均衡分布,家门口的学校间的差别逐步消解,学区房的教育资源保障属性和投资属性才能逐级下降,学区房的价格自然不会成为问题(2)不过,这条路也最难走(3)同样是家门口的学校,教育质量却存在明显差别,让孩子享受更优质的教育资源,不少家长以房择校的动力正来源于此(4)也正因为其实现周期是如此之长,克服短期的政绩冲动、保持政策目标的致性就显得尤为重要(5)推进教育资源均衡分布是一项长线工程,需要各地政府切实持续加大义务教育的投入力度,并在辖区内进行均衡配置,尤其是在发展中处于弱势或不利地位的区域或学校(6)学区房问题,根子在于教育资源的不足与分布不均',
