  '下列没有语病的句子是: ( )',
  null,
  '{"A":"古往今来,青青翠竹吸引了无数诗人和画家竹画成为我国诗画的传统题材,它象征了中华民族坚定顽强、不卑不亢的气概。","B":"三年当中,这个县的粮食产量,以平均每年递增百分之二十的速度大步向前发展。","C":"作为党的负责人之一的方志敏,从他身上,竟搜不出一个铜板来。这就是一个共产党员的\"清贫\"。","D":"古老的中国气功已经运用于竞技体育,它不仅可以有效地治疗运动员的新旧伤病,而且还可以调节赛前运动员经常出现的紧张情绪,迅速消除他们的疲劳。"}'::jsonb,
