  '文字-575',
  '将下列句子组成一段逻辑连贯、语言流畅的文字,排列顺序最合理的是( )。(1)如果说金钱豹的离奇出逃还只是动物园管理上的"意外",那么,相关方面在后续信息发布上的种种奇葩操作,被称为"人祸"毫不为过(2)涉事野生动物世界,不但在金钱豹出逃后未能第一时间向社会披露相关信息,哪怕在当地村民发现豹子后,依然冠冕堂皇地"辟谣",这背后的瞒报态度令人愤怒(3)被舆论围观数天之久的三只金钱豹"出逃记",仍未画上句号,目前,其中两只金钱豹已被捕获,还有一只在逃(4)但可能没有哪一次像这次这样"一波三折",引发如此大的争议(5)所幸,就目前来看,外逃的金钱豹并未带来直接的公共伤害,但由一而再地瞒报所反映出的对于公共安全,对于公众知情权的颟顸态度,可谓"伤害性不大,侮辱性极强"(6)动物园出现动物"外逃"的事,这些年并非是第一次出现',
