  '某市统计局经调查发现,该市居民平均用电量为每家庭每月300度电。该市实行阶梯电价,第一档为每家庭每月200度电,第二档为每家庭每月400度电,政府考虑到居民的实际情况将第一档电价降低10%,第二档电价提高20%。政府修改政策最有可能是基于下列选项中( )的考虑。',
