  '开展严肃认真的党内政治生活,是我们觉的优良传统和政治优势。从80年前的古田会议首次提出*使党员的思想和党内的生活都政治化,科学化,到70多年前的环安整风建立党内政治生活的制度基础,再到改革开放之初制定《关于党内政治生活的著干准则》,正是在__和__中,一代代共产党人在党内政治生活的大熔炉中_,推动我们党历经98年风雨__依然朝气蓬勃、意气风发。依次烦入画横线部分最恰当的一项是( )',
