  '文字-584',
  '1很久以前回了一次家,没有像想象中小野马脱离缰绳的狂喜与暴躁,流浪中日里夜里盼着的第一次回家竟是和亲人的诀别。2第一次感到生命的脆弱与无助,死亡判决的时刻,人类只有忧伤。3我跟着长长的白衣队伍踱着步子送她最后一程。4离家的孩子不知道下次回家是何期。5临走的时候,我贪婪地注视着大地上的每一个角落,想踏遍石板路的每一块青砖。6最后她一人沉沉地睡在了山坡,那里开满了蒲公英,也开满无人问津的苍凉,每一粒种子都在风中传递着亘古不变的哀愁。将以上6个句子从新排序,语序最合理的是( )',
