(
  '文字-585',
  '文字-585',
  '时代的场景变化太大了,要让年轻一代真正记住历史,不能停留在概念式的说教上。真正完整有效的历史教育,是应当融汇在生活之中的。它不应当仅仅是在纪念馆里才能看到,只是在书本中才能读到,它还应当以丰富、适当的形式渗透到我们居住的街区和生活的种种场景之中,这样才能在耳濡目染中化为整个民族的"集体记忆"。对这段话的准确概括是:',
  null,
  '{"A":"历史教育的重要意义","B":"历史教育的形式应当生活化","C":"历史教育随时随地都可以获得","D":"历史存在于民族的集中记忆中"}'::jsonb,
