  '文字-586',
  '文字-586',
  '得不到的未必是最好的。为什么总是有人说得不到所以才觉得分外地好,那不过是心理原因。潜意识里有自卑情结,喜欢用自己所仰慕的东西来平复自己的缺陷。比如没有钱的去追求金钱的载体,长得丑的去追求漂亮的依附体......这段话主要说明:( )',
