  '马克思主义执政党的最大危险就是脱离群众。群众是政党的执政基础,政党是群众的代表。我们党要长期执政,无论何时何地,都必须始终保持党同人民群众的血肉联系,只有这样,才能不断筑牢党的长期执政基础,党领导下的社会主义建设就能蒸蒸日上,无往而不胜。这段话意在说明:( )',
