(
  '文字-595',
  '文字-595',
  '"儿行千里母担忧",其主要原因是"母子连心"。但母子连心并不是简单的文学比喻,也不只是单纯母爱的体现和延伸,更是客观的生理和心理现象。研究发现3个月大的婴儿能够和他们的母亲实现心跳同步。研究人员让40对母婴面对面相处,并在每个人的心脏部位配备了检测心跳的电极,发现随着母亲充满爱意的面容或是欢乐的笑声的出现,母亲与孩子的心跳很快就"步调一致"了。另外一项研究表明:胎儿的细胞能够移动到他们母亲的大脑中。在怀孕期间,母亲和胎儿常常交换细胞,这些细胞似乎能在体内存活数年。男性胎儿在母亲怀孕期间留下的DNA,会终其一生留在母亲大脑中,帮助她们避免患上神经性疾病。下面最适合本文的标题是( )',
  null,
  '{"A":"\"母子连心\"如何影响母婴关系","B":"母爱的表达——\"母子连心\"","C":"如何解读\"母子连心\"","D":"大脑细胞如何影响\"母子连心\""}'::jsonb,
