(
  '文字-597',
  '文字-597',
  '在工作场所安全条例中表明,管理者应考虑到所有人的安全,包括各种员工和那些未参与工作但会受到影响的人员。同时,对员工而言,通过各种方式来保护自己和他人的安全也是一种责任和义务。如果上述为真,下面哪一项肯定是正确的?',
  null,
  '{"A":"如果由于员工的疏忽造成工作场所的游客受伤,那么员工可能被追究全责","B":"管理者应该为工作场所的游客的安全负责","C":"如果由于员工的疏忽造成工作场所的游客受伤,那么管理者可能被追究全责","D":"员工应该为工作场所的游客的安全负责"}'::jsonb,
