  'B',
  '梳理文段的中心句与行文重点后，B项“市场份额竞争是长久的竞争,看待市场份额竞争要目光长远,不能只看当前的领先态势”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择B。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-主题词。',
