  '文字-599',
  '文字-599',
  '产品经理是产品设计与生产中的核心管理人员,虽不一定要掌握最核心的尖端技术,但优秀的产品经理要能在产品设计中灵活运用基本原理。目前,我国各院校中并没有针对产品经理的专业培训和正式教材,而公司中的产品经理有着各种专业背景而良莠不齐。根据上述内容,下列说法正确的是:',
