(
  '文字-600',
  '文字-600',
  '基于互联网的电商,买卖行为在几分钟内完成,但网络却无法完成配送,显然,电商爆发式增长的配送压力全部转移到了物流链条上。更为严重的是,社会上对物流体系的认识仍然"参差不齐",配送企业还呈现"小、散、差"等特点,传统物流企业短时间很难适应电商带来的冲击,尽管有人已经认识到其带来的机遇。这段文字意在说明:',
  null,
