(
  '文字-601',
  '文字-601',
  '在一天八小时的工作时间里,真正有效的工作时间平均约六个小时左右。如果一个人工作不太用心,则很可能一天的有效工作时间只有四小时;但如果另一个人特别努力,绝大部分心思都投注在工作上,即便下班时间,脑子里还不断思考工作上的事情,产生新的创意,思索问题的解决方案等,同样一天下来,可能可以积累相当于十二个小时的工作经验,长期如此,则两个人同样工作十年之后,前者可能只积累相当于六七年的工作经验,但后者却已经拥有相当于二十年的工作经验。上面一段文字的主旨是:',
