(
  '文字-603',
  '文字-603',
  '在这个时代,许多人希望通过写作来让自己的物质生活更好,同时还想创作出一些优秀的影视剧,这些都是很好的愿望。然而我的小说在开始构思的时候我就知道不可能改编成电视剧。这些有关于民选,有关于沉默权的小说是不可能被改编的,至少凭我的智商能够判断这一点。这句话的主旨是:',
  null,
  '{"A":"小说改编的影视剧一般会更加优秀。","B":"如果想把自己的小说改编为电视剧,就不能涉及有关民选和沉默权的内容。","C":"作者的大部分小说都不能改编为电视剧。","D":"想要通过写作来改变生活的愿望是很好的。"}'::jsonb,
