),
(
  '文字-604',
  '文字-604',
  '中国邮政日前宣布开放全国5000个自提网点,任何一家快递公司发货,均可享受此服务。自提网点包括现有邮政自有网点和"无人值守"的智能快递柜。看似简单的自提系统开放,背后却是智能快递的大市场。智能快递已成为当前政府驱动快递满足消费和商业需求的重要手段。快递员将快递包裹送到小区的智能快递柜中,给收件人发送取件短信。收件人经过手机查询——输入密码——开门取件,便可将一个快递包裹从智能快递柜中取出。智能快递代表着未来中国快递业的发展方向,即通过引入信息化、大数据等现代化手段,融合预测等方式,以便捷的智能设施和手段替代现代高密度、高成本、高人力的快递工作,达到服务消费者的目的。关于本文内容,下面理解正确的是( )',
  null,
  '{"A":"中国邮政开放的自提网点均设置为无人值守的自提系统。","B":"智能快递是为了配合政府促进消费和商业需求提出的手段。","C":"智能快递必须要有现代化的技术支持才能实现。","D":"对于快递员来说,只需要将快递放入智能快递柜就已经完成了送件。"}'::jsonb,
