  '下面句子没有语病的是( )',
  null,
  '{"A":"政府刚刚颁布了一份禁令关于禁止高校论文造假。","B":"自从我国成功发射载人航空,我国的航空航天事业有了巨大的进步。","C":"这部电影中\"地下党\"被定义为一个个鲜明的群体,人们对他们有了更深入的了解。","D":"经过昨天的合作,使大家更加团结。"}'::jsonb,
