(
  '文字-606',
  '文字-606',
  '人们为什么喜欢八卦呢?八卦并非流行文化的产物,古已有之。研究者指出八卦和小道消息是维系群体内交流的工具。人类的祖先以部落的形式存在,在残酷的环境中,保证生存和发展的手段之一就是掌握同伴和敌人的信息。因此现代人类差不多与生俱来带着八卦基因。聊八卦能拉近人际距离。聊聊八卦,分享消息,说明大家在同一个"圈子"里,促使大家成为朋友。其次,八卦和巧克力一样,可以刺激人脑分泌内啡肽,给人们带来快感,还不用担心发胖!此外,聊八卦可以令八卦炒作者短时间内迅速成为众人关注的焦点,能满足炒作者的虚荣心,因为八卦消息通常具有轰动效应和吸引眼球的效果。下面哪个词能够代替"轰动",而且保持文章的意义不变?( )',
  null,
  '{"A":"震荡","B":"震撼","C":"颤动","D":"惊动"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '逐项对照原文，B项“震撼”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择B。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
