  636,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-607',
  '文字-607',
  '1947年某一日,一位行人在靠近好莱坞的一个空地上发现了"黑色大丽花"的尸体,她的裸体被人残忍地砍成两段,并有严重殴打和性虐待的痕迹。关于她死状的细节,有着数种令人不寒而栗的传闻。奇怪的是,当这起谋杀案在新闻中被披露之后,许多人去警察局自首,承认是他们杀了"黑色大丽花"。过了好几年的时间,警察依然一无所获,所以这一"摧花狂人"已经成为了与"开膛手杰克"同样的名人。她是一名生活在芝加哥的潦倒的女性,期望走向影视之路但一直未能成功,倒是这个案件将她的名气推上了顶峰。美国导演还将这一案件拍成了电影,并以当代人的视角对这一案件进行了解构并给予案件一个合理的结局。对上面的文字理解正确的一项是:',
  null,
  '{"A":"\"黑色大丽花\"的案件是一个团体谋杀案。","B":"案件发生之后,\"黑色大丽花\"变成了一个影视名人。","C":"电影中案件的结局是完全虚构的。","D":"如果这个案件放在当代,就能够解决。"}'::jsonb,
  '{}'::jsonb,
