(
  '文字-609',
  '文字-609',
  '6月7日,国家航天局发布我国首次火星探测天问一号任务着陆区域高分影像图。图像中天问一号着陆平台、祝融号火星车及周边区域情况清晰可见。影像图由天问一号环绕器高分辨率相机,于6月2日18时拍摄。图像右上角有两处明显亮斑,靠上的亮斑由两个亮点组成,较大亮点为天问一号着陆平台,较小亮点为祝融号火星车。以着陆平台亮点为中心,周围区域颜色较暗,据分析,可能是降落过程中受到发动机羽流影响造成。着陆平台南北方向,存在对称的喷射状亮条纹,可能是着陆后着陆平台钝化时吹除了较细的尘埃形成。图像中部亮斑为降落火星过程中抛离的背罩及降落伞组合体,其中背罩为圆形亮点,降落伞为长条状亮点。图像左下方向,存在另外一处明显的亮斑,为降落过程中抛离的防热大底。下列选项中适合用作这段文字题目的是( )。',
