  '文字-616',
  '文字-616',
  '作为一家上座率很高的餐厅,忆隆大饭店计划将餐厅内的部分标准餐桌椅置换成高桌凳。饭店在开张之际已经充分利用了所有空间布置餐桌,即使置换成新的高貞凳也并不能增加饭店可接待的人数,然而饭店经理预期这项改造仍会为饭店带来利润的增加,并且也不打算在菜式、价位以及营业时间上做出任何改变。以下哪项,最能解释饭店经理会有这种期望?',
