(
  '文字-617',
  '文字-617',
  '随着工业向高加工化发展,技术已成为资源结构中最重要的因素。技术的不断进步与革新,使得一种技术或产业的生命周期缩短。传统产业不断让位给新兴产业。适应这种产业结构迅速变化的形势,要求对现有劳动力不断进行职业上的再培训,以适应新兴产业和新技术发展的需要。因此,在就业岗位中,白领工人越来越占有重要地位,蓝领工人的重要性日益缩小。这段话主要支持了这样一个论点,即:',
