  '据调查,市场上有60个品牌的签字笔,占据笔类文具销售额的一半以上。与其他笔类文具相比,签字笔的性能更好,但是价钱也更高。不过,很多人还是愿意为此付出更高的价钱。如果上述陈述是正确的,下面哪项也一定是正确的?',
