  '{"A":"没有任何一个签字笔品牌的销售额特别突出","B":"在市场上,签字笔的品牌数目比其他任何笔类文具的都多","C":"按支数计算的话,签字笔的销售量比其他笔类都要大","D":"花费在高性能的笔类上的钱要比花费在普通笔类上面的多"}'::jsonb,
