  '文字-623',
  '文字-623',
  '我国现有酸性沉降(酸雨)监测网的监测点基本上都在城区和城郊,位于农村的监测点较少。由于我国城区和农村空气污染物浓度和降水化学组成相差很大,现有降水化学和大气化学数据基本上只能代表城区和郊区而不能代表广大农村,因而缺乏区域代表性。因此应根据各地区自然环境、工业交通和人口分布等状况科学布设监测网点以便得到具有区域代表性的降水化学参数。对这段文字主旨概括最准确的一项是( )。',
