  '{"A":"我国酸雨监测网的监测点基本上都在城区和城郊","B":"我国酸雨监测点得出数据没有代表性","C":"科学布设降水化学监测网点,提高数据的区域代表性","D":"我国需要增加农村的酸雨监测点数量,提高农村数据的代表性"}'::jsonb,
