(
  '文字-628',
  '文字-628',
  '好钢要用在刀刃上。"应检尽检、愿检尽检",是早发现、早报告、早隔离、早治疗的重要抓手,防止出现拥挤,防止等待时间过长,区分轻重缓急显得尤为紧迫和必要。据报道,排队申请核酸检测的,不乏图个心安的低风险人群,也有公司组织员工例行检测。早检测早过关的心情可以理解,但是从大局出发,核酸检测这一防疫利器,还是应该先紧着更需要的人用。比如新发地等出现疫情的市场相关人员、各农贸市场工作人员,维持城市日常运转的餐饮、食堂、物流、外卖等从业人员,还有生活在中高风险区域的市民以及考生、病号、抗疫线工作者等等。疾控部门已经多次呼吁,没有高风险区域出行史、没有接触过高风险人员、没有出现发热等症状的市民不要焦虑,有序参加核酸检测。避免不必要的扎堆,最大限度降低疫情传播风险。越有序效率越高,越理性风险越低。下列选项中适合用作这段文字题目的是( )',
