  '下列句子排列顺序最恰当的一组是( )。1这些小店经济、网店经济是就业岗位的重要来源,是人间的烟火气,和"高大上"一样,是中国的生机2比如对于中小企业,可以出台更多的减税措施以对冲税负压力3家网店的存在不仅能够解决就业,很多时候还意味着的是一家人的生计和收入来源4面对这一部分群体,征税补税固然必要, 但不妨也可以更"柔性"些5帮助企业减轻现金流压力的同时,也给行业整改和恢复留出时间和空间6再比如针对不同企业的不同情况,不妨可以补缴税款分期或缓期缴纳',
