  '下列各句中,有语病的一句是( )。',
  null,
  '{"A":"以往的研究立足东北亚不同区域石制品技术的笼统对比,提出了此类技术的扩散路线,但缺乏以人类行为决策为基础的详细技术对比。","B":"超低利率下的新周期中,如何緩解社会结构化问题,遏制社会阶层进一步固化,是摆在西方发达国家的政策制定者面前的重要课题。","C":"从剧院导览到文化市集,向市民敞开的不仅有剧场的正门,还有文化广场主体建筑周围的多个户外场地,让艺术更加融入城市空间,人人都能享有品质生活。","D":"在卫生信息交流方面,中国有很多宝费的经验可以与世界分享,尤其是中国在医疗保健方面取得的惊人成就。"}'::jsonb,
