  '文字-637',
  '文字-637',
  '虽然新能源车业务出现较大亏损,但并未阻止房地产企业进入新能源汽车领域。许多地产企业家在新能源车领域内频频布局,先后斥巨资入主国能电动车、瑞典超跑公司柯尼塞格、上海卡耐新能源、德国汽车动力工程公司hofer、轮毂电机公司荷兰e-Traction及英国Protean等相关企业,在天津、广州等地建设五大生产基地。某地产首席分析师表示,地产商发展新能源汽车的核心目的仍然还是围绕房地产开发。房企对土地有较大的诉求,通过对汽车产业链的摸索转向多功能用地,从而进行产品多元化开发。目前风口已过,从盈利预期、资产规模的角度,外行想通过发展新能源汽车获得短期回报的可能性很小。下面最能概括文段大意的是:',
