(
  '文字-638',
  '文字-638',
  '存在主义一度是西德人民战后的精神支柱,以海德格尔和萨特为代表的存在主义哲学总是带给人丝丝悲剧性的失落,总是让人们在生与死、悲与喜的极端精神体验中找到生活的方向,特别是萨特与加谬的存在主义哲学由于总是把精神的存在,把人的心理意识,如焦虑、绝望、恐惧等病态的意识同社会存在与个人的现实存在对立起来,并常常引向虚无,这与东德社会主义意识形态所追求的精神理念相去甚远,导致在东德没有官方市场,而且对于一直没有走出战争阴影的东德民众来讲,似乎也不太愿意接受。与此相对,布洛赫的希望哲学像一道曙光照进了东德人民的心中,一度给人们的精神与心灵以抚慰,使人们在建国初期的困难情况下心中充满了希望与喜悦,在文化与精神层面对东德的国家建设给予了支持。下面最适合做本文标题的是:',
  null,
  '{"A":"存在主义要被淘汰","B":"东德人民的\"光\"","C":"希望哲学对东德人民的影响","D":"焦虑等病态意识是否应与社会存在、个人现实存在相对立?"}'::jsonb,
