  '文字-639',
  '我心里明白,通过一个人的言语、观点、行为、同情心和憎恨看到的那个人,根本就不是这个人——在绝大多数情况下,那只不过是某样东西或某个具体人的投影;所有人都如此,在世界面前蒙了七层面纱,隐居在内心深处,活在可以触摸的外表背后。最适合做这段文字标题的是:',
  null,
