(
  '文字-640',
  '文字-640',
  '硝酸铵是一种无色无味的晶体,易溶于水。硝酸铵用途广泛,可用作化肥和制造炸药等。在用作化肥时,硝酸铵往往以颗粒状存在,遇到水分能快速溶解,从而释放出植物生长需要的养料--氢。硝酸铵也能作为炸药原料。虽然在常温下稳定、不易燃,但它也是一种氧化剂,遇见可燃物着火时,能助长火势,并能与可燃物混合发生反应而爆炸。硝酸铵在受热或受到剧烈撞击时也会爆炸。根据受热温度不同,分解产物也不同;温度越高,有关反应越迅速,到400摄氏度以上时它会剧烈分解并发生爆炸。硝酸铵与还原剂、有机物、易燃物等混合时,也可形成爆炸性混合物。所以,硝酸铵务必储存在阴凉、干燥、通风良好的库房,远离火种、热源。根据本文内容,下面推断正确的是:',
  null,
  '{"A":"因为硝酸铵是晶体,所以容易溶于水","B":"由于硝酸铵是氧化剂,所以硝酸铵必须远离火种和热源","C":"硝酸铵用作化肥时,即使不溶解于水也能释放出植物养料氮","D":"即使当温度达到400度以上,硝酸铵也能够足够稳定、不易燃"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '逐项对照原文，B项“由于硝酸铵是氧化剂,所以硝酸铵必须远离火种和热源”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择B。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
