(
  '文字-641',
  '文字-641',
  '国家对良种母牛繁育实施补贴,是为了从源头提高奶制品的质量,国家对规模牧场建设的财政支持,也是为了避免分散养殖所带来的质量隐患。从这两点来看,国家对奶业的政策扶持,其初衷是好的,事实上也产生了一定的效果,我国近年来奶业安全相比2008年之前,确实有了一定幅度的提高。可是,即便是奶业安全有所好转的近几年,我国奶业的安全事故仍然是频频出现,这显然与我国对奶业安全巨额资金扶持是不相称的,也可以说,从经济学的角度看,依赖政策扶持对奶业安全所产生的正向作用,其边际效应是递减的。这段文字意在说明:',
  null,
  '{"A":"政策的扶持和补贴从源头上提高了奶制品质量。","B":"我国奶业安全环境和奶制品质量都有较大改善。","C":"仅依赖政府的财政扶持无法根治奶业安全问题。","D":"政策扶持越多,对奶业安全产生的边际效应越明显。"}'::jsonb,
