  '文字-642',
  '文字-642',
  '冬眠是动物应对恶劣环境的一种策略。有的鱼是会冬眠的,而且冬眠看似与正常的睡觉并无二致。但鱼类睡觉时,鳃也会轻轻开合扇动。而进入冬眠的鱼鳃几乎不动,完全处于麻痹状态。除了呼吸,冬眠动物的体温、心跳等生命指征也都降到极低的水平,新陈代谢变得非常缓慢--这就是冬眠与睡觉的本质区别。冬眠的意义在于减少身体内外的生命活动,以挨过环境严酷的时间。如北美洲的普通箱龟,冬眠时甚至几乎完全不呼吸,只靠皮肤吸入少许氧气。此外,冬眠不是"习惯养成",而是遗传基因决定的"天赋"。这种"天赋"还与寿命的长短有联系。冬眠的菊头蝠和同体型的、不冬眠的老鼠相比活得更久。即使在同一物种中比较,依然是冬眠动物的寿命要长很多。下面不属于动物冬眠的特点的是:',
  null,
  '{"A":"几乎完全不呼吸。","B":"体温、心跳等生命指征都降到极低的水平。","C":"新陈代谢变得非常缓慢。","D":"身体几乎完全处于麻痹状态。"}'::jsonb,
