  '文字-643',
  '文字-643',
  '2020年的新冠肺炎疫情对文化行业的影响较大,中小微文化企业压力更大。特别是实体书店,为了应对疫情而闭店,因此错过了能为上半年提供现金流的春节运营高峰。即便恢复营业,无论图书销售,还是举办文化活动,都容易引起人群聚集。严重依赖于面对面交流的实体书店,如今就像一座远离航线的孤岛。图书销量断崖式下滑,高昂的房租及人力成本,大多数书店资金储备只能维持1到3个月。之前生机勃勃的实体书店业遭受重创,较有实力的实体书店停下了市场拓展脚步,而更多的小书店面临生存危局。下面对本文内容理解正确的是:',
  null,
