(
  '文字-644',
  '文字-644',
  '过去二十年,科学家们发现,丰富的人际关系能够为生活带来一系列正能量,例如减少感冒的概率,可能活得更久。对罹患老年痴呆症的人群,人际关系也有积极的作用。患病早期症状细微时,病症确实影响了他们的社交活动;而当症状越来越明显时,减少的社交活动似乎就影响到了患者的大脑。但在持续时间更长的后续研究中,有的参与者在被跟踪六年后才表现出痴呆的症状。研究者的结论简洁清晰:在抵抗痴呆的效果上,社交活动与健身、智力活动的效果是一样的。其他研究也支持了这一结论。美国哈佛大学的一项六年的研究表明,由婚姻状况、志愿活动、与家人及邻居联系等集成的社交活动,能够减缓老年人的记忆衰退。社交活动集成度最低的人群和该指标最高的人群相比较,前者的记忆衰退速度是后者的两倍。上述材料主要讲述了:',
  null,
