  '文字-646',
  '文字-646',
  '文艺生产的庸俗化、娱乐化和商业化背后,其实是对人民情怀的缺失。文艺精品创作必须要树立正确的价值导向,书写"人民的文艺",凸显人民性。有人曾说:"文艺创作方法有一百条、一千条,但最根本、最关键、最牢靠的办法是扎根人民、扎根生活。""扎根人民"不仅意味着人民需要文艺,也意味着文艺需要人民,即创作者要始终把人民的冷暖放在心中,把人民当主角,展现普通劳动者的奋斗状态。坚持人民性,要求文艺工作者善于从生活中发掘普通人的所思所想所盼和笑点泪点痛点,使鲜活的故事真正融入人民心坎里,从人民的伟大实践中实现对美的捕捉、发现和创造。同时,在题材、语言、技巧和手法上大胆探索,出新出彩,多创作人民群众喜闻乐见的作品,增强文艺精品的吸引力、感染力。下面最适合做本文标题的是:',
