  '耐人寻味的是,一方面是矿难频发,另一方面则是长期不景气的煤炭业回暖。随着北方供暖季来临,据国家统计局发布的10月份物价数据,煤炭开采和洗选业价格涨幅较大,环比涨幅9.8%。11月2日,煤炭市场价格"风向标"环渤海动力的煤价格指数(5500大卡)报收607元/吨,连续第18周上涨。它较今年年初的371元/吨上涨了63.61%,反弹可谓迅猛。这段话主要强调:( )',
