  '文字-651',
  '文字-651',
  '作为交通系统的组成部分,桥梁在人类文明的发展和演化中起到了重要作用。随着现代科技的发展以及运输需求的不断增长,大型桥梁(如跨海大桥、大跨度桥梁等)越来越多的出现在人们的视野中,这些桥梁造价动辄几亿甚至几十亿元,在交通、军事和社会生活等方面有着重要的战略意义。然而,桥梁在建造和使用过程中,由于受到环境、有害物质的侵蚀,车辆、风、地震、疲劳、人为因素等作用,以及材料自身性能的不断退化,导致结构各部分在远没有达到设计年限前就产生不同程度的损伤和劣化。这些损伤如果不能及时得到检测和维修,轻则影响行车安全和缩短桥梁使用寿命,重则导致桥梁突然破坏和倒塌。根据本文内容,下面推断正确的是:',
  null,
  '{"A":"桥梁在交通系统的作用重于船舶","B":"即使耗资巨大的桥梁也需要及时检测维修","C":"大型桥梁相对使用年限更久","D":"桥梁突然破坏和倒塌是由于施工方的不负责"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '逐项对照原文，B项“即使耗资巨大的桥梁也需要及时检测维修”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择B。',
  '把每个选项定位回原文，重点检查偷换概念、范围扩大和绝对化表述。 本题重点：信息核对-定位原文。',
