(
  '文字-652',
  '文字-652',
  '随着全球人口老龄化,新的消费机会和市场将会出现,年长人士将在未来几年里改变消费和资本市场。多数公司的长期供职营销依然处在早期阶段,这必须有所改变,每家公司都应制定一套策略,来开发年长客户的需要、需求和购买力。公司需要制定针对年长消费者的策略,而确定新机会和市场只是第一步。领导者和员工还必须重新审视自己对这一人群的"了解",避免发出带有年龄歧视的过时信息。例如,年长消费者不希望被看得低人一等,他们希望自己的需求得到认可,因此,公司可以强调老龄化积极和真实的一面。老龄化人口很多元,答案并不简单,而企业并没有普适性的解决方案。根据本文内容,下面推断正确的是:',
  null,
  '{"A":"金融服务行业仍然应该以迎合年轻人群的需求为主。","B":"公司可以利用媒体和广告的力量展示出年长人士的积极面貌。","C":"我们应该鼓励企业利用\"抗衰老\"这个词来介绍护肤品或化妆品。","D":"各行各业已经掌握了年长消费者的各种需求并知道如何满足这些需求。"}'::jsonb,
  '{}'::jsonb,
  4,
  'B',
  '逐项对照原文，B项“公司可以利用媒体和广告的力量展示出年长人士的积极面貌。”能够由文段信息直接推出，其他选项存在偷换概念、范围扩大或无中生有。因此选择B。',
