(
  '文字-653',
  '文字-653',
  '在日常表达中,"你"是用的最为频繁的词语之一。除了作为第二人称代词,表达谈话的对象,"你"还可以用以泛指任何人。研究发现在许多情况下人们更喜欢使用"你"表示泛化意义,这种"泛化的你"可以延伸其含义,并使其普遍化。这种情况包括:表述日常行为规范,表达和审视负面经历,得到超越自我的见解,分享自己的人生经验等。人们总希望能够解释事物是如何发展的,也总在不断地追寻生命的意义。当人们从负面经历中寻找意义时,使用"你"这个词可以让人跳出来审视这段经历。下面最适合本文的标题是:',
  null,
  '{"A":"当我说\"你\"时,可能是指大家","B":"词语\"你\"的双重含义","C":"泛化的你,有利于反思生命","D":"将\"你\"普遍化,跳出当下情境"}'::jsonb,
