(
  '文字-660',
  '文字-660',
  '人类能在地球上生活多久?首先取决于太阳。根据近代天文学家的理论,太阳持续而稳定地向地球提供光和热,至少还将持续40亿年。而后,太阳将逐渐膨胀而演化为红巨星,最后将地球完全吞噬。所以,研究人类在地球上持续生存和发展的问题,至少要以人类能在地球上持续生存40亿年为奋斗目标。但是人类面临的真正威胁,却是来自人类本身。近400年来,科学、技术以及工业、农业的发展,就远远超过自有人类历史以来的400万年间的成就。与此同时,也消耗了大大超过在400万年间人类所消耗的资源总量!所以,人类的生存和发展的问题,归根结底将取决于地球上的资源能在多少年内维持人类的正常生活。因此,真正值得忧虑的,是人能否控制人类自身。根本本文观点,下列观点正确的是:',
  null,
  '{"A":"太阳能够为地球持续提供40亿年的光和热,因此至少在40亿年内人类仍然可以生存下去。","B":"科学、技术以及工业、农业等的发展会使地球的资源越来越少。","C":"人类还能在地球上生活多久既取决于地球的外在环境,也取决于地球所能持续提供的资源。","D":"\"人能否控制人类自身\"指的是人能不能减少使用地球有限的不可再生资源。"}'::jsonb,
