(
  '文字-664',
  '文字-664',
  '吸毒为何成瘾?惩罚学说认为吸毒病人表现出的强迫用药和强烈的心瘾是害怕停用毒品后产生难以忍受的痛苦。病理性记忆学说认为吸毒者对毒品引起的奖赏和惩罚效应形成了难以忘记的异常记忆。大脑奖赏学说认为人在吸毒后可以获得如同饥饿时吃饱饭、焦渴时饮足水的欣快感和满足感一样的感觉,这些生理感觉是人类在生存竞争和进化中所获得的自然机理,是为了让种群延续和扩大。这种感受如同奖赏机制,鼓励吸毒者重复行为。奖赏学说的提出依赖于科学技术手段对大脑的研究。例如,利用现代脑成像技术发现人的大脑中存在奖赏通路。当电刺激奖赏通路时,机体会出现愉快效果,但其强度较自然奖赏刺激强度大。但奖赏学说也不能完全解释吸毒成瘾。有关"大脑奖赏学说",下面描述正确的是:',
  null,
