  '文字-666',
  '文字-666',
  '每年都有成千上万的人因车祸丧生。车能够诱导出人们最恶劣的品质,当人坐在方向盘后面时,他的车就成了他个性的延展。而令人吃惊的是,一些国家对驾驶者竟格外宽容,交通法也出奇的宽松。是时候制定一系列的措施来减少这种死亡了,例如使驾驶考试难于它原本的操作,对司机每三年进行一次测验,驾驶者年龄不得小于22岁,对车速进行限制,检查高速道路的安全等等,这样才可能减少交通伤亡。下列词语与"延展"的意义最接近的是:',
