(
  '文字-667',
  '文字-667',
  '安静并不是工作的理想状态,处在安静环境中的人,工作效果有可能比听音乐的同事差。研究显示,周围有一些声音可以帮助我们集中注意力,这些声音使我们不再关注同事的咳嗽声或者时不时的关门声,也不容易被转移注意力。音乐能帮助我们集中注意力,但不是所有音乐都可以做到这点。当你需要集中精力时就去听游戏配乐。这种音乐可以刺激你的感官,同时又不会起到干扰作用。事实上,这种音乐会把人们更快地引向任务。但排行榜上的单曲更可能让你跟着哼唱,而不是帮助你解决问题。下面最适合本文的标题是:',
  null,
  '{"A":"听对音乐,工作更好","B":"想集中注意力?听点音乐吧","C":"最好的工作环境需要音乐","D":"排除干扰,加点音乐"}'::jsonb,
