  720,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-672',
  '文字-672',
  '根据世界卫生组织的数据,全球各年龄段共超过300万人正饱受抑郁症的煎熬。目前,抑郁症已被视为全球主要疾病,人们也感受到抑郁症带来的问题愈发严重。科学家们已经证实抑郁症与脑内白质的结构有关联,白质区域负责连接灰质,确保我们能恰如其分地处理情绪与想法。爱丁堡大学的研究人员们对来自英国生物数据库3461名成人的数据进行分析,是迄今为止最大的单样本库。研究人员采用了一种被称为"弥散张量成像"的技术来比对不同个体的脑内白质区域,这项技术基于磁共振成象(MRI),使研究学者可以更好地构建脑内纤维模型。扫描结果显示具有抑郁症状的患者脑内白质的完整性(即白质质量)显著下降,而无抑郁症状的人,则并没有白质异常。研究人员表示,这种结果可能是由抑郁症引起脑内活动模式差异导致的,但若要对其内在机制下定论,还为时尚早。上述研究与以往研究的不同是:',
  null,
  '{"A":"采用\"弥散张量成像\"的技术。","B":"采用了最大的单样本库。","C":"构建了脑内纤维模型。","D":"发现了抑郁症与脑内白质的作用机制。"}'::jsonb,
  '{}'::jsonb,
  4,
  'A',
  '梳理文段的中心句与行文重点后，A项“采用"弥散张量成像"的技术。”对核心意思概括最全面；其他选项或只对应局部信息，或存在过度推断。因此选择A。',
  '先看提问，再找中心句；用关联词、对策词和行文脉络排除片面项。 本题重点：做题辅助-主题词。',
  '提高',
  '文字推理',
  '中心理解题',
  '["做题辅助-主题词"]'::jsonb,
  '北森言语理解',
  null,
  721,
  '{"kind":"verbal","analysisSource":"依据讲义补充","duplicateOccurrences":[]}'::jsonb
),
(
  '文字-673',
  '文字-673',
  '人是怎样不迷路的?科学家研究发现建立记忆的过程和大脑中的"海马"脑区密切相关。后来在大鼠的海马中植入了一个记录电极,发现了记忆体系的组成部分。他们在纷乱错杂的神经信号中分离出了一组独特信号,来自一类以发放电信号方式实现功能的神经元。这类神经元被称为"位置细胞"。位置细胞的活跃程度只和大鼠所处的位置有关系,总数量并不多,但是通过不同组合可包含海量的信息。同时,位置细胞能和海马中其他的细胞合作,将那些来自大鼠感觉器官当时所处环境的特征信息,与过往记录到的位置特征信息比对,形成空间位置记忆。空间位置记忆既可以随着时间推移而遗忘,也可以通过反复训练来加强,乃至终身保留。基于原文,我们可以推论出:',
  null,
  '{"A":"如果将大鼠的\"海马\"切除,它将无法走路。","B":"空间位置记忆能力主要受练习效应的影响,通过练习,可以得到大幅度地提升。","C":"空间位置记忆短时间内不会被遗忘。","D":"大鼠形成空间位置记忆,离不开感觉器官的参与。"}'::jsonb,
  '{}'::jsonb,
