  '文字-674',
  '文字-674',
  '对中国现代小说形式的评价,离不开五四初期的语言变革对中国现代小说由传统向现代转换的决定性意义这个"基点"。五四初期对各种语言资源的综合,推动了中国现代小说写实性、抒情性、象征性等原则的确立,孕育了中国现代小说的诗化、散文化等美学风格。"小说语言的政治化"带来的"标语口号"、"概述"、"讽刺"、"直语"等特点,同时也给小说文体带来"审美危机"。对政治语言的反援又使小说发展了限制性语态、隐喻和幽默修辞等文体表现形式。新文化运动从当时的文化发展大目标出发,反对文言文,提倡白话文,完成了白话语言方式的确立,这种历史功绩不能抹杀。而文言文作为文学语言的生命力,并未因白话文的兴起而消失,文言文也同样参与了语言变迁与中国现代文学形式演进的过程。下面哪个词能代替文中的"抹杀",而且保持文章的意义不变?',
