  '文字-682',
  '充电桩,是破解新能源车"里程焦虑",支持整个产业发展的基础性设施,也正因此,新能源汽车充电桩被列为国家7大"新基建"之一。现实中,许多新能源汽车车主常常遭遇"充电难",为了车辆充电费尽周折,与此同时,却有一大批充电桩处于"僵尸"状态,这显然是严重的资源错配和极大的浪费。从"僵尸桩"的成因看,只要能对症下药;解决起来其实也不难。比如,对于骗补问题,只要在补贴策略上作出相应调整,就能弥补漏洞。以上海为例,对于充电桩就从之前的"补建设",改变为"补运营",给运营企业直接提供电费补贴;对于技术含量较低的慢充桩,理当严格进行淘汰,审批和验收上做好把关;对于运营企业"弃桩",只要做好日常监管,第一时间介入处理,完全可以最大限度化解风险。这段文字旨在说明( )。',
