(
  '文字-684',
  '文字-684',
  '要确保对商品过度包装问题的治理收到实际成效,就必须在完善法律与市场化监管手段运用的同频共振方面下足工夫。对于前者,相关职能部门要秉承紧迫感,就商品过度包装顽疾的治理构建一套完善的处罚机制,以法律责任的高压威慑,让商家在过度包装商品方面不敢为。对于后者,要充分运用税收、大幅提高包装处理费等市场化监管手段,进一步对冲商家过度包装商品所获的利益,倒逼其主动放弃过度包装商品的行为。当然,治理商品过度包装顽疾是一项系统工程,在让法律和市场化监管手段同频共振之余,消费者也应保持简约消费、绿色消费理性,主动摒弃对商品过度包装的追求,从而以理性成熟的消费观,相向而行地为治理商品过度包装顽疾作出积极贡献。这段文字旨在说明( )。',
  null,
  '{"A":"治理过度包装,法律、市场手段和消费者要共同发力","B":"法律和市场监管手段要在治理商品过度包装上下工夫","C":"商品过度包装造成不必要浪费必须坚决予以治理","D":"要用法律手段高压震慑商家过度包装商品的行为"}'::jsonb,
