  '文字-689',
  '文字-689',
  '由于缺乏准确的考古和文献证据,古代遗址、名人故里等争夺时有发生。平心而论,此种争夺并非没有好处。"正统"之位背后对传统文化和当地历史的自豪感与归属感,无论是"杏花村"还是"公祭黄帝",各地都会寻找依据,甚至对薄公堂,其结果是各种经典被广泛讨论,原本逐渐被淡忘的传统文化得到舆论关切。地方政府也会重修遗址或新建博物馆,一定程度上促进地方文化传播乃至唤醒中华民族的文化认同。对这段文字理解不正确的是( )。',
