(
  '文字-691',
  '文字-691',
  '现代航空母舰的主舰体指的是航空母舰飞行甲板以下的舰体部分。在纵向看,航母主舰体按照垂直方向可分为若干层空间。以美国"小鹰"级航空母舰为例,从舰底龙骨到飞行甲板共有10层:从下往上第1层为燃油舱和淡水舱:第2至4层为主机胎、锅炉舱、副机舱以及舰载机的弹药舱;第5层主要为土兵住舱、食品舱和行政人员办公室;第6层为各种食堂、住舱;第7层为飞机修理库;第8-10层大部分为机库,还有值班室和飞行员食堂等。一般来说,航空母舰的甲板或平台之间(即每一层)的高度为2.4到2.8米,主舰体中最大的就是机库,这也是航母最高大的舱室。舰载机不同,机库的高度略有不同。有的机库要占去2至3层甲板的空间。根据这段文字下列说法中错误的是( )。',
