(
  '文字-692',
  '文字-692',
  '据之前的媒体统计,我国高校博物馆总量已有400多家,有更多学校在新建、改建和扩建场馆,甚至是打造集群。不过,与此数字形成对比的还有平均每馆五万人次的年观众量,以及70%以上机构年举办临时展览数的不足。可作为参照的是,2019年故宫博物院的年参观量为1933万人次,高校博物馆社会影响力有限的现实仍摆在我们眼前。如下这样的情形人们也许并不陌生:许多大学生在校4年乃至更多年,甚至许多大学教师在一所学校工作生活了近一生时间,对自己每天路过的藏品楼,竟从未能得其门而入,有的连听说都没听说过,这就不是这些人个人的悲哀了。从这个层面,高校博物馆应该更多被"看到",便之成为人文学科的实验室,深化既有的知识,启迪新的发现。这尤为重要。这段文字中,"被看到"指的是( )。',
  null,
  '{"A":"投放广告,使公众知道","B":"对公众开放,扩大社会影响力","C":"对标故宫博物院","D":"进一步修葺以吸引公众进入参观"}'::jsonb,
  '{}'::jsonb,
