(
  '文字-693',
  '文字-693',
  '对于受到新冠肺炎疫情影响且正处于恢复期的小微企业和个体工商户来说,支付结算降费措施可谓"及时雨",小微企业和个体工商户是我国经济和社会发展的重要基础,事关上亿人就业稳固,事关百姓民生福祉。截至今年4月末,我国小微企业总数超过4400万户,个体工商户超过9500万户。数量众多的小微企业和个体工商户有着较大的支付结算需求,与大企业相比,他们对支付结算费用的变化更为敏感。正是看到小微企业和个体工商户的实际需求。此次降费措施直击"痛点"、聚焦的都是小微企业和个体工商户降费呼声高、使用频繁的基础支付服务。初步测算,此次推出的全部降费措施实施后,预计每年可以为市场主体社会公众减少手续费支出约240亿元,其中惠及小微企业、个体工南户超过160亿元。下列选项中适合用作这段文字题目的是( )。',
