  '文字-695',
  '文字-695',
  '在互联网浪潮中滋生的"网红经济",虽然改变了传统产业的既有模式,但也摆脱不了新兴产业的喧器与浮躁。从芙蓉姐姐到网络主播,从淘宝店主到微博段子手,网红生命周期短、盈利能力弱等短板始终成为行业发展过程中的"硬伤"。更有甚者指出,目前还难谈盈利的网红行业,注定是一场虚假繁荣的游戏。对这段文字的陈述不正确的是( )。',
