  '文字-700',
  '当前,隔代抚育已经成为一种普遍的社会现象,对其社会影响当有充分认识和周密安排,早些年,农村隔代抚育带来的社会问题就曾引起了广泛关注。那些父母长期外出务工,被托付给祖父母辈隔代抚养的孩子们,部分存在任性、冷漠、内向。孤独等性格缺陷和心理障碍。这些孩子因在成长关键阶段失去父母管教,很容易受到社会不良诱因而做出违背道德甚至法律的事情,形成所谓的"留守儿童"问题。城市里的隔代抚育,情况虽与农村不尽相同,但缺乏成长过程中的"关键一环",也难免会给孩子的性格形成和心理发育留下长期阴影。在这段文字中"关键一环"指的是( )。',
