  '去年第18号台风"圆规"10月13日15时30分在海南省琼海市博鳌镇沿海登陆,登陆时最大风力12级(33米/秒)。"圆规"登陆后,强度逐渐减弱,将先后穿过万宁、陵水、琼中、保亭、五指山等市县,于13日下半夜移入北部湾,然后趋向越南北部。下列选项中适合用作这段文字题目的是( )。',
