(
  '文字-702',
  '文字-702',
  '蚯蚓对地球上几乎所有生物都有着重要作用,它们把落叶拉进土壤并消化,使之成为富饶的表层土。每年,有350亿吨的植物叶片被蚯蚓和其他土壤生物处理。然而,问题在于有些植物毒性非常大,而所有植物为了防止被食草动物吃掉,都演化出了一些有毒物质,这些物质即使在落叶之后依然存在毒性。不过,蚯蚓的肠道中有一套能够中和植物中多酚的分子,多酚让植物呈现不同颜色、起到抗氧化剂的作用,并防止植物不被食草动物吃掉。对这段文字理解正确的是( )。',
