  '{"A":"如果没有蚯蚓其他生物将无法生存","B":"肠道中的特殊分子使蚯蚓抵抗所有有毒物质","C":"一块地里蚯蚓越多长得庄稼越好","D":"对蚯蚓的研究有助于医学上研制新的解毒药物"}'::jsonb,
