  '文字-703',
  '文字-703',
  '电影评分网站上大部分评分与评论,并非来自专业评论人。由于参与者多为普通观众,评分与评论通常渗透着评价者个人的生活感悟和审美趣味。甚至有部分评论者通过打分的行为,获得一种反权威、反资本的想象姿态,这就不可避免地会出现在偏见的基础上滥用评价权利的情况。对这段文字的理解不恰当的是( )。',
