  '文字-704',
  '文字-704',
  '今年上半年,笔者所在的心理教研室进行了一项抗挫能力测试,随机抽取大学一二三年级学生各100人进行调查,问卷从正反两方面设计30个对学生心理有直接影响的问题。结果显示,心理承受能力低,常有挫折感的占7%;心理承受能力一般,虽能承受一些压力,但遇到大的打击,就容易产生心理危机的占41%;心理承受能力强,能在各种艰苦环境里保持旺盛斗志的占52%。这些数据说明有近半数学生相对容易产生心理健康问题,如果不加以疏导、提高其抗挫能力,就有可能发生悲剧。也可以看出,加强大学生的心理健康教育非常重要和必要。下列选项中适合用作这段文字题目的是( )。',
