  '文字-707',
  '文字-707',
  '研究人员说,人们遭遇自己不喜欢、不认同的信息后,会在某个程度上接受其真实性,但这类信息严重伤害到他们的自尊,从而危及自己的身份认同。学者认为,危及身份认同的言论会对个人产生严重的挑战,从而形成敌对心态。于是他们会想尽办法寻找其他信息,反制刚接触到的新信息。对以上文字叙述正确的是( )。',
