  '文字-709',
  '文字-709',
  '煤炭、天然气、石油等化石能源最终将会枯遇,使得人类未来的命运聚焦在寻找更持久的清洁能源上,海水中大量蕴新的同位素氘和氚,在聚变成氨原子的过程中能够释放出的巨大能量,与太阳产生光和热的过程相似。如果人类掌握了核聚变,将拥有可使用超十亿年的清洁能源。因此受控热核聚变实验装置被人们称为"人造太阳",是地球寻找清洁能源的希望。这段文字主要阐述了( )。',
