  '文字-710',
  '犀鸟是大中型攀禽,喜欢吃榕树果实,雌雄基本同色,仅有细微的形态差异,外观以黑色。白色、棕色为主,犀鸟最大的特点是有着巨大的喙,也就是有个大嘴,有些种类的喙上边还有中空的盔突,会形成声音的共鸣腔,因此声音粗而低沉。我国仅在云南、广西和西分布着5种犀鸟,分别是冠斑犀鸟、双角犀鸟、花冠皱盔犀鸟、白喉犀鸟和棕颈犀鸟。它们的分布范围极为狭窄。以云南为例,仅栖息在西双版纳州和德宏州的局部森林中,其中,在德宏州盈江县洪崩河附近分布有3种犀鸟,种群比较稳定。根据这段文字下列说法中错误的是( )。',
