  '文字-711',
  '文字-711',
  '近日,4.22特大成品油走私案移送海南省人民检察院第一分院审查起诉,该案是中国海警局直属第四局成功破获的特大成品油走私案,共查获走私成品油母船1艘、购买走私成品油的渔船4艘,抓获涉案人员21人,现场查获成品油约4730吨。根据掌握的线索,中国海警局直属第四局执法员在文昌市东部海域查获1艘涉嫌载有大量走私成品油的船舶。海警执法员对船上人员进行控制,对嫌疑人进行突击审讯,顺滕摸瓜将购买走私成品油的渔船查获。下列选项中适合用作这段文字题目的是( )。',
