  '文字-713',
  '研究团队获取的实测水质参数涉及124个封闭湖泊,总面积为24570平方公里,占青藏高原湖泊总面积的53%。通过对水温、盐度、pH、叶绿素-a、蓝绿藻、溶解氧、荧光溶解有机质、浊度和透明度的分析发现:青藏高原淡水湖、盐湖皆有分布,目前绝大部分处于非淡水状态。湖泊盐度总体南低北高,大多数湖泊表现出碱性特征,营养化程度低,浮游植物和溶解性有机质较少,浊度低,透明度高。湖泊pH值呈现明显的南高北低,湖泊水温呈现随季节波动、随海拔升高而降低的变化,湖水透明度随湖泊面积增加而加深。根据这段文字下列说法中错误的是( )。',
