(
  '文字-715',
  '文字-715',
  '同样都是废旧电池,动力电池与干电池、家用电器电池在现实中的区别待遇,与电池本身所具备的经济价值,以及不同类型电池回收难度,有着很大关系。新能源车的废旧动力电池,在市场上售价过万:废旧干电池的回收价值,则由于当前生活垃圾处理没有专门的电池回收项目,人们通常随意丢弃或混入普通生活垃圾中,面临着回收分拣难度大,回收利用技术复杂、成本较高等诸多问题。但问题是,废旧干电池等对环境污染同样危害巨大,不能因为回收困难或经济价值低,就放弃了对其的回收处理。人们对新能源车废旧动力电池回收的重视,是建设环境友好型、资源节约型社会的题中之意,同时意味着这将是一个长期性的环保举措,需要全社会的共同支持。同样,我们已经呼吁多年,被当成生活垃圾的废旧干电池等的回收处理问题,显然也需要形成硬性制度性机制,不能任由其与生活垃圾一道被随意处置了。这段文字旨在说明( )。',
  null,
  '{"A":"推进电池回收机制是建立环境友好型社会的重中之重","B":"推进干电池回收制度机制需要全社会共同努力","C":"废旧干电池回收存在技术复杂,成本高等问题","D":"废旧干电池回收处理也应建立起制度机制"}'::jsonb,
