  '文字-722',
  '过去几年,移动支付在中国迅猛发展。在大城市,出门不带现金已经成为不少人,尤其是年轻人的新习惯。网上甚至有人开玩笑说,现在连乞丐都不收现金了。中国确实像很多媒体描述的那样,逐渐变成了一个"无现金社会"。移动支付让商家和消费者都感受到了便利,这本身是一件提升交易效率的好事。但在实际中,有部分商家却走向了排斥现金,甚至拒收现金的极端。从服务的角度讲,所有商家都应当尊重客户的合理选择,包括使用现金的选择。除此之外,正如很多权威人士指出的,人民币现金属于法定货币,因此拒绝接受现金甚至可能涉及违法。这段文字表达的主要内容是( )。',
