  '文字-727',
  '文字-727',
  '血小板减少症是慢性肝病患者常见的并发症之一,中国作为肝病大国,具有庞大的患者数量。数据显示,我国乙型肝炎病毒(HBV)和丙型肝炎病毒(HCV)感染者分别有9000万和1000万。与此同时,还有约1.73至3.38亿非酒精性脂防性肝病患者和至少6200万酒精性肝病患者,其中多达700万人患有肝硬化。另据报道,高达78%的肝硬化患者伴随不同程度的血小板减少。当一位慢性肝病患者合并血小板减少症时,他的出血风险会显著增高,继而导致一系列临床有创性检查及治疗无法照常进行,例如肝脏穿刺活检、肝癌介入治疗等,使得临床诊治过程变得相当棘手。由此可见,在需要进行手术或其它有创检查时,CLD相关血小板减少症患者对在短时间内快速提升血小板计数的需求尤为迫切。根据文章,下列说法中错误的是( )。',
  null,
  '{"A":"慢性肝病患者合并血小板减少症时无法进行肝癌介入治疗","B":"我国约有1亿患者感染乙型肝炎或丙型肝炎","C":"有一部分脂肪肝患者同时患有肝硬化","D":"约有22%的肝硬化患者血小板没有减少"}'::jsonb,
  '{}'::jsonb,
