(
  '文字-728',
  '文字-728',
  '任何节日都是民族特性的浓缩,端午时节,万物皆盛,最是奋斗好时光。非奋斗无以明志,非奋斗无以聚识,非奋斗无以偕行。在勇于担当、勇于奋斗、勇于践行中拓展节日的内涵,放大节庆的意义,家国情怀才能落到实处,才能厚植于我们的思想和心灵深处,才能固若磐石,坚不可摧,永不动摇,催人奋进。以奋斗者的特征、以不懈奋斗的姿态,共筑中华民族伟大复兴"中国梦"、共建富强民主文明和谐美丽大家庭,当是厚植家国情怀、体现家国担当最振奋的节日典仪。下列选项中适合用作这段文字题目的是( )。',
