  '文字-732',
  '文字-732',
  '随着技术进步和制造成本降低,协作机器人的市场接受度越来越高,同时竞争也愈发激烈。"从制造商角度出发,我们并不认同低价替代逻辑。依靠单纯的价格战和低价策略并不能推动协作机器人市场的规模持续扩大,用户所重视的''性价比''的概念首先应该是''好用''而不是''便宜''。"曹宇男说。国产协作机器人的发展也验证了这个逻辑。相比著名的元老级厂商一丹麦优傲协作机器人公司(UR),目前销量第一的国产协作机器人在国内售价未达到UR产品的一半,可以说具备了相当明显的价格优势,但其销售额却不及UR的50%。曹宇男认为,坚定押注平台化将成为协作机器人企业发展的破局之路。"平台化的实质在于通过打造易用、安全、灵活可拓展的协作机器人本体产品和操作系统,为用户、集成商、末端执行器和软硬件合作伙伴提供一个''好用''的载体,从而简化协作机器人从技术端到应用端的落地。"这段文字旨在说明( )。',
  null,
