  '文字-733',
  '文字-733',
  '在最新研究中,美国和瑞典科学家从每头猛犸象的臼齿上提取了大约一撮盐大小的样本,并试图提取出DNA,不过,时间已将这些DNA"蹂躏"成数+亿个短小的片段序列。为把这些片段拼在一起,研究人员使用了先前已测序大象和更年轻的猛犸象遗骸的基因组作为参考,随后他们绘制出年长猛犸象和大象之间的关系图,并估算出了它们的基因"分道扬镳"所需时间,得到的这些猛犸象的生活年代与俄罗斯科学家采用的方法相吻合。文段中"分道扬镳"指的是( )',
