(
  '文字-734',
  '文字-734',
  '天鹅座X1是一个X射线双星系统,除了包含能够产生X射线源的致密星之外,还包含一个蓝巨星。自从这个系统在1964年被美国探空火箭首次发现以来,其中致密天体究竟是黑洞还是中子星的问题一直是高能天体物理研究领域的热点。"天鹅座X-1是人类发现的第一个黑洞候选体。上世纪70年代,它刚刚被发现时,地球上最聪明的两个大脑史蒂芬·霍金和基普·索恩为它是否是黑洞打了个赌。90年代,当时的观测证据表明,天鹅座X-1有90%的可能性是一个黑洞,霍金认输了。"苟利军介绍说。尽管霍金已经认输,然而对于这个系统性质直缺乏精确测量。2011年,苟利军研究员和合作者就对这颗黑洞的性质首次做了一次精确测量的尝试。当时得出的结果是:这个黑洞系统与地球的距离为6067光年,质量为14.8倍的太阳质量,并且发现黑洞的视界面在以72%的光速转动。根据这段文字下列说法中错误的是( )。',
  null,
  '{"A":"天鹅座X1包括蓝巨星","B":"光年是一个长度单位,而不是时间单位","C":"天鹅座X1是人类发现的第一个黑洞","D":"天腿座X1是被探空火箭发现的"}'::jsonb,
