  '文字-735',
  '文字-735',
  '磁星是表面磁场强度为地球磁场强度百万亿倍以上的中子星,在活跃期间会出现剧烈烈的X射线爆发,因此很多理论家认为它们也可以产生快速射电暴。2020年4月中旬,SGRJ1935+2154进入了一个新的活跃期,开始出现频繁的X射线爆发,在这种情况下,慧眼卫星调整了既定的观测计划,对这颗磁星进行了长时间定点观测。此外,慧眼卫星基于独特的准直器设计,对X射线暴进行了高精度定位,从而证明了该X射线暴和快速射电暴都来自这颗磁星。这是人类首次确认快速射电暴的起源天体,也是首个起源于银河系内的快速射电暴。根据这段文字下列说法中错误的是( )。',
