  '2月18日,东京奥运会和残奥会组织委员会召开理事会等会议,选出前奥运大臣桥本圣子担任新主席。2月12日,东京奥组委主席森喜朗因丑闻引咎辞职。次日,日本福岛近海区域发生7.3级地震,造成173人受伤,受损建筑物达2300余栋。在距东京奥运会开幕已不足半年之际,地震余震不断、奥组委混乱、新冠肺炎疫情远未消散等等都在考验着菅义伟内阁。下列选项中适合用作这段文字题目的是( )。',
