(
  '文字-737',
  '文字-737',
  '包容的城市是美好的,对外来人口是否包容,是考验一座城市最好的标准。中国有两亿多农民要进城。城市的教育、医疗、养老都面临着严峻的考验。外来人口的融合最先面对的就是公平问题。当各种利益互相勾连时,一切美好的口号都成了空谈,争权夺利的撕咬才是一座城市最真实的嘴脸。这段文字的主要内容是( )。',
