(
  '文字-738',
  '文字-738',
  '近视是屈光不正的一种。当眼在调节放松状态下,平行光线进入眼内,其聚焦在视网膜之前,这导致视网膜上不能形成清晰像,称为近视眼(myopia)。此时检查验光则会提示近视度数,例如通常称近视50度,记录为"-0.50D"在眼调节放松的状态下,外界的平行光进入眼内,其焦点正好落在视网膜上,则形成清晰像,此称为正视;若焦点无法落在视网膜上,则称为非正视,也就是屈光不正。近年来,我国近视发生率呈明显上升趋势,近视已成为影响我国国民尤其是青少年眼健康的重大公共卫生问题。这类最常见的眼科疾病被列为世界三大疾病之一,我国人口近视发生率约为33%,是世界平均水平(占总人口的22%)的1.5倍。关于近视形成的原因,目前还不完全清楚,大多数学者认为近视与多种因素有关,包括遗传因素、环境因素、不良用眼习惯等。根据这段文字下列说法中错误的是( )。',
  null,
  '{"A":"\"非正视\"又被称为\"屈光不正\"","B":"我国近视发生率高于世界平均水平","C":"平行光线进入眼内,不能聚焦在视网膜上的情况被称为\"近视眼\"","D":"近视与遗传因素有关"}'::jsonb,
