  '文字-740',
  '文字-740',
  '面对逐步逼近的大象,我们到底该如何缓解人象冲突,保护野生亚洲象呢?从根本上来讲还是要从象群对栖息地的选择,以及人类活动对其栖息地造成的影响方面来着手。除了保护天然林外,还要通过国家推动,建立以国家公园为主体的自然保护地体系,通过大尺度、跨区域的景观保护规划,通过生态廊道、生态修复等措施,来恢复和增加亚洲象种群的生存空间,以长期维持并保护其种群的健康发展。另外,针对野生亚洲象取食农作物现象,还应该通过生态补偿来解决当地老百姓生计问题。这段文字旨在说明( )',
