(
  '文字-741',
  '文字-741',
  'AED是一种能够自动识别异常心律并给予电击除颤的急救设备,抢救心跳骤停患者的成功率远高于徒手心肺复苏。因其操作简单且内置语音提示,便于非专业人员使用,AED也被誉为"救命神器"。去年7月印发的(健康中国行动(2019- 2030年) )明确提出:"完善公共场所急救设施设备配备标准,在学校、机关、企事业单位和机场、车站、港口客运站、大型商场、电影院等人员密集场所配备急救药品、器材和设施,配备自动体外除颤器(AED)。"在网上搜索"AED",有成功施救的案例,有通俗易懂的视频教程,还有能显示附近AED位置的小程序。这些,体现出公众急救意识的增强、急救体系的完善,映照着全社会对生命安全的高度关注。自现代心肺复苏术逐步创立推广以来,急救挽救了千千万万"不应过早停止的呼吸和心跳",急救体系成为社会文明程度的一个重要标志。有理由相信,在各方携手努力下,我们一定能织好急救之网,更加有力地托举生命安全。下列选项中适合用作这段文字题目的是 ( )。',
  null,
  '{"A":"国家印发通知,要求公共场所配备AED","B":"急救体系已成为现代文明的重要标志","C":"AED操作简单、成功率高,已成为\"救命神器\"","D":"推广AED,织就更完善急救网"}'::jsonb,
