(
  '文字-742',
  '文字-742',
  '巴西圣保罗大学古海洋学家DanPalcu和同事日前在《科学报告》上发表论文指出,Paratethys湖泊从东阿尔卑斯山延伸到现在的哈萨克斯坦,面积超过280万平方千米,比今天的地中海还大。该湖泊曾含有超过177万立方千米的水,是现有淡水湖和咸水湖总含水量的10倍多。但是气候变化导致Paratethys湖泊在其500万年的生命周期中至少4次急剧缩小。790万年至765万年前,水位下降了250米。最严重时,湖泊失去了1/3的水和超过2/3的表面积。这使得湖泊中心盆地的海水盐度急剧上升。研究人员报告称,这些变化消灭了许多水生物种,包括单细胞藻类和其他小型自由漂浮生物。而包括一些软体动物在内的能在咸水中生存的生物,在湿润期湖泊扩张时存活下来,重新繁衍。根据这段文字下列说法中错误的是( )',
